import { C } from '../../shared/constants/colors'
import { ChangeType } from '../../shared/models/file-change'
import { pyLjust, pyStrip } from '../../shared/utils/pystr'
import type { ChangesSummary } from '../../shared/types/changes'
import { out } from '../utils/console-out'
import { ChangeTracker } from '../services/change-tracker.service'

export interface ChangesDrawerWidget {
  updateData(summary: ChangesSummary): void
}

export class ChangesController {
  private drawer: ChangesDrawerWidget | null = null

  constructor(private readonly tracker: ChangeTracker) {
    this.tracker.onChangesUpdated = (summary) => this.onTrackerUpdated(summary)
    if (this.drawer) this.drawer.updateData(this.tracker.getSummary())
  }

  setDrawerWidget(drawer: ChangesDrawerWidget | null): void {
    this.drawer = drawer
    if (this.drawer) {
      try {
        this.drawer.updateData(this.tracker.getSummary())
      } catch {}
    }
  }

  private onTrackerUpdated(summary: ChangesSummary): void {
    if (!this.drawer) return
    try {
      this.drawer.updateData(summary)
    } catch {}
  }

  async acceptAll(): Promise<string[]> {
    return await this.tracker.acceptAll()
  }

  async rejectAll(): Promise<string[]> {
    return await this.tracker.rejectAll()
  }

  async acceptFile(relPath: string): Promise<boolean> {
    return await this.tracker.acceptFile(relPath)
  }

  async rejectFile(relPath: string): Promise<boolean> {
    return await this.tracker.rejectFile(relPath)
  }

  getSummary(): ChangesSummary {
    return this.tracker.getSummary()
  }

  printCliDetails(): void {
    const summary = this.tracker.getSummary()
    const changes = summary.changes
    const reads = summary.files_read

    out(`\n${C.BOLD}Pending Changes Review (${changes.length} files)${C.RESET}`)
    out(`${C.GRAY}${'-'.repeat(65)}${C.RESET}`)
    if (changes.length === 0) {
      out(`  ${C.DIM}No pending changes.${C.RESET}`)
    } else {
      for (const c of changes) {
        const ctype = c.change_type ?? 'Modified'
        const path = c.path ?? ''
        const timestamp = c.timestamp ?? ''
        const t = timestamp.includes(' ') ? (timestamp.split(' ').at(-1) ?? '') : timestamp
        const col =
          ctype === ChangeType.ADDED
            ? C.GREEN
            : ctype === ChangeType.MODIFIED
              ? C.BLUE
              : ctype === ChangeType.DELETED
                ? C.RED
                : C.MAGENTA
        out(
          `  ${col}[${pyLjust(ctype, 15)}]${C.RESET} ${C.BOLD}${pyLjust(path, 35)}${C.RESET} ` +
            `${C.DIM}${t}${C.RESET}`
        )
      }
    }

    if (reads.length > 0) {
      const listed = reads
        .slice(0, 10)
        .map((r) => r.path)
        .join(', ')
      out(
        `\n${C.DIM}Files read (${reads.length}): ${listed}${reads.length > 10 ? ' ...' : ''}${C.RESET}`
      )
    }
    out(`${C.GRAY}${'-'.repeat(65)}${C.RESET}\n`)
  }

  async handleCliCommand(cmd: string): Promise<'accepted' | 'rejected' | 'viewed' | null> {
    const c = pyStrip(cmd).toLowerCase()
    if (c === '/accept' || c === '/accept_all' || c === 'accept') {
      const accepted = await this.acceptAll()
      out(
        `\n  ${C.GREEN}✓ Accepted all pending changes (${accepted.length} files kept).${C.RESET}\n`
      )
      return 'accepted'
    }
    if (c === '/reject' || c === '/reject_all' || c === 'reject') {
      const rejected = await this.rejectAll()
      out(
        `\n  ${C.RED}✕ Rejected all pending changes (${rejected.length} files restored to ` +
          `original state).${C.RESET}\n`
      )
      return 'rejected'
    }
    if (c === '/changes' || c === '/pending' || c === 'changes') {
      this.printCliDetails()
      return 'viewed'
    }
    return null
  }
}

import type { ThinkingConfig } from '@google/genai'
import { resolve } from 'path'
import { EffortLevel } from '../../shared/models/effort-level'
import { EffortMapper } from '../services/effort-mapper.service'
import { CatalogClient, ModelCatalog } from '../services/model-catalog.service'
import { SettingsStore } from '../storage/settings-store.service'

export type ModelListener = (model: string, effort: EffortLevel) => void

export class ModelController {
  readonly root: string
  readonly catalog: ModelCatalog
  readonly store: SettingsStore
  private readonly mapper: typeof EffortMapper = EffortMapper

  currentModel!: string
  currentEffort!: EffortLevel

  private listeners: ModelListener[] = []

  private constructor(root: string, client: CatalogClient | null) {
    this.root = resolve(root)
    this.catalog = ModelCatalog.getInstance(client)
    this.store = new SettingsStore(this.root)
  }

  static async create(root: string, client: CatalogClient | null = null): Promise<ModelController> {
    const controller = new ModelController(root, client)
    controller.currentModel = await controller.store.getModel()
    controller.currentEffort = await controller.store.getEffortLevel()
    return controller
  }

  addListener(callback: ModelListener): void {
    if (!this.listeners.includes(callback)) this.listeners.push(callback)
  }

  private notify(): void {
    for (const listener of this.listeners) {
      try {
        listener(this.currentModel, this.currentEffort)
      } catch {}
    }
  }

  async selectModel(modelId: string | null | undefined): Promise<void> {
    if (!modelId) return
    this.currentModel = String(modelId).trim()
    await this.store.setModel(this.currentModel)
    this.notify()
  }

  async selectEffortLevel(level: unknown): Promise<void> {
    this.currentEffort = EffortLevel.fromString(level)
    await this.store.setEffortLevel(this.currentEffort)
    this.notify()
  }

  getThinkingConfig(): ThinkingConfig | null {
    return this.mapper.getThinkingConfig(this.currentModel, this.currentEffort)
  }

  /** The config for a candidate model, which may differ from the selected one after a fallback. */
  getThinkingConfigFor(modelId: string): ThinkingConfig | null {
    return this.mapper.getThinkingConfig(modelId, this.currentEffort)
  }

  supportsThinking(modelId?: string | null): boolean {
    const target = modelId || this.currentModel
    return this.mapper.supportsThinking(target)
  }

  getStatusBadge(): string {
    if (this.supportsThinking()) {
      return `${this.currentModel} • ${this.currentEffort.icon} ${this.currentEffort.displayName} Effort`
    }
    return `${this.currentModel} • Standard`
  }
}

import { errorMessage } from '../../shared/utils/exceptions'
import { FileChange, type FileChangeDict } from '../../shared/models/file-change'
import type { FileDiff } from '../../shared/models/file-diff'
import { out } from '../utils/console-out'
import { DiffService } from '../services/diff.service'
import type { ChangeTracker } from '../services/change-tracker.service'

export class ReviewController {
  private readonly tracker: ChangeTracker
  private readonly diffService: DiffService
  private readonly onClose: (() => void) | null
  private panelOpen = false
  private panelClosed = false

  constructor(deps: { tracker: ChangeTracker; diffService: DiffService; onClose?: () => void }) {
    this.tracker = deps.tracker
    this.diffService = deps.diffService
    this.onClose = deps.onClose ?? null
  }

  getPendingChanges(): FileChangeDict[] {
    return this.tracker.getSummary().changes.map((c) => FileChange.fromDict(c).toDict())
  }

  async getFileDiff(relPath: string): Promise<FileDiff | null> {
    const change = this.tracker.pendingChanges.get(relPath)
    if (!change) return null
    return await this.diffService.computeDiff(
      change.path,
      change.change_type,
      change.snapshot_id,
      change.original_exists,
      change.is_binary,
      change.full_path
    )
  }

  async acceptFile(relPath: string): Promise<boolean> {
    return await this.tracker.acceptFile(relPath)
  }

  async rejectFile(relPath: string): Promise<boolean> {
    return await this.tracker.rejectFile(relPath)
  }

  async acceptAll(): Promise<string[]> {
    return await this.tracker.acceptAll()
  }

  async rejectAll(): Promise<string[]> {
    return await this.tracker.rejectAll()
  }

  openReviewPanel(): FileChangeDict[] | null {
    const fileChanges = this.getPendingChanges()
    if (fileChanges.length === 0) return null
    this.panelClosed = false
    this.panelOpen = true
    return fileChanges
  }

  onPanelDestroy(): void {
    if (this.panelClosed) return
    this.panelClosed = true
    this.panelOpen = false
    if (this.onClose) {
      try {
        this.onClose()
      } catch {}
    }
  }

  async safeAcceptFile(path: string): Promise<boolean> {
    try {
      return await this.tracker.acceptFile(path)
    } catch (e) {
      out(`Error accepting file: ${errorMessage(e)}`)
      return false
    }
  }

  async safeRejectFile(path: string): Promise<boolean> {
    try {
      return await this.tracker.rejectFile(path)
    } catch (e) {
      out(`Error rejecting file: ${errorMessage(e)}`)
      return false
    }
  }

  async safeAcceptAll(): Promise<string[]> {
    try {
      return await this.tracker.acceptAll()
    } catch (e) {
      out(`Error accepting all: ${errorMessage(e)}`)
      return []
    }
  }

  async safeRejectAll(): Promise<string[]> {
    try {
      return await this.tracker.rejectAll()
    } catch (e) {
      out(`Error rejecting all: ${errorMessage(e)}`)
      return []
    }
  }

  closeReviewPanel(): void {
    if (!this.panelOpen) return
    this.panelOpen = false
  }
}

import { app, BrowserWindow } from 'electron'
import { electronApp, optimizer } from '@electron-toolkit/utils'
import { AppConstants } from '../shared/constants/app-constants'
import { C } from '../shared/constants/colors'
import { registerIpcHandlers } from './ipc'
import { windowBridge } from './ipc/window.handlers'
import { buildAppMenu } from './menu/app-menu'
import { Agent } from './services/agent.service'
import { log } from './services/logger.service'
import { WindowRuntime } from './services/window-runtime.service'
import { choose } from './utils/choose'
import { onConsoleOutput, out } from './utils/console-out'
import { pyResolve } from './utils/fs-path'
import { envCandidates, loadDotenv, resolveApiKey } from './utils/load-env'
import { createMainWindow } from './windows/main-window'
import { openDatabase, closeDatabase, getDbPath } from './services/database.service'
import { legacyImport, type LegacyImportReport } from './services/legacy-import.service'

function requireApiKey(): string {
  const key = resolveApiKey()
  if (key) return key
  // The key can still be entered from the in-app dialog, so a missing key must not kill the
  // window before it is shown.
  out(
    `${C.YELLOW}No API key found yet.${C.RESET} Use the API key button in the window, or set ` +
      'the GEMINI_API_KEY environment variable and restart.'
  )
  return ''
}

async function createAgent(key: string): Promise<Agent> {
  const readLine = (prompt: string): Promise<string | null> => windowBridge.readLine(prompt)
  return await Agent.create({
    root: pyResolve(process.cwd()),
    model: AppConstants.MODELS[0],
    apiKey: key,
    readLine,
    choose: (title, items, options) => choose(title, items, options, readLine)
  })
}

async function launchWindowUi(
  agent: Agent,
  migration: Promise<LegacyImportReport | null>,
  databaseOk: boolean
): Promise<void> {
  out(
    `\n${C.CYAN}${C.BOLD}+---------------------------------------------------------------+${C.RESET}`
  )
  out(
    `${C.CYAN}${C.BOLD}|  Gemibot Window Mode Active - Real-Time Terminal Mirroring   |${C.RESET}`
  )
  out(
    `${C.CYAN}${C.BOLD}+---------------------------------------------------------------+${C.RESET}`
  )
  out(`  ${C.GRAY}Target Directory :${C.RESET} ${C.GREEN}${pyResolve(process.cwd())}${C.RESET}`)
  out(`  ${C.GRAY}Active Model     :${C.RESET} ${C.YELLOW}${agent.model}${C.RESET}`)
  out(`  ${C.GRAY}Memory Store     :${C.RESET} ${C.DIM}conversation database${C.RESET}`)
  out(`  ${C.GRAY}Conversation DB  :${C.RESET} ${C.DIM}${getDbPath()}${C.RESET}`)
  out(`  ${C.DIM}All prompts, thinking, memory reads, tool calls, and responses${C.RESET}`)
  out(`  ${C.DIM}from the GUI will mirror here in real time for debugging.${C.RESET}\n`)

  // The import runs alongside agent creation; wait for it so the first snapshot already lists
  // the imported conversations, then report it as a pill instead of blocking the window.
  const report = await migration
  const runtime = await WindowRuntime.create(agent, windowBridge)
  windowBridge.bindRuntime(runtime)

  if (!databaseOk) {
    windowBridge.emit({
      kind: 'pill',
      text: 'Database unavailable: this session will not be saved.',
      icon: '⚠️'
    })
  } else if (report !== null) {
    if (report.imported > 0) {
      windowBridge.emit({
        kind: 'pill',
        text: `Imported ${report.imported} session(s) from legacy backups.`,
        icon: '📥'
      })
    }
    if (report.errors.length > 0 || report.warnings.length > 0) {
      windowBridge.emit({
        kind: 'pill',
        text: `Import finished with ${report.warnings.length} warning(s) and ${report.errors.length} error(s). See the console.`,
        icon: '⚠️'
      })
    }
  }
}

function bootstrap(): void {
  electronApp.setAppUserModelId('com.gemibot.prototype')

  // The database is opened once, before anything can write to it.  A failure here leaves the app
  // running in RAM with a visible warning; it never falls back to session files.
  let databaseOk = true
  try {
    openDatabase()
    out(`${C.GREEN}Database initialized at ${getDbPath()}${C.RESET}`)
  } catch (err) {
    databaseOk = false
    out(
      `${C.RED}Failed to initialize database at ${getDbPath()}: ` +
        `${err instanceof Error ? err.message : String(err)}${C.RESET}`
    )
    out(`${C.YELLOW}Continuing without persistence; chats will not be saved.${C.RESET}`)
  }

  const migration: Promise<LegacyImportReport | null> = databaseOk
    ? legacyImport.importExistingSessions(pyResolve(process.cwd())).catch((err) => {
        out(
          `${C.YELLOW}Legacy import warning: ${err instanceof Error ? err.message : String(err)}${C.RESET}`
        )
        return null
      })
    : Promise.resolve(null)

  app.on('browser-window-created', (_, window) => {
    optimizer.watchWindowShortcuts(window)
  })

  registerIpcHandlers()
  buildAppMenu()

  const win = createMainWindow()
  windowBridge.attachWindow(win)
  onConsoleOutput((text, terminator) => {
    windowBridge.emit({ kind: 'console', text: `${text}${terminator}` })
  })

  loadDotenv(envCandidates(app.getAppPath(), app.getPath('userData')))
  const key = requireApiKey()
  void createAgent(key)
    .then((agent) => {
      if (!key) {
        windowBridge.emit({
          kind: 'pill',
          text: 'No API key configured yet. Use the API key button to add one.',
          icon: '🔑'
        })
      }
      return launchWindowUi(agent, migration, databaseOk)
    })
    .catch((err) => {
      out(`Error: ${err instanceof Error ? err.message : String(err)}`)
      log.error(`Window launch failed: ${String(err)}`)
    })

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      const reopened = createMainWindow()
      windowBridge.attachWindow(reopened)
    }
  })

  log.info(`Started ${app.getName()} v${app.getVersion()} on ${process.platform}`)
}

app.whenReady().then(bootstrap).catch((err) => {
  out(`Startup failed: ${err instanceof Error ? err.message : String(err)}`)
  log.error(`Startup failed: ${String(err)}`)
})

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit()
})

app.on('quit', () => {
  closeDatabase()
})

import { BrowserWindow, app, clipboard, dialog, ipcMain, shell } from 'electron'
import { extname, join, resolve } from 'path'
import { IPC } from '../../shared/constants/ipc-channels'
import type { FileDiffDict } from '../../shared/models/file-diff'
import { nowStrftime } from '../../shared/utils/strftime'
import type { ApiKeyInfo, ApiKeyResult } from '../../shared/types/api-key'
import { apiKeyInfo, saveApiKey as saveApiKeyFile } from '../services/api-key.service'
import type {
  TimelineSaveTarget,
  WindowAnswer,
  WindowCommand,
  WindowEvent,
  WindowReply,
  WindowRequest,
  WindowSnapshot
} from '../../shared/types/window'
import type { WindowRuntime, WindowTransport } from '../services/window-runtime.service'
import { out } from '../utils/console-out'

type WithoutId<T> = T extends { id: number } ? Omit<T, 'id'> : never
type RequestKind = WithoutId<WindowRequest>

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/** Runtime gate for commands that name a stored conversation or an export format. */
function isWindowCommand(value: unknown): value is WindowCommand {
  if (!isRecord(value) || typeof value.cmd !== 'string') return false
  switch (value.cmd) {
    case 'conversation-open':
    case 'conversation-delete':
      return typeof value.id === 'string' && value.id.length > 0 && value.id.length <= 200
    case 'conversation-rename':
      return (
        typeof value.id === 'string' &&
        value.id.length > 0 &&
        typeof value.title === 'string' &&
        value.title.trim().length > 0 &&
        value.title.length <= 200
      )
    case 'conversation-export':
      return (
        typeof value.id === 'string' &&
        value.id.length > 0 &&
        (value.format === 'md' || value.format === 'json')
      )
    case 'edit-user':
      return (
        typeof value.text === 'string' &&
        typeof value.rowId === 'number' &&
        Number.isFinite(value.rowId) &&
        (value.cpIdx === null || typeof value.cpIdx === 'number') &&
        (value.dbId === undefined || typeof value.dbId === 'number')
      )
    case 'load-older':
    case 'conversation-new':
    case 'open-data-folder':
      return true
    case 'export-timeline':
      return (
        typeof value.path === 'string' &&
        value.path.length > 0 &&
        typeof value.content === 'string'
      )
  }
  return true
}

export class WindowBridge implements WindowTransport {
  private win: BrowserWindow | null = null
  private ready = false
  private readonly backlog: WindowEvent[] = []
  private nextId = 1
  private readonly pending = new Map<number, (answer: WindowAnswer) => void>()
  private pendingPermission: number | null = null
  private saveTarget: string | null = null
  /** Permission prompts are serialized so a second request cannot orphan the first. */
  private permissionChain: Promise<void> = Promise.resolve()
  private permissionEpoch = 0
  private readonly runtimeReady: Promise<WindowRuntime>
  private readonly resolveRuntime: (runtime: WindowRuntime) => void
  private runtime: WindowRuntime | null = null

  constructor() {
    let resolve!: (runtime: WindowRuntime) => void
    this.runtimeReady = new Promise((r) => {
      resolve = r
    })
    this.resolveRuntime = resolve
  }

  attachWindow(win: BrowserWindow): void {
    this.win = win
    // A reopened window starts before its renderer has asked for the first snapshot.  Anything
    // sent to the old renderer is not recoverable, and dialogs it was showing can never answer.
    this.ready = false
    for (const resolve of this.pending.values()) resolve(null)
    this.pending.clear()
    this.pendingPermission = null
  }

  bindRuntime(runtime: WindowRuntime): void {
    this.runtime = runtime
    this.resolveRuntime(runtime)
  }

  emit(event: WindowEvent): void {
    if (!this.ready || this.win === null || this.win.isDestroyed()) {
      this.backlog.push(event)
      return
    }
    this.win.webContents.send(IPC.WINDOW.EVENT, event)
  }

  private async request(kind: RequestKind): Promise<WindowAnswer> {
    await this.runtimeReady
    if (this.win === null || this.win.isDestroyed()) return null
    const id = this.nextId++
    const full = { ...kind, id } as WindowRequest
    if (full.kind === 'permission') this.pendingPermission = id
    return await new Promise<WindowAnswer>((resolve) => {
      this.pending.set(id, resolve)
      this.win?.webContents.send(IPC.WINDOW.REQUEST, full)
    })
  }

  async readLine(prompt: string): Promise<string | null> {
    const answer = await this.request({ kind: 'read-line', prompt })
    return typeof answer === 'string' ? answer : null
  }

  async permission(tool: string, detail: string): Promise<boolean | 'always'> {
    const epoch = this.permissionEpoch
    let result: boolean | 'always' = false
    const task = this.permissionChain
      .then(async () => {
        // A stop that landed while this request waited means its answer no longer matters.
        if (this.permissionEpoch !== epoch) return
        const answer = await this.request({ kind: 'permission', tool, detail })
        this.pendingPermission = null
        result = answer === 'always' ? 'always' : Boolean(answer)
      })
      .catch(() => {})
    this.permissionChain = task
    await task
    return result
  }

  cancelPermission(): void {
    this.permissionEpoch += 1
    this.emit({ kind: 'cancel-permission' })
    if (this.pendingPermission === null) return
    const id = this.pendingPermission
    this.pendingPermission = null
    this.pending.get(id)?.(false)
    this.pending.delete(id)
  }

  async confirmClear(): Promise<boolean> {
    return Boolean(await this.request({ kind: 'confirm-clear' }))
  }

  async browseDirectory(defaultPath: string, title: string): Promise<string> {
    if (!this.win) return ''
    const result = await dialog.showOpenDialog(this.win, {
      defaultPath,
      title,
      properties: ['openDirectory']
    })
    if (result.canceled) return ''
    return result.filePaths[0] ?? ''
  }

  writeClipboard(text: string): void {
    clipboard.writeText(text)
  }

  async openPath(path: string): Promise<string> {
    return await shell.openPath(path)
  }

  quit(): void {
    this.win?.close()
  }

  getApiKey(): ApiKeyInfo {
    return apiKeyInfo()
  }

  async saveApiKey(key: string): Promise<ApiKeyResult> {
    return this.runtime === null ? await saveApiKeyFile(key) : await this.runtime.applyApiKey(key)
  }

  /** Save dialog for a conversation export; the runtime writes the file itself. */
  async saveConversationFile(defaultName: string, format: 'md' | 'json'): Promise<string | null> {
    if (!this.win) return null
    const result = await dialog.showSaveDialog(this.win, {
      defaultPath: join(app.getPath('documents'), defaultName),
      title: `Export Conversation (${format.toUpperCase()})`,
      filters:
        format === 'json'
          ? [
              { name: 'JSON files', extensions: ['json'] },
              { name: 'All files', extensions: ['*'] }
            ]
          : [
              { name: 'Markdown files', extensions: ['md'] },
              { name: 'All files', extensions: ['*'] }
            ]
    })
    if (result.canceled || !result.filePath) return null
    const extension = extname(result.filePath) === '' ? `.${format}` : ''
    return `${result.filePath}${extension}`
  }

  async openDataFolder(): Promise<void> {
    await shell.openPath(app.getPath('userData'))
  }

  private async takeSnapshot(): Promise<WindowSnapshot> {
    const runtime = await this.runtimeReady
    const snapshot = runtime.snapshot()
    this.ready = true
    for (const event of this.backlog.splice(0, this.backlog.length)) {
      this.emit(event)
    }
    return snapshot
  }

  register(): void {
    ipcMain.handle(IPC.WINDOW.SNAPSHOT, () => this.takeSnapshot())
    ipcMain.on(IPC.WINDOW.REPLY, (_event, answer: WindowReply) => {
      const resolve = this.pending.get(answer.id)
      this.pending.delete(answer.id)
      resolve?.(answer.answer)
    })
    ipcMain.on(IPC.WINDOW.COMMAND, (_event, cmd: unknown) => {
      if (!isWindowCommand(cmd)) return
      if (cmd.cmd === 'export-timeline' && !this.consumeSaveTarget(cmd.path)) {
        out('\n  Timeline export blocked: the path did not come from the save dialog.\n')
        return
      }
      void this.runtimeReady
        .then((runtime) => runtime.dispatch(cmd))
        .catch((error: unknown) => {
          out(`\n  Window command failed: ${error instanceof Error ? error.message : String(error)}\n`)
        })
    })
    ipcMain.handle(IPC.WINDOW.DIFF, async (_event, path: string): Promise<FileDiffDict | null> => {
      const runtime = await this.runtimeReady
      const diff = await runtime.getFileDiff(path)
      return diff ? diff.toDict() : null
    })
    ipcMain.handle(IPC.WINDOW.SAVE_DIALOG, (): Promise<TimelineSaveTarget | null> => {
      return this.pickSaveTarget()
    })
    ipcMain.handle(IPC.API_KEY.GET, () => this.getApiKey())
    ipcMain.handle(IPC.API_KEY.SET, (_event, key: string) => this.saveApiKey(key))
  }

  private async pickSaveTarget(): Promise<TimelineSaveTarget | null> {
    const runtime = await this.runtimeReady
    if (!this.win) return null
    const stamp = nowStrftime('%Y%m%d_%H%M%S')
    const result = await dialog.showSaveDialog(this.win, {
      defaultPath: join(process.cwd(), `gemibot_timeline_${stamp}.md`),
      title: 'Export Conversation Activity Timeline',
      filters: [
        { name: 'Markdown files', extensions: ['md'] },
        { name: 'HTML files', extensions: ['html'] },
        { name: 'All files', extensions: ['*'] }
      ]
    })
    if (result.canceled || !result.filePath) return null
    const path = extname(result.filePath) === '' ? `${result.filePath}.md` : result.filePath
    this.saveTarget = normalizeSavePath(path)
    return { path, ...runtime.exportMeta() }
  }

  private consumeSaveTarget(path: string): boolean {
    if (this.saveTarget === null) return false
    const ok = normalizeSavePath(path) === this.saveTarget
    this.saveTarget = null
    return ok
  }
}

function normalizeSavePath(path: string): string {
  const resolved = resolve(path)
  return process.platform === 'win32' ? resolved.toLowerCase() : resolved
}

