export function pyPlatformSystem(): string {
  if (process.platform === 'win32') return 'Windows'
  if (process.platform === 'darwin') return 'Darwin'
  if (process.platform === 'linux') return 'Linux'
  return process.platform
}

export function pyPlatformRelease(): string {
  const raw = osRelease()
  if (process.platform !== 'win32') return raw
  const [major, , build] = raw.split('.')
  if (major === '10' && Number(build) >= 22000) return '11'
  if (major === '10') return '10'
  return raw
}

export function pyPlatformVersion(): string {
  return process.platform === 'win32' ? osRelease() : osVersion()
}

export function pyPlatformMachine(): string {
  if (process.platform !== 'win32') return osMachine()
  return process.env.PROCESSOR_ARCHITEW6432 || process.env.PROCESSOR_ARCHITECTURE || ''
}

export function pyOsName(): string {
  return process.platform === 'win32' ? 'nt' : 'posix'
}

export interface AgentSystemDeps {
  paths: AgentPaths
  memory: AgentMemory
  modelController(): ModelController | null
}

export class AgentSystem {
  private readonly deps: AgentSystemDeps

  constructor(deps: AgentSystemDeps) {
    this.deps = deps
  }

  tree(root: string, depth = 2, limit = 120): string {
    const lines: string[] = []
    const walk = (directory: string, level: number): void => {
      let entries: { name: string; isFile: boolean; isDir: boolean }[]
      try {
        entries = readdirSync(directory, { withFileTypes: true }).map((entry) => {
          let isFile = false
          let isDir = false
          try {
            const st = statSync(join(directory, entry.name))
            isFile = st.isFile()
            isDir = st.isDirectory()
          } catch {}
          return { name: entry.name, isFile, isDir }
        })
      } catch {
        return
      }
      entries.sort((a, b) => {
        if (a.isFile !== b.isFile) return a.isFile ? 1 : -1
        const an = a.name.toLowerCase()
        const bn = b.name.toLowerCase()
        return an < bn ? -1 : an > bn ? 1 : 0
      })
      for (const entry of entries) {
        if (AppConstants.IGNORED.has(entry.name)) continue
        if (lines.length >= limit) return
        lines.push(`${'  '.repeat(level)}${entry.name}${entry.isDir ? '/' : ''}`)
        if (entry.isDir && level + 1 < depth) walk(join(directory, entry.name), level + 1)
      }
    }
    walk(root, 0)
    if (lines.length >= limit) lines.push('...')
    return lines.join('\n') || '(empty folder)'
  }

  /**
   * Saving effort is the cheapest the app can be, so it trims what is sent as well as how long
   * the model thinks. Without a controller the caller is on the default effort.
   */
  tokenBudget(): { memoryChars: number; keepEntries: number } {
    const saving = this.deps.modelController()?.currentEffort.equals(EffortLevel.SAVING) ?? false
    return saving
      ? {
          memoryChars: AppConstants.SAVING_MEMORY_PROMPT_CHARS,
          keepEntries: AppConstants.SAVING_HISTORY_KEEP_ENTRIES
        }
      : {
          memoryChars: AppConstants.MEMORY_PROMPT_CHARS,
          keepEntries: AppConstants.HISTORY_KEEP_ENTRIES
        }
  }

  async buildSystem(state: AgentState): Promise<string> {
    const parts: string[] = [AppConstants.PERSONA.trim()]
    parts.push(
      'Environment:\n' +
        `- Script: Gemibot.py\n` +
        `- Target Directory: ${state.root}\n` +
        `- Application Root: ${state.appRoot}\n` +
        `- Active Mode: ${state.mode}\n` +
        `- Active Function Suite: ${state.activeFunction}\n` +
        `- Memory: conversation database (loaded automatically)\n` +
        `- Operating system: ${pyPlatformSystem()} ${pyPlatformRelease()}\n` +
        `- Shell commands run with: ${pyOsName() === 'nt' ? 'cmd.exe' : 'sh'}\n` +
        `- Today: ${strftime(new Date(), '%A, %B %d, %Y %I:%M %p')}\n` +
        `- Runtime: Electron ${process.versions.electron ?? 'unknown'} / Node ${process.versions.node} (${process.execPath})\n\n` +
        `Project files (inside Target Directory):\n${this.tree(state.root)}`
    )
    const agents = join(state.root, 'AGENTS.md')
    if (existsSync(agents) && statSync(agents).isFile()) {
      try {
        const { text } = await readText(agents)
        parts.push(`Project instructions (AGENTS.md):\n${clip(text, 8000)}`)
      } catch {}
    }
    const memText = stripForPrompt(await this.deps.memory.readMemoryContent())
    if (memText.trim() !== '') {
      const cap = this.tokenBudget().memoryChars
      const omitted = pyLen(memText) - cap
      const memView =
        omitted > 0
          ? `[... ${pyFormatThousands(omitted)} older characters omitted ...]\n` +
            pySlice(memText, -cap)
          : memText
      parts.push('System Development Progress (from the conversation database):\n' + memView)
    }
    return parts.join('\n\n')
  }

  /** The base prompt plus the digest of any turns the request had to leave out. */
  private systemPrompt(state: AgentState): string {
    const base = state.system ?? ''
    if (!state.historySummary) return base
    return `${base}\n\n${summaryInstruction(state.historySummary)}`
  }

  config(state: AgentState): GenerateContentConfig {
    return this.configFor(state, state.model)
  }

  /**
   * Builds the request for the model that will actually be called, so a ladder fallback gets its
   * own grounding/thinking support instead of inheriting the selected model's configuration.
   */
  configFor(state: AgentState, model: string): GenerateContentConfig {
    if (AppConstants.isGemma(model)) {
      return { systemInstruction: this.systemPrompt(state), automaticFunctionCalling: undefined }
    }

    let tools: ToolDecl[]
    let extraNote: string
    if (state.mode === 'plan') {
      tools = ALL_READ_DECLARATIONS
      extraNote = '\n\n' + AppConstants.PLAN_NOTE.trim()
    } else if (state.mode === 'read') {
      tools = ALL_READ_DECLARATIONS
      extraNote = '\n\n' + AppConstants.READ_NOTE.trim()
    } else {
      tools = FUNCTION_TOOL_MAP[state.activeFunction] ?? ALL_DECLARATIONS
      extraNote = `\n\nActive Function Suite: ${state.activeFunction}`
    }

    const toolObjects: Tool[] = [{ functionDeclarations: toFunctionDeclarations(tools) }]
    if (AppConstants.isGrounding(model)) {
      toolObjects.push({ googleSearch: {} })
    }

    const system = `${this.systemPrompt(state)}${extraNote}`
    const thinkingCfg = this.deps.modelController()?.getThinkingConfigFor(model) ?? null

    return {
      systemInstruction: system,
      tools: toolObjects,
      automaticFunctionCalling: { disable: true },
      thinkingConfig: thinkingCfg ?? undefined
    }
  }

  noToolConfig(state: AgentState): GenerateContentConfig {
    return { systemInstruction: this.systemPrompt(state), automaticFunctionCalling: undefined }
  }

  /**
   * Antigravity agents reject a `systemInstruction` with a 400, so the persona has to travel
   * inside the one user turn the failover is allowed to send.
   */
  singleTurnPrompt(state: AgentState, userPrompt: string): string {
    const system = this.systemPrompt(state).trim()
    if (system === '') return userPrompt
    return `${system}\n\nFollow the instructions above. User request:\n${userPrompt}`
  }
}

import { stat } from 'fs/promises'
import { AppConstants } from '../../shared/constants/app-constants'
import { C } from '../../shared/constants/colors'
import {
  ALL_DECLARATIONS,
  FUNCTION_CATALOG,
  FUNCTION_TOOL_MAP,
  TOOL_ICONS
} from '../../shared/constants/tool-definitions'
import { KeyboardInterrupt, errorMessage } from '../../shared/utils/exceptions'
import { pyFormatThousands } from '../../shared/utils/pyformat'
import { pySlice, pyStr } from '../../shared/utils/pystr'
import { pyTime } from '../../shared/utils/pytime'
import { clip, ensureBro } from '../../shared/utils/text'
import { nowStrftime } from '../../shared/utils/strftime'
import { wrap } from '../../shared/utils/textwrap'
import { out, show } from '../utils/console-out'
import { readText } from '../utils/fs-text'
import { EscMonitor, type KeyPoll } from '../utils/esc-monitor'
import { checkInternet } from '../utils/net-check'
import type { AgentState, Checkpoint, TimelineTurn } from '../models/agent-state'
import type { Content, FunctionCall, Part } from '../models/content'
import { elapsedText, type AgentGenerate } from './agent-generate.service'
import type { AgentMemory } from './agent-memory.service'
import type { AgentPaths } from './agent-paths.service'
import type { ChooseHook } from './agent-session.service'
import type { AgentSettings } from './agent-settings.service'
import type { AgentSystem } from './agent-system.service'
import type { ConversationJournal } from './conversation-journal.service'

export type ToolExecutor = (
  name: string,
  args: Record<string, unknown>
) => Promise<Record<string, unknown>>

export interface AgentTurnDeps {
  state: AgentState
  paths: AgentPaths
  memory: AgentMemory
  system: AgentSystem
  settings: AgentSettings
  generate: AgentGenerate
  execute: ToolExecutor
  choose: ChooseHook
  keyPoll?: KeyPoll
  journal?: ConversationJournal
  effort(): string
  /** Used by sub-agents, whose replies never pass through the window transport. */
  onAssistantReply?: (text: string, meta: string) => void
}

const DESCRIBE_KEYS = ['path', 'output_path', 'db_path', 'pattern', 'command', 'url', 'prompt']

async function isFile(path: string): Promise<boolean> {
  try {
    return (await stat(path)).isFile()
  } catch {
    return false
  }
}

export class AgentTurn {
  constructor(private readonly deps: AgentTurnDeps) {}

  describe(_name: string, args: Record<string, unknown>): string {
    for (const key of DESCRIBE_KEYS) {
      if (key in args) return pySlice(pyStr(args[key]).replaceAll('\n', ' '), 0, 95)
    }
    return ''
  }

  async expandMentions(text: string): Promise<string> {
    const blocks: string[] = []
    for (const match of text.matchAll(/(?<!\S)@(\S+)/g)) {
      const token = match[1]
      try {
        const full = await this.deps.paths.resolve(token)
        if (await isFile(full)) {
          const { text: body } = await readText(full)
          blocks.push(`<file path="${token}">\n${clip(body, 20000)}\n</file>`)
        }
      } catch {}
    }
    if (blocks.length === 0) return text
    out(`  ${C.GRAY}- Attached ${blocks.length} file(s)${C.RESET}`)
    return `${text}\n\nReferenced files:\n${blocks.join('\n')}`
  }

  cancel(): void {
    this.deps.state.cancelRequested = true
    if (this.deps.state.escMonitor) this.deps.state.escMonitor.interrupted = true
  }

  private notifyAssistant(text: string, meta: string): void {
    if (typeof this.deps.onAssistantReply !== 'function') return
    try {
      this.deps.onAssistantReply(text, meta)
    } catch {}
  }

  async turn(userText: string): Promise<void> {
    const state = this.deps.state
    state.lastTurnSucceeded = false
    state.lastTurnError = null
    state.lastTurnCancelled = false

    if (!(await checkInternet())) {
      const msg =
        'Error: No internet connection. Please check your network connection and try again.'
      state.lastTurnError = msg
      out(`\n${C.RED}┃ Error: No internet connection${C.RESET}`)
      if (typeof state.onError === 'function') {
        try {
          state.onError(msg, 'Error: No internet connection (probe failed)')
        } catch {}
      } else {
        await show('Gemibot', msg, C.RED, 'Network Error')
      }
      return
    }

    state.cancelRequested = false
    const mark = state.contents.length
    const undoMark = state.undoStack.length
    state.turnToolLogs = []
    state.turnFileChanges = []
    state.turnTimelineEvents = []

    await this.deps.memory.ensureMemory()
    const memoryBeforeText = await this.deps.memory.readMemoryContent()
    state.system = await this.deps.system.buildSystem(state)
    // Opened after memory is read and rendered into the prompt, so the journal block itself
    // never enters the context, but the banner below and everything after it gets captured.
    await this.deps.journal?.begin(
      { model: state.model, effort: this.deps.effort(), mode: state.mode },
      userText
    )
    out(
      `\n  ${C.GRAY}- ${C.MAGENTA}-' memory_read${C.RESET} ` +
        `${C.DIM}conversation database (${pyFormatThousands(memoryBeforeText.length)} chars loaded)${C.RESET}`
    )

    const checkpoint: Checkpoint = {
      prompt: userText,
      time: nowStrftime('%H:%M:%S'),
      contents_len: mark,
      undo_len: undoMark,
      todos: state.todos.map((t) => ({ ...t })),
      memory_len: memoryBeforeText.length
    }
    state.checkpoints.push(checkpoint)

    const expanded = await this.expandMentions(userText)
    const framedMessage =
      `Active Function Suite: ${state.activeFunction} | Active Mode: ${state.mode}\n` +
      `User Request:\n${expanded}`
    state.pushContent({ role: 'user', parts: [{ text: framedMessage }] })
    const turnStart = pyTime()
    const collectedReplies: string[] = []

    const mon = new EscMonitor(this.deps.keyPoll)
    mon.resume()

    try {
      state.escMonitor = mon
      // The ladder remembers dead models for one turn only, so a rate limit that clears between
      // messages gets another chance at the next one.
      this.deps.generate.beginTurn()
      try {
        let brokeOut = false
        for (let step = 0; step < AppConstants.MAX_STEPS; step++) {
          if (mon.check() || state.cancelRequested) throw new KeyboardInterrupt()
          const response = await this.deps.generate.generate()
          if (mon.check() || state.cancelRequested) throw new KeyboardInterrupt()
          this.deps.generate.countUsage(response)
          const candidate = response.candidates.length > 0 ? response.candidates[0] : null
          const parts = candidate?.content?.parts || []
          if (parts.length === 0) {
            const emptyMsg = 'Bro, I got an empty reply. Try again?'
            this.deps.journal?.record('GemiBot AI', emptyMsg)
            this.notifyAssistant(emptyMsg, '')
            await show('GemiBot AI', emptyMsg, C.GREEN)
            collectedReplies.push(emptyMsg)
            brokeOut = true
            break
          }
          state.pushContent(candidate?.content as Content)
          const thoughts = parts
            .filter((p) => p.thought && p.text)
            .map((p) => p.text as string)
            .join('\n\n')
            .trim()
          if (thoughts) this.deps.journal?.record('Model Thinking', thoughts)
          const text = parts
            .filter((p) => p.text && !p.thought)
            .map((p) => p.text as string)
            .join('')
            .trim()
          const calls = parts
            .filter((p) => p.function_call)
            .map((p) => p.function_call as FunctionCall)
          if (text) {
            const elapsed = `${elapsedText(pyTime() - turnStart)}s`
            const meta = `${state.model} - ${state.activeFunction} - ${elapsed}`
            const displayed = calls.length === 0 ? ensureBro(userText, text) : text
            collectedReplies.push(displayed)
            this.deps.journal?.record(`GemiBot AI (${elapsed})`, displayed)
            this.notifyAssistant(displayed, meta)
            await show('GemiBot AI', displayed, C.GREEN, meta, mon)
          }
          if (calls.length === 0) {
            brokeOut = true
            break
          }
          const results: Part[] = []
          for (const call of calls) {
            if (mon.check() || state.cancelRequested) throw new KeyboardInterrupt()
            const args = { ...(call.args || {}) }
            const icon = TOOL_ICONS[call.name ?? ''] || '-'
            const desc = this.describe(call.name ?? '', args)
            out(`  ${C.GRAY}- ${C.CYAN}${icon} ${call.name}${C.RESET} ${C.DIM}${desc}${C.RESET}`)
            const result = await this.deps.execute(call.name ?? '', args)
            if ('error' in result) {
              const errorText = pyStr(result.error)
              out(`  ${C.GRAY}- ${C.RED}- ${pySlice(errorText, 0, 200)}${C.RESET}`)
              if (typeof state.onToolError === 'function') {
                try {
                  state.onToolError(call.name ?? '', errorText)
                } catch {}
              }
            }
            results.push({
              function_response: { id: call.id ?? null, name: call.name ?? null, response: result }
            })
          }
          state.pushContent({ role: 'user', parts: results })
        }
        if (!brokeOut) {
          out(`\n  ${C.YELLOW}-' Reached the step limit. Tell me to continue, bro.${C.RESET}`)
        }

        // Closing the journal before the v1 interaction log keeps that block below the
        // conversation block instead of being absorbed into part 4.
        await this.deps.journal?.end(brokeOut ? undefined : 'Reached the step limit.')
        await this.deps.memory.logInteraction({
          mode: state.mode,
          activeFunction: state.activeFunction,
          model: state.model,
          userPrompt: userText,
          aiResponses: collectedReplies,
          turnToolLogs: state.turnToolLogs,
          turnFileChanges: state.turnFileChanges
        })
        state.system = await this.deps.system.buildSystem(state)
        out(
          `\n  ${C.GRAY}- ${C.MAGENTA}- memory_log${C.RESET} ` +
            `${C.DIM}Logged prompt, full response, ${state.turnToolLogs.length} tool output(s), ` +
            `and ${state.turnFileChanges.length} file change(s) to the conversation database${C.RESET}`
        )
        const row: TimelineTurn = {
          prompt: userText,
          timestamp: nowStrftime('%H:%M:%S'),
          replies: collectedReplies,
          events: state.turnTimelineEvents.map((e) => ({ ...e })),
          file_changes: state.turnFileChanges.map((c) => ({ ...c }))
        }
        state.timelineHistory.push(row)
        state.lastTurnSucceeded = true
      } finally {
        mon.pause()
      }
    } catch (e) {
      state.truncateContents(mark)
      if (
        state.undoStack.length === undoMark &&
        state.checkpoints.length > 0 &&
        state.checkpoints[state.checkpoints.length - 1] === checkpoint
      )
        state.checkpoints.pop()

      if (e instanceof KeyboardInterrupt) {
        state.lastTurnCancelled = true
        state.lastTurnError = 'Interrupted by user'
        out(`\n  ${C.YELLOW}┃ - Interrupted by user (Esc)${C.RESET}`)
        await this.deps.journal?.end('Interrupted by user (Esc).')
      } else {
        const err = errorMessage(e)
        state.lastTurnError = err
        let msg: string
        if (AppConstants.isNetworkError(err)) {
          msg = 'Error: No internet connection. Please check your network connection and try again.'
        } else if (err.includes('429')) {
          msg =
            `Quota or rate limit reached for ${state.model}. Wait a bit, or pick another ` +
            'model with /model. Pro models usually need a billing-enabled key.'
        } else if (err.includes('404')) {
          msg = `${state.model} is not available for your key. Pick another model with /model.`
        } else if (err.includes('503') || err.includes('UNAVAILABLE')) {
          msg = `${state.model} is busy right now. Try again in a minute, or pick another model with /model.`
        } else {
          msg = `[${state.model}] ${err}`
        }
        out(`\n${C.RED}┃ ${C.BOLD}System Error${C.RESET}`)
        const wrapped = wrap(msg, AppConstants.WIDTH)
        for (const line of wrapped.length > 0 ? wrapped : [msg]) {
          out(`${C.RED}┃${C.RESET} ${line}`)
        }
        if (typeof state.onError === 'function') {
          try {
            state.onError(msg, err)
          } catch {}
        }
      }
    } finally {
      state.escMonitor = null
      // The GUI tees its own error cards into the journal while `onError` is still wired.
      await this.deps.journal?.end()
    }
  }

  async pickFunction(): Promise<void> {
    const state = this.deps.state
    const chosen = await this.deps.choose(
      'Select Gemibot Function Suite or Mode',
      FUNCTION_CATALOG,
      { current: state.activeFunction, page: 15 }
    )
    if (!chosen) {
      out(`  ${C.DIM}Cancelled. Active function suite: ${state.activeFunction}${C.RESET}`)
      return
    }

    if (chosen === 'pip_installer') {
      await this.installPipPackages()
      return
    }

    if (chosen === 'build' || chosen === 'plan' || chosen === 'read') {
      state.mode = chosen
      state.activeFunction = chosen === 'build' ? 'all' : chosen
    } else {
      state.mode = 'build'
      state.activeFunction = chosen
    }

    state.system = await this.deps.system.buildSystem(state)
    await this.deps.settings.saveSettings({
      function_suite: state.activeFunction,
      mode: state.mode
    })
    const toolsEnabled = FUNCTION_TOOL_MAP[state.activeFunction] ?? ALL_DECLARATIONS
    const toolNames = toolsEnabled.map((d) => d.name).join(', ')
    out(
      `\n  ${C.BG_FUNC} FUNCTION ${C.RESET} ${C.GREEN}${C.BOLD}${chosen}${C.RESET} ` +
        `${C.GRAY}(mode: ${state.mode.toUpperCase()})${C.RESET}`
    )
    out(`  ${C.DIM}Enabled Tools (${toolsEnabled.length}): ${toolNames}${C.RESET}`)
  }

  async installPipPackages(): Promise<void> {
    out(`\n  ${C.GRAY}- ${C.CYAN}${C.BOLD}Gemibot .venv Pip Manager${C.RESET}`)
    out(`  ${C.GRAY}- Python Interpreter: ${process.execPath}`)
    out(`  ${C.GRAY}- Packages: ${AppConstants.REQUIRED_PIP_PACKAGES.join(', ')}`)
  }
}

import { resolve } from 'path'
import { ChangeType, FileChange, type FileChangeDict } from '../../shared/models/file-change'
import { pyNormalizeRelPath } from '../../shared/utils/py-path'
import { pyCompare } from '../../shared/utils/pystr'
import { pyListRepr } from '../../shared/utils/pyrepr'
import { nowStrftime } from '../../shared/utils/strftime'
import type { ChangesSummary } from '../../shared/types/changes'
import { out } from '../utils/console-out'
import { SnapshotStore } from './snapshot-store.service'

export class ChangeTracker {
  root: string
  readonly store: SnapshotStore
  pendingChanges: Map<string, FileChange> = new Map()
  filesRead: Record<string, string> = {}
  onChangesUpdated: ((summary: ChangesSummary) => void) | null = null

  private constructor(root: string) {
    this.root = resolve(root)
    this.store = new SnapshotStore(this.root)
  }

  static async create(root: string): Promise<ChangeTracker> {
    const tracker = new ChangeTracker(root)
    await tracker.loadState()
    return tracker
  }

  normalizePath(path: string): string {
    return pyNormalizeRelPath(path)
  }

  /** Pending changes belong to a project, so switching targets swaps in the other project's set. */
  async setRoot(root: string): Promise<void> {
    const before = this.getSummary()
    this.root = resolve(root)
    this.store.setRoot(this.root)
    this.pendingChanges.clear()
    this.filesRead = {}
    await this.loadState()
    const after = this.getSummary()
    if (JSON.stringify(before) !== JSON.stringify(after)) this.onChangesUpdated?.(after)
  }

  async loadState(): Promise<void> {
    const manifest = await this.store.loadManifest()
    const rawChanges = (manifest.changes ?? {}) as Record<string, unknown>
    const rawReads = (manifest.reads ?? {}) as Record<string, string>

    this.pendingChanges.clear()
    for (const [path, data] of Object.entries(rawChanges)) {
      try {
        this.pendingChanges.set(
          this.normalizePath(path),
          FileChange.fromDict(data as FileChangeDict)
        )
      } catch {}
    }

    this.filesRead = Object.fromEntries(
      Object.entries(rawReads).map(([path, time]) => [this.normalizePath(path), time])
    )
  }

  private async saveState(): Promise<void> {
    await this.store.saveManifest({
      changes: Object.fromEntries(
        [...this.pendingChanges.entries()].map(([path, change]) => [path, change.toDict()])
      ),
      reads: this.filesRead
    })
    if (this.onChangesUpdated) {
      try {
        this.onChangesUpdated(this.getSummary())
      } catch {}
    }
  }

  async recordRead(relPath: string): Promise<void> {
    this.filesRead[this.normalizePath(relPath)] = nowStrftime('%H:%M:%S')
    await this.saveState()
  }

  async recordChange(
    relPath: string,
    fullPath: string,
    changeType: ChangeType,
    detail = '',
    isBinary = false,
    what = '',
    why = ''
  ): Promise<FileChange | null> {
    const norm = this.normalizePath(relPath)
    const full = resolve(fullPath)

    const existing = this.pendingChanges.get(norm)
    if (existing) {
      if (!existing.original_exists && changeType === ChangeType.DELETED) {
        if (existing.snapshot_id) await this.store.deleteSnapshot(existing.snapshot_id)
        this.pendingChanges.delete(norm)
        await this.saveState()
        return null
      }

      if (changeType === ChangeType.DELETED) {
        existing.change_type = ChangeType.DELETED
      } else if (existing.original_exists && existing.change_type === ChangeType.DELETED) {
        existing.change_type = ChangeType.MODIFIED
      } else if (!existing.original_exists) {
        existing.change_type =
          changeType === ChangeType.GENERATED || changeType === ChangeType.DOCX_EDITED
            ? changeType
            : ChangeType.ADDED
      } else {
        existing.change_type = changeType
      }

      existing.detail = detail || existing.detail
      existing.timestamp = nowStrftime('%Y-%m-%d %H:%M:%S')

      if (what) existing.what.push(what)
      if (why) existing.why.push(why)

      await this.saveState()
      return existing
    }

    const [snapId, origExists, detectedBin] = await this.store.saveSnapshot(norm, full)

    if (origExists && !snapId) {
      out(
        `Warning: Failed to create snapshot for existing file ${norm}, change tracking may be incomplete`
      )
    }

    const change = new FileChange({
      path: norm,
      full_path: full,
      change_type: changeType,
      snapshot_id: snapId,
      original_exists: origExists,
      timestamp: nowStrftime('%Y-%m-%d %H:%M:%S'),
      detail,
      is_binary: isBinary || detectedBin,
      what: what ? [what] : [],
      why: why ? [why] : []
    })
    this.pendingChanges.set(norm, change)
    await this.saveState()
    return change
  }

  async acceptAll(): Promise<string[]> {
    const accepted = [...this.pendingChanges.keys()]
    this.pendingChanges.clear()
    this.filesRead = {}
    await this.store.clearAll()
    await this.saveState()
    return accepted
  }

  async rejectAll(): Promise<string[]> {
    const rejected: string[] = []
    const failed: string[] = []
    for (const [normPath, change] of [...this.pendingChanges.entries()]) {
      const restored = await this.store.restoreSnapshot(
        change.snapshot_id,
        change.full_path,
        change.original_exists
      )
      if (restored) rejected.push(normPath)
      else failed.push(normPath)
    }

    if (!failed.length) {
      this.pendingChanges.clear()
      this.filesRead = {}
      await this.store.clearAll()
    } else {
      for (const normPath of rejected) {
        const change = this.pendingChanges.get(normPath)
        if (change) {
          this.pendingChanges.delete(normPath)
          if (change.snapshot_id) await this.store.deleteSnapshot(change.snapshot_id)
        }
      }
      out(`Warning: Failed to restore ${failed.length} files: ${pyListRepr(failed)}`)
    }

    await this.saveState()
    return rejected
  }

  async acceptFile(relPath: string): Promise<boolean> {
    const norm = this.normalizePath(relPath)
    const change = this.pendingChanges.get(norm)
    if (change) {
      this.pendingChanges.delete(norm)
      if (change.snapshot_id) await this.store.deleteSnapshot(change.snapshot_id)
      await this.saveState()
      return true
    }
    return false
  }

  async rejectFile(relPath: string): Promise<boolean> {
    const norm = this.normalizePath(relPath)
    const change = this.pendingChanges.get(norm)
    if (!change) return false

    this.pendingChanges.delete(norm)
    const restored = await this.store.restoreSnapshot(
      change.snapshot_id,
      change.full_path,
      change.original_exists
    )
    if (restored) {
      await this.store.deleteSnapshot(change.snapshot_id)
      await this.saveState()
      return true
    }

    this.pendingChanges.set(norm, change)
    await this.saveState()
    return false
  }

  getSummary(): ChangesSummary {
    const counts: Record<string, number> = {
      [ChangeType.ADDED]: 0,
      [ChangeType.MODIFIED]: 0,
      [ChangeType.DELETED]: 0,
      [ChangeType.GENERATED]: 0,
      [ChangeType.DOCX_EDITED]: 0
    }
    for (const change of this.pendingChanges.values()) {
      const val = change.change_type as string
      counts[val] = (counts[val] ?? 0) + 1
    }

    return {
      total_changes: this.pendingChanges.size,
      counts,
      changes: [...this.pendingChanges.values()]
        .sort((a, b) => pyCompare(a.path, b.path))
        .map((change) => change.toDict()),
      files_read: Object.entries(this.filesRead)
        .sort(([a], [b]) => pyCompare(a, b))
        .map(([path, time]) => ({ path, time }))
    }
  }
}

import type { ConversationRow, MessageRow } from './conversation-repository.service'

function parseJson(value: string | null): unknown {
  if (value === null) return null
  try {
    return JSON.parse(value) as unknown
  } catch {
    return null
  }
}

function iso(ms: number): string {
  return new Date(Number.isFinite(ms) ? ms : Date.now()).toISOString()
}

function roleLabel(row: MessageRow): string {
  if (row.role === 'user') return 'User'
  if (row.role === 'assistant') return 'Assistant'
  if (row.role === 'tool') return 'Tool'
  return 'System'
}

function toolName(row: MessageRow): string {
  const calls = parseJson(row.tool_calls)
  if (calls && typeof calls === 'object' && !Array.isArray(calls)) {
    const name = (calls as Record<string, unknown>).name
    if (typeof name === 'string' && name) return name
  }
  return row.status === 'failed' ? 'tool (failed)' : 'tool'
}

function duration(row: MessageRow): string {
  if (row.duration_ms === null) return ''
  const seconds = row.duration_ms / 1000
  return seconds >= 0.1 ? ` • ${seconds.toFixed(1)}s` : ''
}

export function exportFileName(title: string, format: 'md' | 'json'): string {
  const base = title.replace(/[^\w.-]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60)
  const stamp = new Date().toISOString().slice(0, 10)
  return `gemibot-${base || 'conversation'}-${stamp}.${format}`
}

export function conversationToMarkdown(
  conversation: ConversationRow,
  messages: MessageRow[]
): string {
  const lines: string[] = [
    `# ${conversation.title}`,
    '',
    `- **Conversation ID:** \`${conversation.id}\``,
    `- **Created:** ${iso(conversation.created_at)}`,
    `- **Updated:** ${iso(conversation.updated_at)}`,
    `- **Messages:** ${messages.length}`
  ]
  if (conversation.parent_conversation_id) {
    lines.push(`- **Parent conversation:** \`${conversation.parent_conversation_id}\``)
  }
  if (conversation.summary) {
    lines.push('', '## Summary', '', conversation.summary)
  }
  lines.push('', '---', '')

  for (const row of messages) {
    const meta: string[] = [iso(row.created_at)]
    if (row.model) meta.push(row.model)
    if (row.effort_level) meta.push(row.effort_level)
    if (row.role === 'tool') {
      meta.push(toolName(row))
      if (row.status) meta.push(row.status)
      meta.push(duration(row).replace(/^ • /, ''))
    } else if (row.status && row.status !== 'success') {
      meta.push(row.status)
    }
    const heading = `### ${roleLabel(row)}${meta.filter(Boolean).length > 0 ? ` — ${meta.filter(Boolean).join(' • ')}` : ''}`
    lines.push(heading, '')
    if (row.role === 'tool') {
      lines.push('```', row.content, '```')
    } else {
      lines.push(row.content)
    }
    lines.push('')
  }
  return `${lines.join('\n')}\n`
}

export function conversationToJson(
  conversation: ConversationRow,
  messages: MessageRow[]
): string {
  const payload = {
    conversation: {
      id: conversation.id,
      title: conversation.title,
      createdAt: iso(conversation.created_at),
      updatedAt: iso(conversation.updated_at),
      summary: conversation.summary,
      parentConversationId: conversation.parent_conversation_id
    },
    messages: messages.map((row) => ({
      id: row.id,
      role: row.role,
      content: row.content,
      model: row.model,
      effortLevel: row.effort_level,
      status: row.status,
      durationMs: row.duration_ms,
      createdAt: iso(row.created_at),
      toolCalls: parseJson(row.tool_calls),
      toolResult: parseJson(row.tool_result)
    }))
  }
  return `${JSON.stringify(payload, null, 2)}\n`
}

import type { WindowEvent } from '../../shared/types/window'
import { nowStrftime } from '../../shared/utils/strftime'
import type { Content } from '../models/content'
import { contentModelDumpJson, contentModelValidateJson } from '../models/content'
import {
  conversationRepository,
  deriveTitle,
  type ConversationListItem,
  type ConversationRepository,
  type ConversationRow,
  type MessageOptions,
  type MessagePage,
  type MessageRow
} from './conversation-repository.service'

/**
 * The bridge between the engine's live state and the SQLite conversation store.
 *
 * A locked or corrupt database must never abort a turn: the engine keeps working from RAM while
 * the user is told that the chat is not being saved. There is no file fallback.
 */

const HEADER_BULLET = '  •  '

export interface TimelineRowMeta {
  event?: WindowEvent
  cpIdx?: number | null
  contentIndex?: number | null
  hidden?: boolean
}

export interface UserRecordOptions {
  cpIdx?: number | null
  contentIndex?: number | null
  model?: string
  effortLevel?: string
  event?: WindowEvent
  hidden?: boolean
}

export interface AssistantRecordOptions {
  contentIndex?: number | null
  model?: string
  effortLevel?: string
  event?: WindowEvent
  meta?: string
}

export interface ActionRecordOptions {
  contentIndex?: number | null
  model?: string
  effortLevel?: string
}

export interface ConversationPage {
  rows: MessageRow[]
  hasMore: boolean
}

export function parseRowMeta(row: MessageRow): TimelineRowMeta | null {
  if (!row.meta_json) return null
  try {
    const value = JSON.parse(row.meta_json) as unknown
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value as TimelineRowMeta
    }
  } catch {}
  return null
}

function rowTime(createdAt: number): string {
  const date = Number.isFinite(createdAt) ? new Date(createdAt) : new Date()
  return nowStrftime('%H:%M:%S', date)
}

/**
 * Turns a stored row back into the timeline widget it represented. App-written rows carry the
 * exact event in `meta_json`; rows imported from an older store are rebuilt from their columns.
 */
export function eventFromRow(row: MessageRow): WindowEvent | null {
  const meta = parseRowMeta(row)
  if (meta?.event) return meta.event
  if (meta?.hidden) return null
  const timestamp = rowTime(row.created_at)
  if (row.role === 'user') {
    if (row.content.startsWith('/') || row.content.startsWith('!')) return null
    return {
      kind: 'user',
      text: row.content,
      cpIdx: meta?.cpIdx ?? null,
      header: ['You', timestamp].join(HEADER_BULLET),
      timestamp
    }
  }
  if (row.role === 'assistant') {
    const label = row.model || 'GemiBot AI'
    return {
      kind: 'assistant',
      text: row.content,
      meta: '',
      header: [label, timestamp].join(HEADER_BULLET),
      timestamp
    }
  }
  return null
}

export function storedContentIndex(row: MessageRow): number | null {
  const meta = parseRowMeta(row)
  return typeof meta?.contentIndex === 'number' ? meta.contentIndex : null
}

function parsedJson(value: string | null): unknown {
  if (value === null) return null
  try {
    return JSON.parse(value) as unknown
  } catch {
    return null
  }
}

function toolNameOfRow(row: MessageRow): string {
  const meta = parseRowMeta(row)
  const event = meta?.event
  if (event !== undefined && event.kind === 'action') {
    const name = (event.event as Record<string, unknown> | undefined)?.['tool']
    if (typeof name === 'string' && name) return name
  }
  const calls = parsedJson(row.tool_calls)
  if (calls && typeof calls === 'object' && !Array.isArray(calls)) {
    const name = (calls as Record<string, unknown>)['name']
    if (typeof name === 'string' && name) return name
  }
  return 'tool'
}

function toolResponseOfRow(row: MessageRow): Record<string, unknown> {
  const result = parsedJson(row.tool_result)
  if (result && typeof result === 'object' && !Array.isArray(result)) {
    return result as Record<string, unknown>
  }
  return { output: typeof result === 'string' ? result : row.content }
}

export type PersistenceErrorReporter = (message: string, details: string) => void

export class ConversationPersistence {
  private current: string | null = null
  private readonly repo: ConversationRepository
  private errorReporter: PersistenceErrorReporter | null = null
  private lastFailure: { key: string; at: number } | null = null

  constructor(repo: ConversationRepository = conversationRepository) {
    this.repo = repo
  }

  setErrorReporter(reporter: PersistenceErrorReporter | null): void {
    this.errorReporter = reporter
  }

  /** One card per failure window, so a broken store cannot flood the timeline. */
  private failed(action: string, error: unknown): void {
    const details = error instanceof Error ? error.message : String(error)
    const key = `${action}:${details}`
    const now = Date.now()
    if (this.lastFailure?.key === key && now - this.lastFailure.at < 15_000) return
    this.lastFailure = { key, at: now }
    try {
      this.errorReporter?.(`Could not ${action}.`, details)
    } catch {}
  }

  get conversationId(): string | null {
    return this.current
  }

  use(conversationId: string | null): void {
    this.current = conversationId
  }

  exists(conversationId: string | null = this.current): boolean {
    if (!conversationId) return false
    try {
      return this.repo.getConversation(conversationId) !== null
    } catch (error) {
      this.failed('read the conversation store', error)
      return false
    }
  }

  create(title: string = 'New Conversation', parentId: string | null = null): string | null {
    const id = `conv_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`
    try {
      this.repo.createConversation(id, title, parentId)
      return id
    } catch (error) {
      this.failed('create a conversation', error)
      return null
    }
  }

  /** A child store for one sub-agent, linked through `parent_conversation_id`. */
  child(parentId: string, title: string): ConversationPersistence | null {
    const id = this.create(title, parentId)
    if (!id) return null
    const child = new ConversationPersistence(this.repo)
    child.use(id)
    return child
  }

  ensure(title: string = 'New Conversation'): string | null {
    if (this.current && this.exists()) return this.current
    const id = this.create(title)
    if (id) this.current = id
    return this.current
  }

  start(title: string, prompt?: string): string | null {
    const id = this.create(title, null)
    if (!id) return null
    this.current = id
    if (prompt) this.rename(id, deriveTitle(prompt))
    return id
  }

  list(includeSubAgents = false, limit = 200, offset = 0): ConversationListItem[] {
    try {
      return this.repo.listConversations(includeSubAgents, limit, offset)
    } catch (error) {
      this.failed('load the conversation list', error)
      return []
    }
  }

  listSubAgents(parentId: string): ConversationListItem[] {
    try {
      return this.repo.listSubAgents(parentId)
    } catch (error) {
      this.failed('load sub-agent conversations', error)
      return []
    }
  }

  get(conversationId: string): ConversationRow | null {
    try {
      return this.repo.getConversation(conversationId)
    } catch (error) {
      this.failed('load the conversation', error)
      return null
    }
  }

  last(): ConversationRow | null {
    try {
      return this.repo.lastConversation()
    } catch (error) {
      this.failed('find the last conversation', error)
      return null
    }
  }

  rename(conversationId: string, title: string): boolean {
    try {
      this.repo.renameConversation(conversationId, title)
      return true
    } catch (error) {
      this.failed('rename the conversation', error)
      return false
    }
  }

  remove(conversationId: string): boolean {
    try {
      this.repo.deleteConversation(conversationId)
      if (this.current === conversationId) this.current = null
      return true
    } catch (error) {
      this.failed('delete the conversation', error)
      return false
    }
  }

  touch(conversationId: string | null = this.current): void {
    if (!conversationId) return
    try {
      this.repo.touchConversation(conversationId)
    } catch (error) {
      this.failed('update the conversation', error)
    }
  }

  // ---------- Exact model history ----------

  appendContent(content: Content, conversationId: string | null = this.current): number | null {
    if (!conversationId) return null
    try {
      return this.repo.appendContent(conversationId, contentModelDumpJson(content))
    } catch (error) {
      this.failed('save the model history', error)
      return null
    }
  }

  contents(conversationId: string | null = this.current): Content[] {
    if (!conversationId) return []
    try {
      const result: Content[] = []
      for (const row of this.repo.getContents(conversationId)) {
        try {
          result.push(contentModelValidateJson(row.content_json))
        } catch {}
      }
      if (result.length > 0) return result
      // Markdown imports have timeline rows but no exact model contents.  Rebuilding once and
      // saving it means a later turn keeps the imported history instead of sending only the new
      // prompt, and the next reopen reads the same history back.
      const rebuilt = this.contentsFromMessages(conversationId)
      if (rebuilt.length > 0) {
        this.repo.transaction(() => {
          this.repo.deleteContentsFrom(conversationId, 0)
          for (const content of rebuilt) {
            this.repo.appendContent(conversationId, contentModelDumpJson(content))
          }
        })
      }
      return rebuilt
    } catch (error) {
      this.failed('load the conversation history', error)
      return []
    }
  }

  private contentsFromMessages(conversationId: string): Content[] {
    const contents: Content[] = []
    for (const row of this.repo.getAllMessages(conversationId)) {
      const meta = parseRowMeta(row)
      if (meta?.hidden) continue
      if (row.role === 'user') {
        if (row.content.startsWith('/') || row.content.startsWith('!')) continue
        contents.push({ role: 'user', parts: [{ text: row.content }] })
      } else if (row.role === 'assistant') {
        contents.push({ role: 'model', parts: [{ text: row.content }] })
      } else if (row.role === 'tool') {
        contents.push({
          role: 'user',
          parts: [
            {
              function_response: {
                name: toolNameOfRow(row),
                response: toolResponseOfRow(row)
              }
            }
          ]
        })
      }
    }
    return contents
  }

  contentCount(conversationId: string | null = this.current): number {
    if (!conversationId) return 0
    try {
      return this.repo.getContentCount(conversationId)
    } catch (error) {
      this.failed('count the conversation history', error)
      return 0
    }
  }

  truncateContents(length: number, conversationId: string | null = this.current): void {
    if (!conversationId) return
    try {
      this.repo.deleteContentsFrom(conversationId, length)
    } catch (error) {
      this.failed('trim the saved history', error)
    }
  }

  // ---------- Timeline rows ----------

  recordUser(
    text: string,
    options: UserRecordOptions = {},
    conversationId: string | null = this.current
  ): number | null {
    if (!conversationId) return null
    const meta: TimelineRowMeta = {}
    if (options.event) meta.event = options.event
    if (options.cpIdx !== undefined) meta.cpIdx = options.cpIdx
    if (options.contentIndex !== undefined) meta.contentIndex = options.contentIndex
    if (options.hidden) meta.hidden = true
    return this.addRow(
      conversationId,
      'user',
      text,
      {
        model: options.model,
        effortLevel: options.effortLevel,
        meta: Object.keys(meta).length > 0 ? (meta as Record<string, unknown>) : undefined
      }
    )
  }

  recordAssistant(
    text: string,
    options: AssistantRecordOptions = {},
    conversationId: string | null = this.current
  ): number | null {
    if (!conversationId) return null
    const meta: TimelineRowMeta = {}
    if (options.event) meta.event = options.event
    if (options.meta !== undefined) (meta as Record<string, unknown>)['meta'] = options.meta
    if (options.contentIndex !== undefined) meta.contentIndex = options.contentIndex
    return this.addRow(conversationId, 'assistant', text, {
      model: options.model,
      effortLevel: options.effortLevel,
      status: 'success',
      meta: meta as Record<string, unknown>
    })
  }

  recordAction(
    event: Record<string, unknown>,
    options: ActionRecordOptions = {},
    conversationId: string | null = this.current
  ): number | null {
    if (!conversationId) return null
    const output = typeof event.output === 'string' ? event.output : safeJson(event.output)
    const duration = typeof event.duration === 'number' ? event.duration : null
    const meta: TimelineRowMeta = {
      event: { kind: 'action', event },
      contentIndex: options.contentIndex ?? null
    }
    return this.addRow(conversationId, 'tool', output, {
      toolCalls: event.args,
      toolResult: {
        output,
        is_error: Boolean(event.is_error),
        status: typeof event.status === 'string' ? event.status : undefined
      },
      model: options.model,
      effortLevel: options.effortLevel,
      status: event.is_error ? 'failed' : 'success',
      durationMs: duration === null ? undefined : Math.round(duration * 1000),
      meta: meta as Record<string, unknown>
    })
  }

  /** Stores a rendered chat row (user, assistant, action, pill, error) exactly as shown. */
  recordEvent(
    event: WindowEvent,
    options: ActionRecordOptions & { cpIdx?: number | null; hidden?: boolean } = {},
    conversationId: string | null = this.current
  ): number | null {
    switch (event.kind) {
      case 'user':
        return this.recordUser(
          event.text,
          {
            cpIdx: options.cpIdx ?? event.cpIdx,
            contentIndex: options.contentIndex,
            model: options.model,
            effortLevel: options.effortLevel,
            event,
            hidden: options.hidden
          },
          conversationId
        )
      case 'assistant':
        return this.recordAssistant(
          event.text,
          {
            contentIndex: options.contentIndex,
            model: options.model,
            effortLevel: options.effortLevel,
            event,
            meta: event.meta
          },
          conversationId
        )
      case 'action':
        return this.recordAction(
          event.event,
          {
            contentIndex: options.contentIndex,
            model: options.model,
            effortLevel: options.effortLevel
          },
          conversationId
        )
      case 'pill':
        return this.addRow(
          conversationId,
          'system',
          event.text,
          {
            model: options.model,
            effortLevel: options.effortLevel,
            meta: { event, contentIndex: options.contentIndex ?? null }
          }
        )
      case 'error':
        return this.addRow(
          conversationId,
          'system',
          `${event.title}: ${event.message}`.trim(),
          {
            model: options.model,
            effortLevel: options.effortLevel,
            status: 'failed',
            meta: { event, contentIndex: options.contentIndex ?? null }
          }
        )
      default:
        return null
    }
  }

  private addRow(
    conversationId: string | null,
    role: 'user' | 'assistant' | 'system' | 'tool',
    content: string,
    options: MessageOptions
  ): number | null {
    if (!conversationId) return null
    try {
      const id = this.repo.addMessage(conversationId, role, content, options)
      return Number.isFinite(id) ? id : null
    } catch (error) {
      this.failed('save a message', error)
      return null
    }
  }

  message(messageId: number): MessageRow | null {
    try {
      return this.repo.getMessage(messageId)
    } catch (error) {
      this.failed('load a message', error)
      return null
    }
  }

  page(
    beforeId: number | null = null,
    limit = 100,
    conversationId: string | null = this.current
  ): ConversationPage {
    if (!conversationId) return { rows: [], hasMore: false }
    try {
      const result: MessagePage = this.repo.getMessagePage(conversationId, limit, beforeId)
      return { rows: result.messages, hasMore: result.hasMore }
    } catch (error) {
      this.failed('load the message history', error)
      return { rows: [], hasMore: false }
    }
  }

  allMessages(conversationId: string | null = this.current): MessageRow[] {
    if (!conversationId) return []
    try {
      return this.repo.getAllMessages(conversationId)
    } catch (error) {
      this.failed('load all messages', error)
      return []
    }
  }

  lastMessageId(conversationId: string | null = this.current): number {
    if (!conversationId) return 0
    try {
      const id = this.repo.getLastMessageId(conversationId)
      return Number.isFinite(id) ? id : 0
    } catch (error) {
      this.failed('read the last message id', error)
      return 0
    }
  }

  /** Deletes a row and everything after it, plus the model history it introduced. */
  clearFrom(
    messageId: number,
    contentIndex: number | null,
    conversationId: string | null = this.current
  ): boolean {
    if (!conversationId) return false
    try {
      this.repo.tryTransaction(() => {
        this.repo.deleteMessagesFrom(conversationId, messageId)
        if (contentIndex !== null && contentIndex >= 0) {
          this.repo.deleteContentsFrom(conversationId, contentIndex)
        }
      })
      return true
    } catch (error) {
      this.failed('remove messages from the store', error)
      return false
    }
  }

  // ---------- Queue ----------

  loadQueue(conversationId: string | null = this.current): string[] {
    if (!conversationId) return []
    try {
      return this.repo.getQueuedMessages(conversationId).map((row) => row.content)
    } catch (error) {
      this.failed('load the queued messages', error)
      return []
    }
  }

  saveQueue(contents: string[], conversationId: string | null = this.current): void {
    if (!conversationId) return
    try {
      this.repo.replaceQueuedMessages(conversationId, contents)
    } catch (error) {
      this.failed('save the queued messages', error)
    }
  }

  // ---------- Summary ----------

  saveSummary(
    summary: string,
    upToMessageId?: number,
    conversationId: string | null = this.current
  ): void {
    if (!conversationId) return
    try {
      const upTo = upToMessageId ?? this.lastMessageId(conversationId)
      this.repo.saveSummary(conversationId, summary, upTo)
    } catch (error) {
      this.failed('save the conversation summary', error)
    }
  }

  getSummary(conversationId: string | null = this.current): string | null {
    if (!conversationId) return null
    try {
      return this.repo.getConversation(conversationId)?.summary ?? null
    } catch (error) {
      this.failed('load the conversation summary', error)
      return null
    }
  }
}

function safeJson(value: unknown): string {
  if (value === undefined || value === null) return ''
  try {
    return JSON.stringify(value)
  } catch {
    return String(value)
  }
}

export const conversationPersistence = new ConversationPersistence()

import Database from 'better-sqlite3'
import { getDatabase } from './database.service'

export interface ConversationRow {
  id: string
  title: string
  created_at: number
  updated_at: number
  summary: string | null
  summary_up_to_message_id: number | null
  parent_conversation_id: string | null
}

export interface MessageRow {
  id: number
  conversation_id: string
  role: 'user' | 'assistant' | 'system' | 'tool'
  content: string
  tool_calls: string | null
  tool_result: string | null
  model: string | null
  effort_level: string | null
  status: string | null
  duration_ms: number | null
  meta_json: string | null
  created_at: number
}

export interface QueuedMessageRow {
  id: number
  conversation_id: string
  content: string
  position: number
  created_at: number
}

export interface ConversationContentRow {
  id: number
  conversation_id: string
  position: number
  content_json: string
  created_at: number
}

export interface ConversationListItem {
  id: string
  title: string
  updated_at: number
  created_at: number
  message_count: number
  parent_conversation_id: string | null
  is_sub_agent: boolean
  preview: string
  sub_agent_count: number
}

export interface MessagePage {
  messages: MessageRow[]
  hasMore: boolean
}

export interface MessageOptions {
  toolCalls?: unknown
  toolResult?: unknown
  model?: string
  effortLevel?: string
  status?: string
  durationMs?: number
  meta?: Record<string, unknown>
  createdAt?: number
}

export interface ConversationOptions {
  parentId?: string | null
  createdAt?: number
  updatedAt?: number
}

function clipPreview(text: string): string {
  const clean = text.replace(/\s+/g, ' ').trim()
  return clean.length > 120 ? `${clean.slice(0, 120)}...` : clean
}

export function deriveTitle(prompt: string): string {
  const clean = prompt.replace(/\s+/g, ' ').trim()
  if (!clean) return 'New Conversation'
  return clean.length > 60 ? `${clean.slice(0, 60)}...` : clean
}

export class ConversationRepository {
  private db: Database | null = null

  private get dbInstance(): Database {
    if (this.db) return this.db
    this.db = getDatabase()
    return this.db
  }

  constructor(db?: Database) {
    this.db = db ?? null
  }

  // ---------- Conversations ----------

  createConversation(
    id: string,
    title: string = 'New Conversation',
    parentId: string | null = null,
    options: ConversationOptions = {}
  ): ConversationRow {
    const now = Date.now()
    const createdAt = options.createdAt ?? now
    const updatedAt = options.updatedAt ?? now
    this.dbInstance
      .prepare(
        `INSERT INTO conversations (id, title, created_at, updated_at, parent_conversation_id)
         VALUES (?, ?, ?, ?, ?)`
      )
      .run(id, title, createdAt, updatedAt, parentId)
    return {
      id,
      title,
      created_at: createdAt,
      updated_at: updatedAt,
      summary: null,
      summary_up_to_message_id: null,
      parent_conversation_id: parentId
    }
  }

  listConversations(includeSubAgents: boolean = false, limit = 200, offset = 0): ConversationListItem[] {
    const rows = this.dbInstance
      .prepare(
        `SELECT c.id, c.title, c.updated_at, c.created_at, c.parent_conversation_id,
                (SELECT COUNT(*) FROM messages m WHERE m.conversation_id = c.id) AS message_count,
                (SELECT COUNT(*) FROM conversations s WHERE s.parent_conversation_id = c.id) AS sub_agent_count,
                (SELECT m.content FROM messages m
                  WHERE m.conversation_id = c.id AND m.role IN ('user', 'assistant')
                  ORDER BY m.id DESC LIMIT 1) AS last_content
         FROM conversations c
         ${includeSubAgents ? '' : 'WHERE c.parent_conversation_id IS NULL'}
         ORDER BY c.updated_at DESC, c.id DESC
         LIMIT ? OFFSET ?`
      )
      .all(limit, offset) as Array<{
      id: string
      title: string
      updated_at: number
      created_at: number
      message_count: number
      parent_conversation_id: string | null
      sub_agent_count: number
      last_content: string | null
    }>
    return rows.map((row) => ({
      id: row.id,
      title: row.title,
      updated_at: row.updated_at,
      created_at: row.created_at,
      message_count: row.message_count,
      parent_conversation_id: row.parent_conversation_id,
      is_sub_agent: row.parent_conversation_id !== null,
      preview: row.last_content ? clipPreview(row.last_content) : '',
      sub_agent_count: row.sub_agent_count
    }))
  }

  listSubAgents(parentId: string): ConversationListItem[] {
    return (
      this.dbInstance
        .prepare(
          `SELECT c.id, c.title, c.updated_at, c.created_at, c.parent_conversation_id,
                  (SELECT COUNT(*) FROM messages m WHERE m.conversation_id = c.id) AS message_count,
                  0 AS sub_agent_count,
                  (SELECT m.content FROM messages m
                    WHERE m.conversation_id = c.id AND m.role IN ('user', 'assistant')
                    ORDER BY m.id DESC LIMIT 1) AS last_content
           FROM conversations c
           WHERE c.parent_conversation_id = ?
           ORDER BY c.created_at ASC, c.id ASC`
        )
        .all(parentId) as Array<{
        id: string
        title: string
        updated_at: number
        created_at: number
        message_count: number
        parent_conversation_id: string | null
        sub_agent_count: number
        last_content: string | null
      }>
    ).map((row) => ({
      id: row.id,
      title: row.title,
      updated_at: row.updated_at,
      created_at: row.created_at,
      message_count: row.message_count,
      parent_conversation_id: row.parent_conversation_id,
      is_sub_agent: true,
      preview: row.last_content ? clipPreview(row.last_content) : '',
      sub_agent_count: 0
    }))
  }

  getConversation(id: string): ConversationRow | null {
    return this.dbInstance.prepare('SELECT * FROM conversations WHERE id = ?').get(id) as
      | ConversationRow
      | null
  }

  updateConversation(
    id: string,
    updates: Partial<{ title: string; summary: string; summary_up_to_message_id: number }>
  ): void {
    const sets: string[] = []
    const values: unknown[] = []
    if (updates.title !== undefined) {
      sets.push('title = ?')
      values.push(updates.title)
    }
    if (updates.summary !== undefined) {
      sets.push('summary = ?')
      values.push(updates.summary)
    }
    if (updates.summary_up_to_message_id !== undefined) {
      sets.push('summary_up_to_message_id = ?')
      values.push(updates.summary_up_to_message_id)
    }
    if (sets.length === 0) return
    sets.push('updated_at = ?')
    values.push(Date.now())
    values.push(id)
    this.dbInstance.prepare(`UPDATE conversations SET ${sets.join(', ')} WHERE id = ?`).run(...values)
  }

  renameConversation(id: string, title: string): void {
    this.updateConversation(id, { title })
  }

  touchConversation(id: string, at: number = Date.now()): void {
    this.dbInstance.prepare('UPDATE conversations SET updated_at = ? WHERE id = ?').run(at, id)
  }

  saveSummary(id: string, summary: string, upToMessageId: number): void {
    this.updateConversation(id, { summary, summary_up_to_message_id: upToMessageId })
  }

  deleteConversation(id: string): void {
    this.dbInstance.prepare('DELETE FROM conversations WHERE id = ?').run(id)
  }

  lastConversation(): ConversationRow | null {
    return this.dbInstance
      .prepare(
        `SELECT * FROM conversations
         WHERE parent_conversation_id IS NULL
         ORDER BY updated_at DESC, id DESC LIMIT 1`
      )
      .get() as ConversationRow | null
  }

  // ---------- Messages ----------

  addMessage(
    conversationId: string,
    role: 'user' | 'assistant' | 'system' | 'tool',
    content: string,
    opts: MessageOptions = {}
  ): number {
    const now = opts.createdAt ?? Date.now()
    const insert = this.dbInstance.prepare(
      `INSERT INTO messages
         (conversation_id, role, content, tool_calls, tool_result, model, effort_level, status,
          duration_ms, meta_json, created_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    )
    const touch = this.dbInstance.prepare(
      'UPDATE conversations SET updated_at = ? WHERE id = ?'
    )
    const run = this.dbInstance.transaction(() => {
      const info = insert.run(
        conversationId,
        role,
        content,
        opts.toolCalls !== undefined ? JSON.stringify(opts.toolCalls) : null,
        opts.toolResult !== undefined ? JSON.stringify(opts.toolResult) : null,
        opts.model ?? null,
        opts.effortLevel ?? null,
        opts.status ?? null,
        opts.durationMs ?? null,
        opts.meta !== undefined ? JSON.stringify(opts.meta) : null,
        now
      )
      touch.run(now, conversationId)
      return Number(info.lastInsertRowid)
    })
    return run()
  }

  /** Oldest-first window ending at the newest message, used by the timeline. */
  getMessages(conversationId: string, limit: number = 100, offset: number = 0): MessageRow[] {
    return this.dbInstance
      .prepare(
        `SELECT * FROM messages WHERE conversation_id = ?
         ORDER BY id ASC
         LIMIT ? OFFSET ?`
      )
      .all(conversationId, limit, offset) as MessageRow[]
  }

  getMessage(messageId: number): MessageRow | null {
    return this.dbInstance.prepare('SELECT * FROM messages WHERE id = ?').get(messageId) as
      | MessageRow
      | null
  }

  /** The latest page, still returned oldest-first so callers can replay it in order. */
  getMessagePage(conversationId: string, limit = 100, beforeId?: number | null): MessagePage {
    const safeLimit = Math.max(1, Math.min(500, Math.trunc(limit)))
    const rows = (
      beforeId
        ? this.dbInstance
            .prepare(
              `SELECT * FROM (
                 SELECT * FROM messages
                 WHERE conversation_id = ? AND id < ?
                 ORDER BY id DESC LIMIT ?
               ) ORDER BY id ASC`
            )
            .all(conversationId, beforeId, safeLimit + 1)
        : this.dbInstance
            .prepare(
              `SELECT * FROM (
                 SELECT * FROM messages
                 WHERE conversation_id = ?
                 ORDER BY id DESC LIMIT ?
               ) ORDER BY id ASC`
            )
            .all(conversationId, safeLimit + 1)
    ) as MessageRow[]
    const hasMore = rows.length > safeLimit
    // Rows are oldest-first.  The window was fetched backwards from the page boundary, so the
    // extra row is always the oldest one and dropping it keeps the 100 closest to that boundary.
    const messages = hasMore ? rows.slice(1) : rows
    return { messages, hasMore }
  }

  getAllMessages(conversationId: string): MessageRow[] {
    return this.dbInstance
      .prepare('SELECT * FROM messages WHERE conversation_id = ? ORDER BY id ASC')
      .all(conversationId) as MessageRow[]
  }

  getMessageCount(conversationId: string): number {
    const row = this.dbInstance
      .prepare('SELECT COUNT(*) AS c FROM messages WHERE conversation_id = ?')
      .get(conversationId) as { c: number }
    return row.c
  }

  getLastMessageId(conversationId: string): number {
    const row = this.dbInstance
      .prepare('SELECT COALESCE(MAX(id), 0) AS id FROM messages WHERE conversation_id = ?')
      .get(conversationId) as { id: number }
    return row.id
  }

  updateMessage(
    messageId: number,
    updates: Partial<{
      content: string
      toolCalls: unknown
      toolResult: unknown
      status: string
      durationMs: number
      meta: Record<string, unknown>
      model: string
      effortLevel: string
    }>
  ): void {
    const sets: string[] = []
    const values: unknown[] = []
    if (updates.content !== undefined) {
      sets.push('content = ?')
      values.push(updates.content)
    }
    if (updates.toolCalls !== undefined) {
      sets.push('tool_calls = ?')
      values.push(JSON.stringify(updates.toolCalls))
    }
    if (updates.toolResult !== undefined) {
      sets.push('tool_result = ?')
      values.push(JSON.stringify(updates.toolResult))
    }
    if (updates.status !== undefined) {
      sets.push('status = ?')
      values.push(updates.status)
    }
    if (updates.durationMs !== undefined) {
      sets.push('duration_ms = ?')
      values.push(updates.durationMs)
    }
    if (updates.meta !== undefined) {
      sets.push('meta_json = ?')
      values.push(JSON.stringify(updates.meta))
    }
    if (updates.model !== undefined) {
      sets.push('model = ?')
      values.push(updates.model)
    }
    if (updates.effortLevel !== undefined) {
      sets.push('effort_level = ?')
      values.push(updates.effortLevel)
    }
    if (sets.length === 0) return
    values.push(messageId)
    this.dbInstance.prepare(`UPDATE messages SET ${sets.join(', ')} WHERE id = ?`).run(...values)
  }

  deleteMessage(messageId: number): void {
    this.dbInstance.prepare('DELETE FROM messages WHERE id = ?').run(messageId)
  }

  /** Removes a user row and everything after it, the DB half of "edit this prompt". */
  deleteMessagesFrom(conversationId: string, fromId: number): void {
    const run = this.dbInstance.transaction(() => {
      this.dbInstance
        .prepare('DELETE FROM messages WHERE conversation_id = ? AND id >= ?')
        .run(conversationId, fromId)
      this.dbInstance
        .prepare('UPDATE conversations SET updated_at = ? WHERE id = ?')
        .run(Date.now(), conversationId)
    })
    run()
  }

  // ---------- Model contents (the exact history sent to the model) ----------

  appendContent(conversationId: string, contentJson: string): number {
    const nextPosition = this.dbInstance.prepare(
      'SELECT COALESCE(MAX(position), -1) + 1 AS position FROM conversation_contents WHERE conversation_id = ?'
    )
    const insert = this.dbInstance.prepare(
      `INSERT INTO conversation_contents (conversation_id, position, content_json, created_at)
       VALUES (?, ?, ?, ?)`
    )
    // Position allocation and the insert must not interleave with another append.
    const run = this.dbInstance.transaction(() => {
      const next = nextPosition.get(conversationId) as { position: number }
      const info = insert.run(conversationId, next.position, contentJson, Date.now())
      return Number(info.lastInsertRowid)
    })
    return run()
  }

  getContents(conversationId: string): ConversationContentRow[] {
    return this.dbInstance
      .prepare(
        'SELECT * FROM conversation_contents WHERE conversation_id = ? ORDER BY position ASC'
      )
      .all(conversationId) as ConversationContentRow[]
  }

  getContentCount(conversationId: string): number {
    const row = this.dbInstance
      .prepare('SELECT COUNT(*) AS c FROM conversation_contents WHERE conversation_id = ?')
      .get(conversationId) as { c: number }
    return row.c
  }

  deleteContentsFrom(conversationId: string, position: number): void {
    this.dbInstance
      .prepare('DELETE FROM conversation_contents WHERE conversation_id = ? AND position >= ?')
      .run(conversationId, position)
  }

  // ---------- Queued Messages ----------

  addQueuedMessage(conversationId: string, content: string, position: number): number {
    const now = Date.now()
    const info = this.dbInstance
      .prepare(
        `INSERT INTO queued_messages (conversation_id, content, position, created_at)
         VALUES (?, ?, ?, ?)`
      )
      .run(conversationId, content, position, now)
    return Number(info.lastInsertRowid)
  }

  getQueuedMessages(conversationId: string): QueuedMessageRow[] {
    return this.dbInstance
      .prepare('SELECT * FROM queued_messages WHERE conversation_id = ? ORDER BY position ASC')
      .all(conversationId) as QueuedMessageRow[]
  }

  updateQueuedMessage(id: number, updates: Partial<{ content: string; position: number }>): void {
    const sets: string[] = []
    const values: unknown[] = []
    if (updates.content !== undefined) {
      sets.push('content = ?')
      values.push(updates.content)
    }
    if (updates.position !== undefined) {
      sets.push('position = ?')
      values.push(updates.position)
    }
    if (sets.length === 0) return
    values.push(id)
    this.dbInstance.prepare(`UPDATE queued_messages SET ${sets.join(', ')} WHERE id = ?`).run(...values)
  }

  replaceQueuedMessages(conversationId: string, contents: string[]): void {
    const run = this.dbInstance.transaction(() => {
      this.dbInstance.prepare('DELETE FROM queued_messages WHERE conversation_id = ?').run(conversationId)
      const insert = this.dbInstance.prepare(
        'INSERT INTO queued_messages (conversation_id, content, position, created_at) VALUES (?, ?, ?, ?)'
      )
      contents.forEach((content, position) => insert.run(conversationId, content, position, Date.now()))
    })
    run()
  }

  updateQueuedMessagePosition(id: number, position: number): void {
    this.updateQueuedMessage(id, { position })
  }

  deleteQueuedMessage(id: number): void {
    this.dbInstance.prepare('DELETE FROM queued_messages WHERE id = ?').run(id)
  }

  clearQueuedMessages(conversationId: string): void {
    this.dbInstance.prepare('DELETE FROM queued_messages WHERE conversation_id = ?').run(conversationId)
  }

  // ---------- Imports ----------

  isImported(path: string, sourceKey: string): boolean {
    return Boolean(
      this.dbInstance
        .prepare('SELECT 1 FROM imported_files WHERE path = ? AND source_key = ?')
        .get(path, sourceKey)
    )
  }

  importedConversation(path: string, sourceKey: string): string | null {
    const row = this.dbInstance
      .prepare('SELECT conversation_id FROM imported_files WHERE path = ? AND source_key = ?')
      .get(path, sourceKey) as { conversation_id: string | null } | undefined
    return row?.conversation_id ?? null
  }

  recordImported(
    path: string,
    sourceKey: string,
    hash: string | null,
    conversationId: string | null
  ): void {
    this.dbInstance
      .prepare(
        `INSERT INTO imported_files (path, source_key, hash, conversation_id, imported_at)
         VALUES (?, ?, ?, ?, ?)
         ON CONFLICT(path, source_key) DO UPDATE SET
           hash = excluded.hash,
           conversation_id = excluded.conversation_id,
           imported_at = excluded.imported_at`
      )
      .run(path, sourceKey, hash, conversationId, Date.now())
  }

  // ---------- Transactions ----------

  transaction<T>(fn: () => T): T {
    return this.dbInstance.transaction(fn)()
  }

  /** Runs a write and returns false instead of throwing, for optional live mirroring. */
  tryTransaction<T>(fn: () => T): T | null {
    try {
      return this.transaction(fn)
    } catch {
      return null
    }
  }

  // ---------- Utility ----------

  getSchemaVersion(): number {
    return this.dbInstance.pragma('user_version', { simple: true }) as number
  }

  setSchemaVersion(version: number): void {
    this.dbInstance.pragma(`user_version = ${version}`)
  }

  vacuum(): void {
    this.dbInstance.pragma('VACUUM')
  }
}

export const conversationRepository = new ConversationRepository()

