        CREATE TABLE IF NOT EXISTS pending_snapshots (
          root TEXT NOT NULL,
          snapshot_id TEXT NOT NULL,
          data BLOB NOT NULL,
          updated_at INTEGER NOT NULL,
          PRIMARY KEY (root, snapshot_id)
        );
      `)
    },
    (db) => {
      // v7 keyed long-term rows by the memory/settings file path.  The app no longer touches
      // those files, so move each row to the logical key of the project it belongs to.
      const memoryRows = db
        .prepare('SELECT path, content, updated_at FROM memory_docs ORDER BY updated_at DESC')
        .all() as Array<{ path: string; content: string; updated_at: number }>
      const putMemory = db.prepare(
        'INSERT OR IGNORE INTO memory_docs (path, content, updated_at) VALUES (?, ?, ?)'
      )
      const dropMemory = db.prepare('DELETE FROM memory_docs WHERE path = ?')
      for (const row of memoryRows) {
        const match = /^(.*)[/\\]memory[/\\]memory\.md$/i.exec(row.path)
        if (match === null) continue
        putMemory.run(`memory:${match[1]}`, row.content, row.updated_at)
        dropMemory.run(row.path)
      }

      const settingRows = db
        .prepare('SELECT scope, key, value, updated_at FROM settings ORDER BY updated_at DESC')
        .all() as Array<{ scope: string; key: string; value: string; updated_at: number }>
      const putSetting = db.prepare(
        'INSERT OR IGNORE INTO settings (scope, key, value, updated_at) VALUES (?, ?, ?, ?)'
      )
      const oldScopes = new Set<string>()
      for (const row of settingRows) {
        const match = /^(.*)[/\\]memory[/\\]settings\.md$/i.exec(row.scope)
        if (match === null) continue
        putSetting.run(`settings:${match[1]}`, row.key, row.value, row.updated_at)
        oldScopes.add(row.scope)
      }
      const dropScope = db.prepare('DELETE FROM settings WHERE scope = ?')
      for (const scope of oldScopes) dropScope.run(scope)
    }
  ]
}

function columnExists(db: Database, table: string, column: string): boolean {
  const rows = db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>
  return rows.some((row) => row.name === column)
}

function tableExists(db: Database, table: string): boolean {
  return Boolean(
    db.prepare("SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?").get(table)
  )
}

function legacyVersion(db: Database): number {
  if (!tableExists(db, 'schema_version')) return 0
  const row = db.prepare('SELECT version FROM schema_version LIMIT 1').get() as
    { version: number } | undefined
  return row?.version ?? 0
}

function configure(db: Database): void {
  db.pragma('journal_mode = WAL')
  db.pragma('foreign_keys = ON')
  db.pragma('busy_timeout = 5000')
  db.pragma('synchronous = NORMAL')
}

function migrate(db: Database): void {
  configure(db)
  const steps = migrations()
  let current = db.pragma('user_version', { simple: true }) as number
  const legacy = legacyVersion(db)
  if (current === 0 && legacy > 0) {
    if (legacy > DB_SCHEMA_VERSION) {
      throw new DatabaseUnavailableError(
        `Database schema v${legacy} is newer than this app supports (v${DB_SCHEMA_VERSION}).`
      )
    }
    current = legacy
    db.pragma(`user_version = ${current}`)
  }
  if (current > DB_SCHEMA_VERSION) {
    throw new DatabaseUnavailableError(
      `Database schema v${current} is newer than this app supports (v${DB_SCHEMA_VERSION}).`
    )
  }
  for (let version = current; version < steps.length; version++) {
    const run = db.transaction(() => {
      steps[version](db)
      db.pragma(`user_version = ${version + 1}`)
    })
    run()
  }
  if (tableExists(db, 'schema_version')) {
    db.prepare('UPDATE schema_version SET version = ?').run(DB_SCHEMA_VERSION)
  }
}

function isCorrupt(error: unknown): boolean {
  const text = error instanceof Error ? `${error.name} ${error.message}` : String(error)
  return /SQLITE_CORRUPT|SQLITE_NOTADB|file is not a database|database disk image is malformed/i.test(
    text
  )
}

function backupCorruptFile(path: string): void {
  try {
    if (!existsSync(path)) return
    const stamp = new Date().toISOString().replace(/[:.]/g, '-')
    renameSync(path, `${path}.corrupt-${stamp}`)
    for (const suffix of ['-wal', '-shm']) {
      if (existsSync(`${path}${suffix}`))
        renameSync(`${path}${suffix}`, `${path}.corrupt-${stamp}${suffix}`)
    }
  } catch {
    /* the original stays in place if it cannot be moved */
  }
}

export function openDatabase(): Database {
  if (dbInstance) return dbInstance

  const path = getDbPath()
  let db: Database | null = null
  try {
    db = new Database(path)
    migrate(db)
    dbInstance = db
    bootstrapped = true
    return db
  } catch (error) {
    // Windows cannot rename a file that is still open, so release the handle before backing up.
    if (db !== null) {
      try {
        db.close()
      } catch {}
      db = null
    }
    if (!isCorrupt(error)) throw error
    backupCorruptFile(path)
    const fresh = new Database(path)
    migrate(fresh)
    dbInstance = fresh
    bootstrapped = true
    return fresh
  }
}

/**
 * Long-term stores pick SQLite only after the app itself opened the database.  The lazy
 * in-memory fallback used by unit tests must not flip them to database mode mid-suite.
 */
export function isDatabaseOpen(): boolean {
  return dbInstance !== null && bootstrapped
}

export function closeDatabase(): void {
  if (dbInstance) {
    try {
      dbInstance.pragma('wal_checkpoint(TRUNCATE)')
    } catch {
      /* closing must not throw on quit */
    }
    try {
      dbInstance.close()
    } catch {
      /* ignore a double close */
    }
    dbInstance = null
    bootstrapped = false
  }
}

/**
 * Tests import the main process without Electron's app module; those runs get an isolated
 * in-memory database instead of touching a user profile.  In the real app a missing open() is
 * a bug and must be visible rather than silently discarding every write.
 */
function canUseElectronApp(): boolean {
  return Boolean(process.versions.electron) && typeof app?.getPath === 'function'
}

export function getDatabase(): Database {
  if (dbInstance) return dbInstance
  if (canUseElectronApp()) {
    throw new DatabaseUnavailableError('The conversation database has not been opened.')
  }
  const db = new Database(':memory:')
  migrate(db)
  dbInstance = db
  return db
}

import { readFile, stat } from 'fs/promises'
import { resolve } from 'path'
import { PIL_MIME } from '../../shared/constants/pil-mime'
import { ChangeType } from '../../shared/models/file-change'
import {
  BinaryMetadata,
  DiffHunk,
  DiffLine,
  DiffLineType,
  DocxTextDiff,
  FileDiff
} from '../../shared/models/file-diff'
import { unifiedDiff } from '../../shared/utils/difflib'
import { pyNormalizeRelPath } from '../../shared/utils/py-path'
import { pySplitlines } from '../../shared/utils/pystr'
import { parseUnifiedDiff } from '../../shared/utils/unified-diff'
import { readImageHeader } from '../utils/py-image'
import { docxParagraphTexts, docxParagraphTextsFromFile } from './docx-text.service'
import type { SnapshotStore } from './snapshot-store.service'

async function readFileText(path: string): Promise<string> {
  return (await readFile(path)).toString('utf-8')
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

export class DiffService {
  readonly root: string
  private readonly store: SnapshotStore
  private readonly cache = new Map<string, FileDiff>()
  private readonly MAX_FILE_SIZE = 10 * 1024 * 1024

  constructor(root: string, snapshotStore: SnapshotStore) {
    this.root = resolve(root)
    this.store = snapshotStore
  }

  private normalize(path: string): string {
    return pyNormalizeRelPath(path)
  }

  async computeDiff(
    relPath: string,
    changeType: ChangeType,
    snapshotId: string | null,
    _originalExists: boolean,
    isBinary: boolean,
    fullPath: string
  ): Promise<FileDiff> {
    const normPath = this.normalize(relPath)
    const cacheKey = `${normPath}:${snapshotId}:${changeType}`

    const cached = this.cache.get(cacheKey)
    if (cached) return cached

    try {
      if (changeType !== ChangeType.DELETED) {
        try {
          const size = (await stat(resolve(fullPath))).size
          if (size > this.MAX_FILE_SIZE) {
            return new FileDiff({
              path: normPath,
              change_type: changeType,
              has_error: true,
              error_message: `File too large for diff (${size} bytes > ${this.MAX_FILE_SIZE} bytes)`
            })
          }
        } catch {}
      }

      let diff: FileDiff
      if (changeType === ChangeType.DELETED) {
        diff = await this.computeDeletedDiff(normPath, snapshotId, isBinary)
      } else if (changeType === ChangeType.ADDED) {
        diff = await this.computeAddedDiff(normPath, fullPath, isBinary)
      } else if (changeType === ChangeType.GENERATED) {
        diff = await this.computeGeneratedDiff(normPath, fullPath, isBinary)
      } else if (changeType === ChangeType.DOCX_EDITED) {
        diff = await this.computeDocxDiff(normPath, snapshotId, fullPath)
      } else {
        diff = await this.computeModifiedDiff(normPath, snapshotId, fullPath, isBinary)
      }

      this.cache.set(cacheKey, diff)
      return diff
    } catch (error) {
      return new FileDiff({
        path: normPath,
        change_type: changeType,
        has_error: true,
        error_message: errorMessage(error)
      })
    }
  }

  private async computeDeletedDiff(
    relPath: string,
    snapshotId: string | null,
    isBinary: boolean
  ): Promise<FileDiff> {
    if (isBinary) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.DELETED,
        is_binary: true,
        binary_metadata: await this.getBinaryMetadataFromSnapshot(snapshotId)
      })
    }

    const originalBytes = await this.store.getSnapshotBytes(snapshotId)
    if (!originalBytes) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.DELETED,
        has_error: true,
        error_message: 'Snapshot not found'
      })
    }

    try {
      const originalLines = pySplitlines(originalBytes.toString('utf-8'))
      const hunk = new DiffHunk({
        header: `@@ -1,${originalLines.length} +0,0 @@`,
        old_start: 1,
        old_count: originalLines.length,
        new_start: 0,
        new_count: 0
      })
      originalLines.forEach((line, i) => {
        hunk.lines.push(new DiffLine(line, null, DiffLineType.REMOVED, i + 1))
      })

      return new FileDiff({ path: relPath, change_type: ChangeType.DELETED, hunks: [hunk] })
    } catch (error) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.DELETED,
        is_binary: true,
        has_error: true,
        error_message: `Failed to decode deleted file: ${errorMessage(error)}`
      })
    }
  }

  private async computeAddedDiff(
    relPath: string,
    fullPath: string,
    isBinary: boolean
  ): Promise<FileDiff> {
    const full = resolve(fullPath)

    if (isBinary) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.ADDED,
        is_binary: true,
        binary_metadata: await this.getBinaryMetadataFromFile(full)
      })
    }

    try {
      const currentLines = pySplitlines(await readFileText(full))
      const hunk = new DiffHunk({
        header: `@@ -0,0 +1,${currentLines.length} @@`,
        old_start: 0,
        old_count: 0,
        new_start: 1,
        new_count: currentLines.length
      })
      currentLines.forEach((line, i) => {
        hunk.lines.push(new DiffLine(line, i + 1, DiffLineType.ADDED))
      })

      return new FileDiff({ path: relPath, change_type: ChangeType.ADDED, hunks: [hunk] })
    } catch (error) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.ADDED,
        is_binary: true,
        has_error: true,
        error_message: `Failed to read added file: ${errorMessage(error)}`
      })
    }
  }

  private computeGeneratedDiff(
    relPath: string,
    fullPath: string,
    isBinary: boolean
  ): Promise<FileDiff> {
    return this.computeAddedDiff(relPath, fullPath, isBinary)
  }

  private async computeModifiedDiff(
    relPath: string,
    snapshotId: string | null,
    fullPath: string,
    isBinary: boolean
  ): Promise<FileDiff> {
    const full = resolve(fullPath)

    if (isBinary) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.MODIFIED,
        is_binary: true,
        binary_metadata: await this.getBinaryMetadataFromFile(full)
      })
    }

    const originalBytes = await this.store.getSnapshotBytes(snapshotId)
    if (!originalBytes) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.MODIFIED,
        has_error: true,
        error_message: 'Snapshot not found'
      })
    }

    try {
      const originalText = originalBytes.toString('utf-8')
      const currentText = await readFileText(full)

      if (originalText === currentText) {
        return new FileDiff({ path: relPath, change_type: ChangeType.MODIFIED, hunks: [] })
      }

      const hunks = parseUnifiedDiff(
        unifiedDiff(
          pySplitlines(originalText),
          pySplitlines(currentText),
          `a/${relPath}`,
          `b/${relPath}`,
          '',
          '',
          3,
          ''
        )
      )

      return new FileDiff({ path: relPath, change_type: ChangeType.MODIFIED, hunks })
    } catch (error) {
      return new FileDiff({
        path: relPath,
        change_type: ChangeType.MODIFIED,
        has_error: true,
        error_message: `Failed to compute diff: ${errorMessage(error)}`
      })
    }
  }

  private async computeDocxDiff(
    relPath: string,
    snapshotId: string | null,
    fullPath: string
  ): Promise<FileDiff> {
    const full = resolve(fullPath)

    let originalText = ''
    const originalBytes = await this.store.getSnapshotBytes(snapshotId)
    if (originalBytes) {
      try {
        originalText = (await docxParagraphTexts(originalBytes)).join('\n')
      } catch (error) {
        originalText = `[Could not extract original text: ${errorMessage(error)}]`
      }
    }

    let currentText: string
    try {
      currentText = (await docxParagraphTextsFromFile(full)).join('\n')
    } catch (error) {
      currentText = `[Could not extract current text: ${errorMessage(error)}]`
    }

    const hunks = parseUnifiedDiff(
      unifiedDiff(
        pySplitlines(originalText),
        pySplitlines(currentText),
        `a/${relPath} (text only)`,
        `b/${relPath} (text only)`,
        '',
        '',
        3,
        ''
      )
    )

    return new FileDiff({
      path: relPath,
      change_type: ChangeType.DOCX_EDITED,
      is_binary: true,
      docx_diff: new DocxTextDiff(originalText, currentText, hunks)
    })
  }

  private async getBinaryMetadataFromSnapshot(
    snapshotId: string | null
  ): Promise<BinaryMetadata | null> {
    if (!snapshotId) return null
    const bytes = await this.store.getSnapshotBytes(snapshotId)
    if (!bytes) return null
    return this.extractBinaryMetadata(bytes)
  }

  private async getBinaryMetadataFromFile(filePath: string): Promise<BinaryMetadata | null> {
    try {
      await stat(filePath)
      return this.extractBinaryMetadata(await readFile(filePath))
    } catch {
      return null
    }
  }

  private extractBinaryMetadata(bytes: Buffer): BinaryMetadata {
    const metadata = new BinaryMetadata({ size_bytes: bytes.length })

    const header = readImageHeader(bytes)
    if (header) {
      metadata.is_image = true
      metadata.width = header.width
      metadata.height = header.height
      metadata.format = header.format
      metadata.mime_type = PIL_MIME[header.format] ?? null
    }

    return metadata
  }

  clearCache(): void {
    this.cache.clear()
  }
}

import { resolve } from 'path'
import { getDatabase } from './database.service'

/** SQLite key columns are byte-exact, while Windows paths are case-insensitive. */
export function storageKey(path: string): string {
  const resolved = resolve(path)
  return process.platform === 'win32' ? resolved.toLowerCase() : resolved
}

/** Internal marker so a legacy file is imported exactly once per scope. */
const SEEDED_KEY = '__meta_seeded__'

export class SettingsRepository {
  list(scope: string): Record<string, string> {
    const rows = getDatabase()
      .prepare(
        'SELECT key, value FROM settings WHERE scope = ? AND key != ? ORDER BY rowid'
      )
      .all(scope, SEEDED_KEY) as Array<{ key: string; value: string }>
    return Object.fromEntries(rows.map((row) => [row.key, row.value]))
  }

  has(scope: string, key: string): boolean {
    return Boolean(
      getDatabase().prepare('SELECT 1 FROM settings WHERE scope = ? AND key = ?').get(scope, key)
    )
  }

  isSeeded(scope: string): boolean {
    return this.has(scope, SEEDED_KEY)
  }

  get(scope: string, key: string): string | null {
    const row = getDatabase()
      .prepare('SELECT value FROM settings WHERE scope = ? AND key = ?')
      .get(scope, key) as { value: string } | undefined
    return row?.value ?? null
  }

  setMany(scope: string, entries: Record<string, string>): void {
    const db = getDatabase()
    const now = Date.now()
    const insert = db.prepare(
      `INSERT INTO settings (scope, key, value, updated_at) VALUES (?, ?, ?, ?)
       ON CONFLICT(scope, key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`
    )
    db.transaction(() => {
      for (const [key, value] of Object.entries(entries)) insert.run(scope, key, value, now)
    })()
  }

  /** The most recently written scope among `scopes`, used to keep an existing project's rows. */
  newestExistingScope(scopes: readonly string[]): string | null {
    if (scopes.length === 0) return null
    const placeholders = scopes.map(() => '?').join(', ')
    const row = getDatabase()
      .prepare(
        `SELECT scope FROM settings WHERE scope IN (${placeholders})
         ORDER BY updated_at DESC LIMIT 1`
      )
      .get(...scopes) as { scope: string } | undefined
    return row?.scope ?? null
  }

  /**
   * Inserts the first-run defaults.  Existing keys always win, so a write that happened before
   * the seed is never overwritten.
   */
  seed(scope: string, entries: Record<string, string>): boolean {
    const db = getDatabase()
    const now = Date.now()
    return db.transaction(() => {
      const seeded = db
        .prepare('SELECT 1 FROM settings WHERE scope = ? AND key = ?')
        .get(scope, SEEDED_KEY)
      if (seeded) return false
      const insert = db.prepare(
        'INSERT OR IGNORE INTO settings (scope, key, value, updated_at) VALUES (?, ?, ?, ?)'
      )
      for (const [key, value] of Object.entries(entries)) insert.run(scope, key, value, now)
      insert.run(scope, SEEDED_KEY, '1', now)
      return true
    })()
  }
}

export class MemoryRepository {
  /** The most recently written key among `keys`, used to keep an existing project's document. */
  newestExistingKey(keys: readonly string[]): string | null {
    if (keys.length === 0) return null
    const placeholders = keys.map(() => '?').join(', ')
    const row = getDatabase()
      .prepare(
        `SELECT path FROM memory_docs WHERE path IN (${placeholders})
         ORDER BY updated_at DESC LIMIT 1`
      )
      .get(...keys) as { path: string } | undefined
    return row?.path ?? null
  }

  get(key: string): string | null {
    const row = getDatabase().prepare('SELECT content FROM memory_docs WHERE path = ?').get(key) as
      { content: string } | undefined
    return row?.content ?? null
  }

  insertIfMissing(key: string, content: string): string {
    getDatabase()
      .prepare('INSERT OR IGNORE INTO memory_docs (path, content, updated_at) VALUES (?, ?, ?)')
      .run(key, content, Date.now())
    return this.get(key) ?? content
  }

  write(key: string, content: string): void {
    getDatabase()
      .prepare(
        `INSERT INTO memory_docs (path, content, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(path) DO UPDATE SET content = excluded.content, updated_at = excluded.updated_at`
      )
      .run(key, content, Date.now())
  }

  /** One statement so concurrent sub-agent turns cannot overwrite each other's entry. */
  append(key: string, text: string): void {
    getDatabase()
      .prepare(
        `INSERT INTO memory_docs (path, content, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(path) DO UPDATE SET content = memory_docs.content || excluded.content,
           updated_at = excluded.updated_at`
      )
      .run(key, text, Date.now())
  }
}

export class PendingRepository {
  getManifest(root: string): string | null {
    const row = getDatabase()
      .prepare('SELECT manifest_json FROM pending_manifests WHERE root = ?')
      .get(root) as { manifest_json: string } | undefined
    return row?.manifest_json ?? null
  }

  saveManifest(root: string, manifestJson: string): void {
    getDatabase()
      .prepare(
        `INSERT INTO pending_manifests (root, manifest_json, updated_at) VALUES (?, ?, ?)
         ON CONFLICT(root) DO UPDATE SET manifest_json = excluded.manifest_json,
           updated_at = excluded.updated_at`
      )
      .run(root, manifestJson, Date.now())
  }

  hasSnapshot(root: string, snapshotId: string): boolean {
    return Boolean(
      getDatabase()
        .prepare('SELECT 1 FROM pending_snapshots WHERE root = ? AND snapshot_id = ?')
        .get(root, snapshotId)
    )
  }

  putSnapshot(root: string, snapshotId: string, data: Buffer): void {
    getDatabase()
      .prepare(
        `INSERT OR IGNORE INTO pending_snapshots (root, snapshot_id, data, updated_at)
         VALUES (?, ?, ?, ?)`
      )
      .run(root, snapshotId, data, Date.now())
  }

  getSnapshot(root: string, snapshotId: string): Buffer | null {
    const row = getDatabase()
      .prepare('SELECT data FROM pending_snapshots WHERE root = ? AND snapshot_id = ?')
      .get(root, snapshotId) as { data: Buffer } | undefined
    return row?.data ? Buffer.from(row.data) : null
  }

  deleteSnapshot(root: string, snapshotId: string): void {
    getDatabase()
      .prepare('DELETE FROM pending_snapshots WHERE root = ? AND snapshot_id = ?')
      .run(root, snapshotId)
  }

  listSnapshotIds(root: string): string[] {
    return (
      getDatabase()
        .prepare('SELECT snapshot_id FROM pending_snapshots WHERE root = ? ORDER BY snapshot_id')
        .all(root) as Array<{ snapshot_id: string }>
    ).map((row) => row.snapshot_id)
  }

  clear(root: string): void {
    const db = getDatabase()
    db.transaction(() => {
      db.prepare('DELETE FROM pending_snapshots WHERE root = ?').run(root)
      db.prepare('DELETE FROM pending_manifests WHERE root = ?').run(root)
    })()
  }

  /** One transaction so an interrupted upgrade cannot leave a partial pending-change set. */
  importLegacy(
    root: string,
    manifestJson: string,
    snapshots: Array<[snapshotId: string, data: Buffer]>
  ): void {
    const db = getDatabase()
    const now = Date.now()
    const insertManifest = db.prepare(
      'INSERT OR IGNORE INTO pending_manifests (root, manifest_json, updated_at) VALUES (?, ?, ?)'
    )
    const insertSnapshot = db.prepare(
      'INSERT OR IGNORE INTO pending_snapshots (root, snapshot_id, data, updated_at) VALUES (?, ?, ?, ?)'
    )
    db.transaction(() => {
      insertManifest.run(root, manifestJson, now)
      for (const [id, data] of snapshots) insertSnapshot.run(root, id, data, now)
    })()
  }
}

export const settingsRepository = new SettingsRepository()
export const memoryRepository = new MemoryRepository()
export const pendingRepository = new PendingRepository()

import { AppConstants } from '../../shared/constants/app-constants'
import { EffortMapper } from './effort-mapper.service'

export interface ModelDetail {
  id: string
  display: string
  category: string
  badge: string
  supports_thinking: boolean
  searchable_blob: string
}

export type CatalogItem = [string, string]

export interface RemoteModel {
  name?: string | null
  display_name?: string | null
  displayName?: string | null
}

export interface CatalogClient {
  models?: {
    list(): AsyncIterable<RemoteModel> | RemoteModel[] | Promise<AsyncIterable<RemoteModel>>
  }
}

export class ModelCatalog {
  private static instance: ModelCatalog | null = null

  client: CatalogClient | null
  private cachedItems: CatalogItem[] = []
  private cachedDetails = new Map<string, ModelDetail>()
  private isRefreshing = false
  private onCatalogUpdated: (() => void) | null = null

  constructor(client: CatalogClient | null = null) {
    this.client = client
    this.initializeFromConstants()
  }

  static getInstance(client: CatalogClient | null = null): ModelCatalog {
    if (ModelCatalog.instance === null) {
      ModelCatalog.instance = new ModelCatalog(client)
    } else if (client && ModelCatalog.instance.client === null) {
      ModelCatalog.instance.client = client
    }
    return ModelCatalog.instance
  }

  static resetInstance(): void {
    ModelCatalog.instance = null
  }

  private initializeFromConstants(): void {
    const catalog = AppConstants.MODEL_CATALOG as Record<string, string>
    const items: CatalogItem[] = []
    for (const m of AppConstants.MODELS) {
      items.push([m, catalog[m] ?? m])
    }
    this.cachedItems = items
    this.rebuildDetailsCache()
  }

  private rebuildDetailsCache(): void {
    const details = new Map<string, ModelDetail>()
    for (const [modelId, display] of this.cachedItems) {
      const category = AppConstants.getModelCategory(modelId)
      const badge = AppConstants.getModelBadge(modelId)
      details.set(modelId, {
        id: modelId,
        display,
        category,
        badge,
        supports_thinking: EffortMapper.supportsThinking(modelId),
        searchable_blob: `${display} ${modelId} ${category} ${badge}`.toLowerCase()
      })
    }
    this.cachedDetails = details
  }

  getModels(): CatalogItem[] {
    return [...this.cachedItems]
  }

  getAllDetails(): ModelDetail[] {
    return [...this.cachedDetails.values()]
  }

  getModelInfo(modelId: string): ModelDetail {
    const cached = this.cachedDetails.get(modelId)
    if (cached) return { ...cached }

    const category = AppConstants.getModelCategory(modelId)
    const badge = AppConstants.getModelBadge(modelId)
    const display = (AppConstants.MODEL_CATALOG as Record<string, string>)[modelId] ?? modelId
    return {
      id: modelId,
      display,
      category,
      badge,
      supports_thinking: EffortMapper.supportsThinking(modelId),
      searchable_blob: `${display} ${modelId} ${category} ${badge}`.toLowerCase()
    }
  }

  setUpdateListener(callback: () => void): void {
    this.onCatalogUpdated = callback
  }

  refreshAsync(client?: CatalogClient | null): Promise<void> {
    if (client) this.client = client
    if (!this.client) return Promise.resolve()
    if (this.isRefreshing) return Promise.resolve()

    return this.runRefresh()
  }

  private async runRefresh(): Promise<void> {
    this.isRefreshing = true
    try {
      const catalog = AppConstants.MODEL_CATALOG as Record<string, string>
      const remoteItems: CatalogItem[] = []
      for (const entry of await collectModels(this.client)) {
        const name = (entry?.name || '').replaceAll('models/', '')
        const remoteDisplay = entry?.display_name ?? entry?.displayName ?? ''
        const display = remoteDisplay || (catalog[name] ?? '')
        if (name) remoteItems.push([name, display])
      }

      if (remoteItems.length > 0) {
        const seen = new Set<string>()
        const merged: CatalogItem[] = []
        const orderMap = new Map<string, number>()
        AppConstants.MODELS.forEach((m, idx) => orderMap.set(m, idx))
        for (const [name, display] of remoteItems) {
          seen.add(name)
          merged.push([name, display])
        }
        for (const name of AppConstants.MODELS) {
          if (!seen.has(name)) merged.push([name, catalog[name] ?? ''])
        }
        merged.sort((a, b) => {
          const keyA: [number, string] = [orderMap.get(a[0]) ?? 999, a[0]]
          const keyB: [number, string] = [orderMap.get(b[0]) ?? 999, b[0]]
          if (keyA[0] !== keyB[0]) return keyA[0] < keyB[0] ? -1 : 1
          if (keyA[1] !== keyB[1]) return keyA[1] < keyB[1] ? -1 : 1
          return 0
        })

        this.cachedItems = merged
        this.rebuildDetailsCache()

        if (this.onCatalogUpdated) this.onCatalogUpdated()
      }
    } catch {
    } finally {
      this.isRefreshing = false
    }
  }
}

async function collectModels(client: CatalogClient | null): Promise<RemoteModel[]> {
  const page = await client?.models?.list()
  if (!page) return []
  if (Array.isArray(page)) return page
  const items: RemoteModel[] = []
  for await (const item of page as AsyncIterable<RemoteModel>) items.push(item)
  return items
}

import { AgentState } from '../models/agent-state'
import { AgentTurn } from './agent-turn.service'
import { AgentGenerate } from './agent-generate.service'
import { EffortLevel } from '../../shared/models/effort-level'
import type {
  SubAgentSnapshot,
  ModelSwitchEvent,
  MultiAgentSnapshot
} from '../../shared/types/window'
import { AppConstants } from '../../shared/constants/app-constants'
import { nowStrftime } from '../../shared/utils/strftime'
import { pyTime } from '../../shared/utils/pytime'
import { C } from '../../shared/constants/colors'
import { out } from '../utils/console-out'
import type { Agent } from './agent.service'
import type { AgentMemory } from './agent-memory.service'
import type { AgentSystem } from './agent-system.service'
import type { AgentSettings } from './agent-settings.service'
import type { AgentPaths } from './agent-paths.service'
import type { ChooseHook } from './agent-session.service'
import type { ConversationPersistence } from './conversation-persistence.service'

export type SubAgentStatus = 'idle' | 'running' | 'succeeded' | 'failed' | 'switching'

function pySnippet(text: string, limit = 40): string {
  const clean = text.replace(/\s+/g, ' ').trim()
  return clean.length > limit ? `${clean.slice(0, limit)}...` : clean
}

export interface SubAgentContext {
  id: number
  task: string
  model: string
  effort: EffortLevel
  status: SubAgentStatus
  result: string | null
  error: string | null
  modelSwitches: ModelSwitchEvent[]
  startTime: number
  endTime: number | null
  state: AgentState
  turnEngine: AgentTurn
  generate: AgentGenerate
  conversationId: string | null
}

export class MultiAgentService {
  private readonly agent: Agent
  private enabled = false
  private maxSubAgents = 4
  private subAgents = new Map<number, SubAgentContext>()
  private isRunning = false
  private stopRequested = false
  private nextId = 1

  constructor(
    agent: Agent,
    private readonly memory: AgentMemory,
    private readonly system: AgentSystem,
    private readonly settings: AgentSettings,
    private readonly paths: AgentPaths,
    private readonly choose: ChooseHook,
    private readonly persistence?: ConversationPersistence,
    private readonly parentConversation?: () => string | null,
    private readonly runTurn?: (prompt: string) => Promise<void>
  ) {
    this.agent = agent
  }

  setEnabled(enabled: boolean): void {
    this.enabled = enabled
  }

  isEnabled(): boolean {
    return this.enabled
  }

  setMaxSubAgents(max: number): void {
    this.maxSubAgents = Math.max(2, Math.min(6, max))
  }

  getMaxSubAgents(): number {
    return this.maxSubAgents
  }

  private async runOrchestratorTurn(prompt: string): Promise<void> {
    if (typeof this.runTurn === 'function') await this.runTurn(prompt)
    else await this.agent.turn(prompt)
  }

  /**
   * The plan `orchestrate()` would use for this prompt. Null means the task is handled by a
   * normal single-agent turn, so no multi-agent indicator should appear.
   */
  plan(userText: string): { subTasks: string[]; numAgents: number } | null {
    if (!this.enabled) return null
    if (!this.assessComplexity(userText)) return null
    const subTasks = this.breakIntoSubTasks(userText)
    const numAgents = Math.min(subTasks.length, this.maxSubAgents)
    if (numAgents < 2) return null
    return { subTasks, numAgents }
  }

  /**
   * Main entry point. If multi-agent is disabled or the task is simple, falls back to
   * a normal single-agent turn via this.agent.turn().
   */
  async orchestrate(userText: string): Promise<void> {
    const plan = this.plan(userText)
    if (plan === null) {
      await this.runOrchestratorTurn(userText)
      return
    }

    // Complex task: break into sub-tasks and run in parallel.
    const { subTasks, numAgents } = plan

    this.isRunning = true
    this.stopRequested = false
    this.subAgents.clear()

    // Assign models, spreading across different models to avoid quota collisions.
    const models = this.selectStartingModels(numAgents)

    try {
      await Promise.all(
        subTasks.slice(0, numAgents).map((task, idx) =>
          this.runSubAgent(idx, task, models[idx])
        )
      )

      // Stopping the task must not run an extra orchestrator turn after the sub-agents end.
      if (this.stopRequested) return

      // Orchestrator synthesizes the final answer.
      const combined = this.combineResults()
      const synthesisPrompt =
        `You are the orchestrator of a multi-agent task. The user asked:\n${userText}\n\n` +
        `${subTasks.length} sub-agents worked on independent sub-tasks in parallel. Here are their results:\n\n` +
        combined +
        `\n\nPlease synthesize these into one coherent final answer for the user. ` +
        `If any sub-agent failed, mention it. Do not claim credit for work you did not do.`

      await this.runOrchestratorTurn(synthesisPrompt)
    } finally {
      this.isRunning = false
      this.subAgents.clear()
    }
  }

  private assessComplexity(userText: string): boolean {
    const text = userText.toLowerCase()
    const complexitySignals = [
      'and also', 'then', 'additionally', 'meanwhile', 'separately',
      'independent', 'parallel', 'multiple files', 'several files',
      'update', 'create', 'modify', 'refactor', 'rewrite'
    ]
    let signalCount = 0
    for (const sig of complexitySignals) {
      if (text.includes(sig)) signalCount++
    }
    if (userText.length > 300) signalCount += 1
    const fileMentions = (userText.match(/\b\w+\.\w{2,4}\b/g) ?? []).length
    if (fileMentions >= 2) signalCount += 1
    return signalCount >= 2
  }

  private breakIntoSubTasks(userText: string): string[] {
    const parts = userText.split(/[,;]|(?:\s+and\s+)/i).map((s) => s.trim()).filter((s) => s.length > 0)
    if (parts.length >= 2) return parts
    const sentences = userText.split(/[.!?]+/).map((s) => s.trim()).filter((s) => s.length > 0)
    if (sentences.length >= 2) return sentences
    return [userText]
  }

  private selectStartingModels(count: number): string[] {
    const available = [...AppConstants.MODELS]
    const result: string[] = []
    for (let i = 0; i < count; i++) {
      result.push(available[i % available.length])
    }
    return result
  }

  private async runSubAgent(
    _index: number,
    task: string,
    model: string
  ): Promise<{
    id: number
    status: 'succeeded' | 'failed'
    result: string | null
    error: string | null
    modelUsed: string
    modelSwitches: ModelSwitchEvent[]
    duration: number
  }> {
    const id = this.nextId++
    const effort = this.agent.effortLevel
    const subState = new AgentState(this.agent.state.appRoot, model, false, false)
    // The sub-agent sees the same project the orchestrator is pointed at, not the app folder.
    subState.root = this.agent.state.root
    const ctx: SubAgentContext = {
      id,
      task,
      model,
      effort,
      status: 'running',
      result: null,
      error: null,
      modelSwitches: [],
      startTime: pyTime(),
      endTime: null,
      state: subState,
      turnEngine: null as unknown as AgentTurn,
      generate: null as unknown as AgentGenerate,
      conversationId: null
    }

    // Each sub-agent gets its own child conversation so its transcript survives a restart while
    // staying out of the normal (parent-only) conversation list.
    const parentId = this.parentConversation?.() ?? null
    const child =
      parentId !== null && this.persistence !== undefined
        ? this.persistence.child(parentId, `Sub-Agent ${id}: ${pySnippet(task)}`)
        : null
    if (child !== null) {
      ctx.conversationId = child.conversationId
      child.recordUser(task, { contentIndex: 0 }, child.conversationId)
      ctx.state.onContentAdded = (content) => child.appendContent(content, child.conversationId)
      ctx.state.onContentsTruncated = (length) =>
        child.truncateContents(length, child.conversationId)
      ctx.state.onHistorySummary = (summary) =>
        child.saveSummary(summary, undefined, child.conversationId)
    }

    // Build isolated services for this sub-agent.
    ctx.generate = new AgentGenerate(ctx.state, this.agent.client, this.system)
    ctx.turnEngine = new AgentTurn({
      state: ctx.state,
      paths: this.paths,
      memory: this.memory,
      system: this.system,
      settings: this.settings,
      generate: ctx.generate,
      execute: (name, args) => this.agent.tools.execute(name, args),
      choose: this.choose,
      effort: () => effort.displayName,
      onAssistantReply: (text, meta) => {
        if (child === null) return
        const timestamp = nowStrftime('%H:%M:%S')
        child.recordAssistant(text, {
          model: ctx.state.lastRoutedModel ?? ctx.state.model,
          effortLevel: effort.displayName,
          event: {
            kind: 'assistant',
            text,
            meta,
            header: `${meta || 'GemiBot AI'}  •  ${timestamp}`,
            timestamp
          }
        })
      }
    })

    // Override the model for this sub-agent's generate ladder.
    ctx.state.model = model
    ctx.state.cancelRequested = false

    // Wire up callbacks so errors/tool results are captured in this sub-agent context.
    ctx.state.onError = (_userMsg, _rawErr) => {
      out(`  ${C.YELLOW}Sub-Agent ${id} error${C.RESET}`)
    }
    ctx.state.onToolError = (_toolName, _toolErr) => {
      out(`  ${C.YELLOW}Sub-Agent ${id} tool error${C.RESET}`)
    }
    ctx.state.onTimelineEvent = (event) => {
      if (child !== null) {
        child.recordAction(event, {
          model: ctx.state.lastRoutedModel ?? ctx.state.model,
          effortLevel: effort.displayName
        })
      }
      if (event.tool === 'model_failover') {
        const args = event.args as Record<string, unknown> | undefined
        const from = args?.requested as string | undefined
        const to = args?.routed_to as string | undefined
        const reason = (event.output as string) ?? ''
        if (from && to) {
          ctx.modelSwitches.push({ fromModel: from, toModel: to, reason, timestamp: nowStrftime('%H:%M:%S') })
          ctx.status = 'switching'
          this.emitSubAgentUpdate(id, 'switching', to, undefined, undefined, ctx.conversationId)
        }
      }
    }

    this.subAgents.set(id, ctx)
    this.emitSubAgentUpdate(id, 'running', model, undefined, undefined, ctx.conversationId)

    try {
      if (this.stopRequested) {
        ctx.status = 'failed'
        ctx.error = 'Stopped by user'
        ctx.endTime = pyTime()
        this.emitSubAgentUpdate(id, 'failed', model, undefined, ctx.error, ctx.conversationId)
        return {
          id,
          status: 'failed',
          result: null,
          error: ctx.error,
          modelUsed: model,
          modelSwitches: ctx.modelSwitches,
          duration: ctx.endTime - ctx.startTime
        }
      }

      await ctx.turnEngine.turn(task)

      // The turn engine swallows errors and user stops, so its outcome flags decide the status.
      if (this.stopRequested || ctx.status === 'failed' || !ctx.state.lastTurnSucceeded) {
        if (ctx.status !== 'failed') {
          const cancelled = this.stopRequested || ctx.state.lastTurnCancelled
          ctx.status = 'failed'
          ctx.error = cancelled
            ? 'Stopped by user'
            : (ctx.state.lastTurnError ?? 'Turn did not complete')
          ctx.endTime = pyTime()
          this.emitSubAgentUpdate(id, 'failed', model, undefined, ctx.error, ctx.conversationId)
        }
        return {
          id,
          status: 'failed',
          result: null,
          error: ctx.error,
          modelUsed: ctx.state.model,
          modelSwitches: ctx.modelSwitches,
          duration: (ctx.endTime ?? pyTime()) - ctx.startTime
        }
      }

      ctx.status = 'succeeded'
      ctx.result = this.extractLastAssistantText(ctx.state)
      ctx.endTime = pyTime()
      this.emitSubAgentUpdate(id, 'succeeded', model, ctx.result, undefined, ctx.conversationId)

      return {
        id,
        status: 'succeeded',
        result: ctx.result,
        error: null,
        modelUsed: ctx.state.model,
        modelSwitches: ctx.modelSwitches,
        duration: ctx.endTime - ctx.startTime
      }
    } catch (e) {
      const errMsg = e instanceof Error ? e.message : String(e)
      ctx.endTime = pyTime()
      // Avoid duplicate 'failed' emission if stopSubAgent() already set it.
      if (ctx.status !== 'failed') {
        ctx.status = 'failed'
        ctx.error = errMsg
        this.emitSubAgentUpdate(id, 'failed', model, undefined, errMsg, ctx.conversationId)
      }
      return {
        id,
        status: 'failed',
        result: null,
        error: errMsg,
        modelUsed: ctx.state.model,
        modelSwitches: ctx.modelSwitches,
        duration: ctx.endTime - ctx.startTime
      }
    }
  }

  private stopSubAgent(id: number): void {
    const ctx = this.subAgents.get(id)
    if (!ctx) return
    // Do not overwrite a sub-agent that already completed (success or failure).
    if (ctx.status === 'succeeded' || ctx.status === 'failed') return
    ctx.status = 'failed'
    ctx.error = 'Stopped by user'
    ctx.endTime = pyTime()
    ctx.turnEngine.cancel()
    this.emitSubAgentUpdate(id, 'failed', ctx.model, undefined, ctx.error, ctx.conversationId)
  }

  stopAllSubAgents(): void {
    this.stopRequested = true
    for (const [id] of this.subAgents) {
      this.stopSubAgent(id)
    }
  }

  getSubAgentSnapshot(id: number): SubAgentSnapshot | null {
    const ctx = this.subAgents.get(id)
    if (!ctx) return null
    return {
      id: ctx.id,
      task: ctx.task,
      model: ctx.state.model,
      effort: ctx.effort.displayName,
      status: ctx.status,
      result: ctx.result,
      error: ctx.error,
      fileChanges: [],
      modelSwitches: ctx.modelSwitches
    }
  }

  getAllSubAgentSnapshots(): SubAgentSnapshot[] {
    return Array.from(this.subAgents.values()).map((ctx) => ({
      id: ctx.id,
      task: ctx.task,
      model: ctx.state.model,
      effort: ctx.effort.displayName,
      status: ctx.status,
      result: ctx.result,
      error: ctx.error,
      fileChanges: [],
      modelSwitches: ctx.modelSwitches
    }))
  }

  getMultiAgentSnapshot(): MultiAgentSnapshot {
    const subAgents = this.getAllSubAgentSnapshots()
    const total = subAgents.length
    const completed = subAgents.filter((s) => s.status === 'succeeded' || s.status === 'failed').length
    const activeIdx = subAgents.findIndex((s) => s.status === 'running')
    return {
      isActive: this.isRunning,
      orchestratorModel: this.agent.model,
      subAgents,
      activeSubAgentIdx: activeIdx >= 0 ? activeIdx : null,
      totalSubTasks: total,
      completedSubTasks: completed
    }
  }

  private extractLastAssistantText(state: AgentState): string | null {
    const contents = state.contents
    for (let i = contents.length - 1; i >= 0; i--) {
      const c = contents[i]
      if ((c.role ?? '') === 'model' || (c.role ?? '') === 'assistant') {
        const parts = c.parts ?? []
        for (const p of parts) {
          if (p.text && !(p.thought ?? false)) return p.text
        }
      }
    }
    return null
  }

  private combineResults(): string {
    const lines: string[] = []
    // Iterate over actual sub-agent contexts (IDs start at 1, not 0).
    for (const ctx of this.subAgents.values()) {
      const n = ctx.id
      if (ctx.status === 'succeeded' && ctx.result) {
        lines.push(`## Sub-Agent ${n}\n${ctx.result}`)
      } else {
        lines.push(`## Sub-Agent ${n}\n**Status:** Failed\n**Error:** ${ctx.error ?? 'unknown error'}`)
      }
    }
    return lines.join('\n\n')
  }

  private emitSubAgentUpdate(
    id: number,
    status: SubAgentStatus,
    model: string,
    result?: string | null,
    error?: string | null,
    conversationId?: string | null
  ): void {
    const state = this.agent.state
    if (typeof state.onTimelineEvent === 'function') {
      const ev: Record<string, unknown> = {
        type: 'sub-agent',
        subAgentIdx: id,
        status,
        model,
        timestamp: nowStrftime('%H:%M:%S')
      }
      if (result !== undefined) ev['result'] = result
      if (error !== undefined) ev['error'] = error
      if (conversationId) ev['conversationId'] = conversationId
      try {
        state.onTimelineEvent(ev)
      } catch {}
    }
  }
}

export default MultiAgentService

import { createHash } from 'crypto'
import type { Stats } from 'fs'
import { mkdir, readFile, readdir, rename, rm, stat, unlink, writeFile } from 'fs/promises'
import { dirname, join, resolve } from 'path'
import { isBinary } from '../../shared/utils/text'
import { out } from '../utils/console-out'
import { isDatabaseOpen } from './database.service'
import { pendingRepository, storageKey } from './long-term-repository.service'

export interface PendingManifest {
  changes: Record<string, unknown>
  reads: Record<string, string>
}

const EMPTY_MANIFEST: PendingManifest = { changes: {}, reads: {} }

export class SnapshotStore {
  root: string
  pendingDir: string
  snapshotsDir: string
  manifestFile: string
  private readonly database: boolean
  private rootKey: string

  constructor(root: string) {
    this.root = resolve(root)
    this.pendingDir = join(this.root, '.gemibot', 'pending')
    this.snapshotsDir = join(this.pendingDir, 'snapshots')
    this.manifestFile = join(this.pendingDir, 'manifest.json')
    this.database = isDatabaseOpen()
    this.rootKey = storageKey(this.root)
    if (!this.database) void this.ensureDirs()
  }

  setRoot(root: string): void {
    this.root = resolve(root)
    this.pendingDir = join(this.root, '.gemibot', 'pending')
    this.snapshotsDir = join(this.pendingDir, 'snapshots')
    this.manifestFile = join(this.pendingDir, 'manifest.json')
    this.rootKey = storageKey(this.root)
    if (!this.database) void this.ensureDirs()
  }

  private async ensureDirs(): Promise<void> {
    try {
      await mkdir(this.snapshotsDir, { recursive: true })
    } catch {}
  }

  async saveSnapshot(
    relPath: string,
    fullPath: string
  ): Promise<[string | null, boolean, boolean]> {
    const target = resolve(fullPath)
    if (!(await this.exists(target))) return [null, false, false]

    try {
      const raw = await readFile(target)
      const isBin = isBinary(raw)
      const snapId = createHash('sha256')
        .update(Buffer.from(relPath, 'utf-8'))
        .update(raw)
        .digest('hex')
        .slice(0, 16)

      if (this.database) {
        if (!pendingRepository.hasSnapshot(this.rootKey, snapId)) {
          pendingRepository.putSnapshot(this.rootKey, snapId, raw)
        }
        return [snapId, true, isBin]
      }

      await this.ensureDirs()
      const snapPath = join(this.snapshotsDir, snapId)
      if (!(await this.exists(snapPath))) await writeFile(snapPath, raw)
      return [snapId, true, isBin]
    } catch (error) {
      out(`Warning: Failed to create snapshot for ${relPath}: ${errorMessage(error)}`)
      return [null, true, false]
    }
  }

  async restoreSnapshot(
    snapshotId: string | null,
    fullPath: string,
    originalExists: boolean
  ): Promise<boolean> {
    const target = resolve(fullPath)
    try {
      if (!originalExists) {
        const info = await this.statOrNull(target)
        if (info?.isFile()) await unlink(target)
        else if (info?.isDirectory()) await rm(target, { recursive: true, force: true })
        return true
      }

      if (snapshotId) {
        if (this.database) {
          const data = pendingRepository.getSnapshot(this.rootKey, snapshotId)
          if (data !== null) {
            await mkdir(dirname(target), { recursive: true })
            await writeFile(target, data)
            return true
          }
          return false
        }
        const snapPath = join(this.snapshotsDir, snapshotId)
        if (await this.exists(snapPath)) {
          await mkdir(dirname(target), { recursive: true })
          await writeFile(target, await readFile(snapPath))
          return true
        }
      }
      return false
    } catch (error) {
      out(`Error restoring snapshot ${snapshotId} to ${target}: ${errorMessage(error)}`)
      return false
    }
  }

  async getSnapshotBytes(snapshotId: string | null): Promise<Buffer | null> {
    if (!snapshotId) return null
    if (this.database) return pendingRepository.getSnapshot(this.rootKey, snapshotId)
    const snapPath = join(this.snapshotsDir, snapshotId)
    try {
      if (await this.exists(snapPath)) return await readFile(snapPath)
      return null
    } catch {
      return null
    }
  }

  async deleteSnapshot(snapshotId: string | null): Promise<void> {
    if (!snapshotId) return
    if (this.database) {
      pendingRepository.deleteSnapshot(this.rootKey, snapshotId)
      return
    }
    const snapPath = join(this.snapshotsDir, snapshotId)
    try {
      if (await this.exists(snapPath)) await unlink(snapPath)
    } catch {}
  }

  async saveManifest(data: PendingManifest): Promise<void> {
    if (this.database) {
      pendingRepository.saveManifest(this.rootKey, JSON.stringify(data, null, 2))
      return
    }
    await this.ensureDirs()
    try {
      const tempFile = join(this.pendingDir, 'manifest.tmp')
      await writeFile(tempFile, JSON.stringify(data, null, 2), 'utf-8')
      await rename(tempFile, this.manifestFile)
    } catch (error) {
      out(`Warning: Failed to save pending changes manifest: ${errorMessage(error)}`)
    }
  }

  async loadManifest(): Promise<PendingManifest> {
    if (this.database) {
      const stored = pendingRepository.getManifest(this.rootKey)
      if (stored !== null) return parseManifest(stored)
      // First database run: carry over the v1.0 pending set once, then SQLite owns it.
      const legacy = await this.readLegacyManifest()
      const snapshots = await this.readLegacySnapshots()
      pendingRepository.importLegacy(this.rootKey, JSON.stringify(legacy), snapshots)
      return legacy
    }
    return await this.readLegacyManifest()
  }

  private async readLegacyManifest(): Promise<PendingManifest> {
    if (!(await this.exists(this.manifestFile))) return { changes: {}, reads: {} }
    try {
      return parseManifest(await readFile(this.manifestFile, 'utf-8'))
    } catch {
      return { changes: {}, reads: {} }
    }
  }

  private async readLegacySnapshots(): Promise<Array<[string, Buffer]>> {
    let ids: string[]
    try {
      ids = await readdir(this.snapshotsDir)
    } catch {
      return []
    }
    const snapshots: Array<[string, Buffer]> = []
    for (const id of ids) {
      try {
        snapshots.push([id, await readFile(join(this.snapshotsDir, id))])
      } catch {
        /* an unreadable backup snapshot stays on disk */
      }
    }
    return snapshots
  }

  async clearAll(): Promise<void> {
    if (this.database) {
      pendingRepository.clear(this.rootKey)
      // Keep an empty manifest so the legacy files are not imported a second time.
      pendingRepository.saveManifest(this.rootKey, JSON.stringify(EMPTY_MANIFEST))
      return
    }
    try {
      await rm(this.snapshotsDir, { recursive: true, force: true })
      await unlink(this.manifestFile).catch(() => undefined)
      await this.ensureDirs()
    } catch {}
  }

  async listSnapshotIds(): Promise<string[]> {
    if (this.database) return pendingRepository.listSnapshotIds(this.rootKey)
    try {
      return (await readdir(this.snapshotsDir)).sort()
    } catch {
      return []
    }
  }

  private async statOrNull(path: string): Promise<Stats | null> {
    try {
      return await stat(path)
    } catch {
      return null
    }
  }

  private async exists(path: string): Promise<boolean> {
    return (await this.statOrNull(path)) !== null
  }
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function parseManifest(text: string): PendingManifest {
  try {
    const parsed = JSON.parse(text) as Partial<PendingManifest> | null
    if (parsed === null || typeof parsed !== 'object') return { changes: {}, reads: {} }
    return {
      changes: typeof parsed.changes === 'object' && parsed.changes !== null ? parsed.changes : {},
      reads: typeof parsed.reads === 'object' && parsed.reads !== null ? parsed.reads : {}
    }
  } catch {
    return { changes: {}, reads: {} }
  }
}

