      this.emit({ kind: 'target-error', text: null })
      this.syncStats()
      this.pill(`Target set to: ${this.agent.state.root}`, '\u{1F4C1}')
    } else {
      this.emit({ kind: 'target-error', text: msg })
      this.pill(`Target error: ${msg}`, '⚠️')
