  private async onModeChange(val: string): Promise<void> {
    const state = this.agent.state
    const mode = val.toLowerCase()
    state.mode = mode
    state.activeFunction = mode === 'plan' || mode === 'read' ? mode : 'all'
    await this.agent.buildSystem()
    await this.agent.saveSettings({ mode: state.mode, function_suite: state.activeFunction })
    this.syncStats()
    this.pill(`Mode switched to ${mode.toUpperCase()} (Suite: ${state.activeFunction})`)
  }

  private async onFunctionChangeDisplay(selectedDisplay: string): Promise<void> {
    const state = this.agent.state
    const funcCode = this.catalogs.funcDisplayToCode.get(selectedDisplay) ?? selectedDisplay
    if (funcCode === 'pip_installer') {
      this.actionPip()
      this.syncStats()
      return
    }
    state.activeFunction = funcCode
    state.mode = ['build', 'plan', 'read'].includes(funcCode) ? funcCode : 'build'
    await this.agent.buildSystem()
    await this.agent.saveSettings({ function_suite: funcCode, mode: state.mode })
    this.syncStats()
    this.pill(`Suite activated: ${selectedDisplay} [${funcCode}]`)
  }

  private async onModelChangeDisplay(selectedDisplay: string): Promise<void> {
    const modelId = this.catalogs.modelDisplayToId.get(selectedDisplay) ?? selectedDisplay
    this.agent.model = modelId
    this.agent.state.pinned = true
    await this.agent.saveSettings({ model: modelId })
    if (this.agent.modelController) await this.agent.modelController.selectModel(modelId)
    if (this.agent.model !== selectedDisplay) this.configureModelButton(selectedDisplay)
    this.syncEffortDisplay()
    this.syncStats()
    this.pill(`AI Model changed: ${selectedDisplay} (${modelId})`)
  }

  private async onModelSelectedFromModal(modelId: string, displayName: string): Promise<void> {
    this.agent.model = modelId
    this.agent.state.pinned = true
    await this.agent.saveSettings({ model: modelId })
    if (this.agent.modelController) await this.agent.modelController.selectModel(modelId)
    this.configureModelButton(displayName)
    this.syncEffortDisplay()
    this.syncStats()
    this.pill(`AI Model changed: ${displayName} (${modelId})`)
  }

  private async onEffortSelectedFromModal(effortLevel: EffortLevel): Promise<void> {
    this.agent.effortLevel = effortLevel
    await this.agent.saveSettings({ effort_level: effortLevel.value })
    if (this.agent.modelController) await this.agent.modelController.selectEffortLevel(effortLevel)
    this.syncEffortDisplay()
    this.pill(
      `Reasoning Effort set to: ${effortLevel.icon} ${effortLevel.displayName} (${effortLevel.costHint})`
    )
  }

  private async onFontSizeChange(selectedLabel: string): Promise<void> {
    const [newSize, scale] = FONT_SIZE_MAP.get(selectedLabel) ?? DEFAULT_FONT_CFG
    this.fontSize = newSize
    this.scale = scale
    this.emit({ kind: 'font-scale', label: selectedLabel, size: newSize, scale })
    this.scaleLabel = selectedLabel
    await this.agent.saveSettings({ ui_scale: `${newSize}px`, ui_scale_label: selectedLabel })
    this.pill(`Applied UI font scale: ${newSize}px (${Math.trunc(scale * 100)}%)`, '\u{1F524}')
  }

  private async onEditUserMessage(
    text: string,
    cpIdx: number | null,
    rowId: number,
    dbId?: number
  ): Promise<void> {
    if (this.isGenerating) return
    this.emit({ kind: 'input', text, focus: true })
    if (cpIdx !== null && cpIdx >= 0 && cpIdx < this.agent.checkpoints.length) {
      await this.agent.rollbackToCheckpoint(cpIdx)
      this.pill(`Rolled back to prompt #${cpIdx + 1} for edit.`, '↩️')
      this.syncStats()
    }
    if (dbId !== undefined && this.currentConversationId !== null) {
      const row = this.persistence.message(dbId)
      const cut = row !== null ? storedContentIndex(row) : null
      // Never hide rows the store failed to delete; the error card already reports the failure.
      if (!this.persistence.clearFrom(dbId, cut)) return
      if (cut !== null) this.agent.state.truncateContents(cut)
    }
    this.emit({ kind: 'truncate-chat', rowId })
  }

  private isBusy(): boolean {
    // A send that is still probing will start a turn against the live state, so a conversation
    // switch during that window would land the turn in the wrong conversation.
    return this.isGenerating || this.isMultiAgentRunning || this.isStarting
  }

  private resetLiveConversationState(): void {
    const state = this.agent.state
    state.contents = []
    state.checkpoints = []
    state.undoStack = []
    state.lastRoutedModel = null
    state.historySummary = null
    this.queue = []
    this.loadedHistoryStartId = null
    this.loadedHistoryHasMore = false
  }

  private async displayConversation(conversationId: string | null): Promise<void> {
    if (conversationId === null || !this.persistence.exists(conversationId)) {
      this.persistence.use(null)
      this.resetLiveConversationState()
      this.emit({
        kind: 'history-reset',
        events: [this.assistantEvent(WELCOME_MESSAGE)],
        hasMore: false
      })
      this.emit({ kind: 'queue-sync', items: [] })
      this.syncStats()
      this.broadcastConversations(null)
      return
    }

    const contents = this.persistence.contents(conversationId)
    await this.adoptConversation(conversationId, contents)
    this.queue = this.persistence.loadQueue(conversationId)
    const page = this.persistence.page(null, HISTORY_PAGE_SIZE)
    this.loadedHistoryStartId = page.rows.length > 0 ? page.rows[0].id : null
    this.loadedHistoryHasMore = page.hasMore
    const events = this.timelineFromRows(page.rows)
    this.emit({
      kind: 'history-reset',
      events: events.length > 0 ? events : [this.assistantEvent(WELCOME_MESSAGE)],
      hasMore: page.hasMore
    })
    this.emit({ kind: 'queue-sync', items: [...this.queue] })
    this.syncStats()
    this.broadcastConversations(conversationId)
  }

  private async onConversationNew(): Promise<void> {
    if (this.isBusy()) return
    await this.displayConversation(null)
  }

  private async onConversationOpen(id: string): Promise<void> {
    if (this.isBusy()) return
    await this.displayConversation(id)
  }

  private onConversationRename(id: string, title: string): void {
    const clean = pyStrip(title)
    if (!clean) return
    if (!this.persistence.rename(id, clean)) return
    this.broadcastConversations()
  }

  private async onConversationDelete(id: string): Promise<void> {
    if (this.isBusy()) return
    const wasActive = this.currentConversationId === id
    if (!this.persistence.remove(id)) return
    if (wasActive) {
      const last = this.persistence.last()
      const nextId = last !== null && typeof last.id === 'string' && last.id !== '' ? last.id : null
      await this.displayConversation(nextId)
      return
    }
    this.broadcastConversations()
  }

  private async onConversationExport(id: string, format: 'md' | 'json'): Promise<void> {
    const conversation = this.persistence.get(id)
    if (conversation === null) return
    const save = this.transport.saveConversationFile
    if (typeof save !== 'function') return
    const path = await save(exportFileName(conversation.title, format), format)
    if (path === null) return
    try {
      const messages = this.persistence.allMessages(id)
      const content =
        format === 'json'
          ? conversationToJson(conversation, messages)
          : conversationToMarkdown(conversation, messages)
      const text = process.platform === 'win32' ? content.replaceAll('\n', '\r\n') : content
      writeFileSync(path, text, 'utf8')
      this.pill(`Exported conversation to ${pyPathName(path)}`, '📥')
    } catch (e) {
      this.pill(`Export failed: ${errorMessage(e)}`, '⚠️')
    }
  }

  private onLoadOlder(): void {
    if (this.loadingOlder) return
    if (!this.loadedHistoryHasMore || this.currentConversationId === null) return
    this.loadingOlder = true
    try {
      const page = this.persistence.page(this.loadedHistoryStartId, HISTORY_PAGE_SIZE)
      if (page.rows.length > 0) this.loadedHistoryStartId = page.rows[0].id
      this.loadedHistoryHasMore = page.hasMore
      this.emit({
        kind: 'history-prepend',
        events: this.timelineFromRows(page.rows),
        hasMore: page.hasMore
      })
    } finally {
      this.loadingOlder = false
    }
  }

  private async onOpenDataFolder(): Promise<void> {
    const open = this.transport.openDataFolder
    if (typeof open === 'function') await open()
  }

  private copyToClipboard(text: string): void {
    try {
      this.transport.writeClipboard(text)
      this.pill('Copied to clipboard!', '\u{1F4CB}')
    } catch (e) {
      this.pill(`Copy failed: ${errorMessage(e)}`, '⚠️')
    }
  }

  private async openFileInEditor(rel: string): Promise<void> {
    try {
      const full = await this.agent.resolvePath(rel)
      if (!existsSync(full)) {
        this.pill(`File not found: ${rel}`, '⚠️')
        return
      }
      const failure = await this.transport.openPath(full)
      if (failure) throw new Error(failure)
      this.pill(`Opened ${rel}`, '\u{1F4C2}')
    } catch (e) {
      this.pill(`Could not open file: ${errorMessage(e)}`, '⚠️')
    }
  }

  async dispatch(cmd: WindowCommand): Promise<void> {
    switch (cmd.cmd) {
      case 'send':
        return await this.sendMessage(cmd.text)
      case 'action':
        return await this.runAction(cmd.name)
      case 'stop': {
        this.stopGeneration()
        return
      }
      case 'accept-all':
        return await this.onAcceptAllChanges()
      case 'reject-all':
        return await this.onRejectAllChanges()
      case 'accept-file':
        return await this.onAcceptFileChange(cmd.path)
      case 'reject-file':
        return await this.onRejectFileChange(cmd.path)
      case 'review-open':
        return this.openReviewPanel()
      case 'review-panel-close':
        this.reviewController.onPanelDestroy()
        return
      case 'target-apply':
        return await this.onTargetApply(cmd.path)
      case 'target-browse':
        return await this.onTargetBrowse()
      case 'target-clear':
        return await this.onTargetClear()
      case 'mode-change':
        return await this.onModeChange(cmd.value)
      case 'function-change':
        return await this.onFunctionChangeDisplay(cmd.display)
      case 'model-change':
        return await this.onModelChangeDisplay(cmd.display)
      case 'model-picker':
        return this.openModelPicker()
      case 'model-selected':
        return await this.onModelSelectedFromModal(cmd.modelId, cmd.display)
      case 'effort-selected':
        return await this.onEffortSelectedFromModal(EffortLevel.fromString(cmd.value))
      case 'font-scale':
        return await this.onFontSizeChange(cmd.label)
      case 'edit-user':
        return await this.onEditUserMessage(cmd.text, cmd.cpIdx, cmd.rowId, cmd.dbId)
      case 'copy':
        return this.copyToClipboard(cmd.text)
      case 'copy-path':
        return this.copyToClipboard(await this.agent.resolvePath(cmd.rel))
      case 'open-file':
        return await this.openFileInEditor(cmd.rel)
      case 'export-timeline':
        return this.writeTimelineExport(cmd.path, cmd.content)
      case 'queue-add':
        // Handled by sendMessage() which pushes to this.queue and emits queue-add event
        return undefined
      case 'queue-process':
        // Process next queued message (handled by onTurnFinished / processQueue)
        return undefined
      case 'queue-delete':
        return await this.handleQueueDelete(cmd.index)
      case 'queue-edit':
        return await this.handleQueueEdit(cmd.index, cmd.text)
      case 'queue-send-now':
        return await this.handleQueueSendNow(cmd.index)
      case 'multi-agent-start':
        return await this.handleMultiAgentStart(cmd.orchestratorModel, cmd.totalSubTasks)
      case 'multi-agent-stop':
        return this.handleMultiAgentStop(cmd.subAgentIdx)
      case 'multi-agent-enable':
        if (this.multiAgent) {
          this.multiAgent.setEnabled(cmd.enabled)
          await this.agent.saveSettings({ multi_agent_enabled: String(cmd.enabled) })
          this.pill(`Multi-Agent mode ${cmd.enabled ? 'enabled' : 'disabled'}`, '\u{1F916}')
        }
        return
      case 'multi-agent-max':
        if (this.multiAgent) {
          this.multiAgent.setMaxSubAgents(cmd.max)
          await this.agent.saveSettings({
            multi_agent_max_sub_agents: String(this.multiAgent.getMaxSubAgents())
          })
          this.pill(`Max sub-agents set to ${this.multiAgent.getMaxSubAgents()}`, '\u{1F916}')
        }
        return
      case 'conversation-new':
        return await this.onConversationNew()
      case 'conversation-open':
        return await this.onConversationOpen(cmd.id)
      case 'conversation-rename':
        return this.onConversationRename(cmd.id, cmd.title)
      case 'conversation-delete':
        return await this.onConversationDelete(cmd.id)
      case 'conversation-export':
        return await this.onConversationExport(cmd.id, cmd.format)
      case 'load-older':
        return this.onLoadOlder()
      case 'open-data-folder':
        return await this.onOpenDataFolder()
    }
  }
}

import { resolve } from 'path'
import { EffortLevel } from '../../shared/models/effort-level'
import { SettingsStorage } from './settings-storage.service'

export class SettingsStore {
  static readonly DEFAULT_EFFORT = EffortLevel.MEDIUM
  static readonly DEFAULT_MODEL = 'gemini-3.5-flash-lite'

  readonly storage: SettingsStorage

  constructor(appRoot: string) {
    this.storage = new SettingsStorage(resolve(appRoot))
  }

  async getModel(): Promise<string> {
    try {
      const settings = await this.storage.readSettingsDict()
      const model = (settings['model'] ?? '').trim()
      if (model) return model
    } catch {}
    return SettingsStore.DEFAULT_MODEL
  }

  async setModel(model: string): Promise<void> {
    if (!model) return
    await this.storage.saveSettings({ model: String(model).trim() })
  }

  async getEffortLevel(): Promise<EffortLevel> {
    try {
      const settings = await this.storage.readSettingsDict()
      const rawLevel = (settings['effort_level'] ?? '').trim()
      if (rawLevel) return EffortLevel.fromString(rawLevel)
    } catch {}
    return SettingsStore.DEFAULT_EFFORT
  }

  async setEffortLevel(effortLevel: unknown): Promise<void> {
    const level = EffortLevel.fromString(effortLevel)
    await this.storage.saveSettings({ effort_level: level.value })
  }

  async getAll(): Promise<Record<string, string>> {
    try {
      return await this.storage.readSettingsDict()
    } catch {
      return {}
    }
  }

  async update(updates: Record<string, string>): Promise<void> {
    await this.storage.saveSettings(updates)
  }
}

import { readFile } from 'fs/promises'
import { C } from '../../shared/constants/colors'
import { WRITE_NAMES } from '../../shared/constants/tool-definitions'
import { ChangeType } from '../../shared/models/file-change'
import { KeyboardInterrupt, ToolError, errorMessage } from '../../shared/utils/exceptions'
import { pyRound } from '../../shared/utils/pyformat'
import { pyStr, pyTypeName } from '../../shared/utils/pystr'
import { pyTime } from '../../shared/utils/pytime'
import { makeUnifiedDiff } from '../../shared/utils/difflib'
import type { TurnFileChange } from '../../shared/utils/memory-entry'
import { clip } from '../../shared/utils/text'
import { nowStrftime } from '../../shared/utils/strftime'
import { out, outRaw, printDiff } from '../utils/console-out'
import { pyResolve } from '../utils/fs-path'
import type { AgentState, TimelineEvent } from '../models/agent-state'
import type { AgentGenerate } from '../services/agent-generate.service'
import type { AgentPaths } from '../services/agent-paths.service'
import type { AgentSystem } from '../services/agent-system.service'
import type { AiClient } from '../services/ai-client.service'
import type { ChangeTracker } from '../services/change-tracker.service'
import type { FileOperations } from '../services/file-operations.service'
import { bindArgs, type ToolContext, type ToolSpec } from './tool-contract'
import { FILE_TOOLS } from './file-tools'
import { DATA_TOOLS } from './data-tools'
import { IMAGE_TOOLS } from './image-tools'
import { WEB_TOOLS } from './web-tools'
import { DOCX_TOOLS } from './doc-tools'
import { EXCEL_TOOLS } from './sheet-tools'
import { PDF_TOOLS } from './pdf-tools'
import { PPTX_TOOLS } from './pptx-tools'
import { VOICE_TOOLS } from './voice-tools'
import { VIDEO_TOOLS } from './video-tools'
import { ARCHIVE_TOOLS } from './archive-tools'
import { SYSTEM_TOOLS } from './system-tools'

export interface AgentToolsDeps {
  state: AgentState
  paths: AgentPaths
  system: AgentSystem
  generate: AgentGenerate
  client: AiClient
  fileOps: FileOperations
  changeTracker: ChangeTracker
  readLine?: (prompt: string) => Promise<string | null>
}

const TOOLS: Record<string, ToolSpec> = {
  ...FILE_TOOLS,
  ...WEB_TOOLS,
  ...IMAGE_TOOLS,
  ...DOCX_TOOLS,
  ...EXCEL_TOOLS,
  ...PDF_TOOLS,
  ...PPTX_TOOLS,
  ...VOICE_TOOLS,
  ...VIDEO_TOOLS,
  ...DATA_TOOLS,
  ...ARCHIVE_TOOLS,
  ...SYSTEM_TOOLS
}

function errTypeName(error: unknown): string {
  if (error instanceof Error) return error.name
  return pyTypeName(error)
}

export class AgentTools {
  readonly ctx: ToolContext
  private readonly specs: Map<string, ToolSpec> = new Map()
  private readonly readLine: (prompt: string) => Promise<string | null>

  constructor(deps: AgentToolsDeps) {
    this.readLine = deps.readLine ?? (async () => null)
    for (const [name, spec] of Object.entries(TOOLS)) this.specs.set(name, spec)
    this.ctx = {
      ...deps,
      allowed: (tool, detail) => this.allowed(tool, detail),
      commit: (tool, full, rel, oldText, newText, crlf, what, why) =>
        this.commit(tool, full, rel, oldText, newText, crlf, what, why),
      beginBinaryArtifact: (full) => this.beginBinaryArtifact(full),
      recordBinaryArtifact: (full, actionLabel, summaryNote) =>
        this.recordBinaryArtifact(full, actionLabel, summaryNote),
      checkCommandPaths: (command) => this.checkCommandPaths(command),
      printTodos: () => this.printTodos()
    }
  }

  toolNames(): string[] {
    return [...this.specs.keys()].sort()
  }

  private emit(
    name: string,
    args: Record<string, unknown>,
    output: string,
    isError: boolean,
    status: string,
    duration: number | null,
    fileChanges: TurnFileChange[]
  ): void {
    const state = this.ctx.state
    const ev: TimelineEvent = {
      type: 'action',
      tool: name,
      args,
      output,
      is_error: isError,
      status,
      ...(duration === null ? {} : { duration }),
      timestamp: nowStrftime('%H:%M:%S'),
      file_changes: fileChanges
    }
    state.turnTimelineEvents.push(ev)
    state.journal?.recordEvent(ev)
    if (typeof state.onTimelineEvent === 'function') {
      try {
        state.onTimelineEvent(ev)
      } catch {}
    }
  }

  async execute(name: string, args: Record<string, unknown>): Promise<Record<string, unknown>> {
    const state = this.ctx.state
    const t0 = pyTime()
    const fileChgBefore = state.turnFileChanges.length

    if ((state.mode === 'plan' || state.mode === 'read') && WRITE_NAMES.has(name)) {
      const errMsg =
        `Tool '${name}' is disabled in ${state.mode.toUpperCase()} mode. ` +
        'Switch to /build or /function.'
      state.turnToolLogs.push({ tool: name, args, raw_output: errMsg, is_error: true })
      this.emit(name, args, errMsg, true, 'Failed', null, [])
      return { error: errMsg }
    }

    const spec = this.specs.get(name)
    if (!spec) {
      const errMsg = `Unknown tool: ${name}`
      state.turnToolLogs.push({ tool: name, args, raw_output: errMsg, is_error: true })
      this.emit(name, args, errMsg, true, 'Failed', null, [])
      return { error: errMsg }
    }

    try {
      const rawOut = pyStr(await spec.run(this.ctx, bindArgs(spec, args)))
      const dur = pyRound(pyTime() - t0, 3)
      const exitMatch = name === 'run_command' ? /^exit code (-?\d+)/u.exec(rawOut) : null
      const failedExit = exitMatch !== null && Number(exitMatch[1]) !== 0
      const newChgs = state.turnFileChanges.slice(fileChgBefore).map((c) => ({ ...c }))
      state.turnToolLogs.push({
        tool: name,
        args,
        raw_output: rawOut,
        is_error: failedExit,
        duration: dur
      })
      this.emit(name, args, rawOut, failedExit, failedExit ? 'Failed' : 'Success', dur, newChgs)
      return { output: clip(rawOut) }
    } catch (e) {
      if (e instanceof KeyboardInterrupt) throw e

      if (e instanceof ToolError) {
        const errMsg = errorMessage(e)
        const dur = pyRound(pyTime() - t0, 3)
        const newChgs = state.turnFileChanges.slice(fileChgBefore).map((c) => ({ ...c }))
        const statusVal = errMsg.toLowerCase().includes('denied') ? 'Denied' : 'Failed'
        state.turnToolLogs.push({
          tool: name,
          args,
          raw_output: errMsg,
          is_error: true,
          duration: dur
        })
        this.emit(name, args, errMsg, true, statusVal, dur, newChgs)
        return { error: errMsg }
      }

      const raw = errorMessage(e)
      const errMsg =
        e instanceof Error && e.name === 'TypeError'
          ? `Bad arguments: ${raw}`
          : `${errTypeName(e)}: ${raw}`
      const dur = pyRound(pyTime() - t0, 3)
      state.turnToolLogs.push({
        tool: name,
        args,
        raw_output: errMsg,
        is_error: true,
        duration: dur
      })
      this.emit(name, args, errMsg, true, 'Failed', dur, [])
      return { error: errMsg }
    }
  }

  async allowed(tool: string, detail: string): Promise<boolean> {
    const state = this.ctx.state
    if (state.autoYes || state.always.has(tool)) return true

    if (typeof state.onPermission === 'function') {
      try {
        const res = await state.onPermission(tool, detail)
        const trusted = res === 'always' || res === 'a'
        const ok = trusted || Boolean(res)
        if (trusted) state.always.add(tool)
        state.journal?.record(
          `Permission ${ok ? 'Accepted' : 'Rejected'}`,
          `${tool}: ${detail}${trusted ? ' (always)' : ''}`
        )
        return ok
      } catch {}
    }

    const mon = state.escMonitor
    if (mon) mon.pause()
    try {
      out(
        `\n  ${C.YELLOW}- Permission Required${C.RESET} [${C.BOLD}${tool}${C.RESET}] ` +
          `${C.DIM}${detail}${C.RESET}`
      )
      const prompt = `  ${C.YELLOW}- Allow? [y]es / [a]lways / [n]o - ${C.RESET}`
      for (;;) {
        outRaw(prompt)
        const answer = await this.readLine(prompt)
        if (answer === null) return false
        const clean = answer.trim().toLowerCase()
        if (clean === 'y' || clean === 'yes') return true
        if (clean === 'a' || clean === 'always') {
          state.always.add(tool)
          return true
        }
        if (clean === 'n' || clean === 'no' || clean === '') return false
      }
    } finally {
      if (mon) mon.resume()
    }
  }

  async commit(
    tool: string,
    full: string,
    rel: string,
    oldText: string | null,
    newText: string,
    crlf: boolean,
    what = '',
    why = ''
  ): Promise<string> {
    const { state, fileOps } = this.ctx
    printDiff(rel, oldText || '', newText, oldText === null)
    if (!(await this.allowed(tool, rel))) {
      throw new ToolError(
        'The user denied this change. Do not retry it; ask what they want instead.'
      )
    }
    state.undoStack.push([full, oldText, crlf])
    const diffStr = makeUnifiedDiff(rel, oldText || '', newText).join('\n')
    const ctype = oldText === null ? ChangeType.ADDED : ChangeType.MODIFIED
    await fileOps.writeTextFile(full, newText, crlf, ctype, diffStr, what, why)
    state.turnFileChanges.push({
      action: oldText === null ? 'created' : 'modified',
      path: rel,
      diff: diffStr,
      old_content: oldText,
      new_content: newText
    })
    return `${oldText === null ? 'Created' : 'Updated'} ${rel}`
  }

  async beginBinaryArtifact(fullPath: string): Promise<void> {
    const state = this.ctx.state
    const rel = this.ctx.paths.rel(fullPath)
    const oldBytes = await readFile(fullPath).catch(() => null)
    state.undoStack.push(
      oldBytes === null ? [fullPath, null, false] : [fullPath, null, false, oldBytes]
    )
    // Snapshot before the write so reject/undo can restore the original bytes.
    await this.ctx.changeTracker.recordChange(
      rel,
      fullPath,
      oldBytes === null ? ChangeType.ADDED : ChangeType.MODIFIED,
      '',
      true,
      '',
      ''
    )
  }

  async recordBinaryArtifact(
    fullPath: string,
    actionLabel: string,
    summaryNote: string
  ): Promise<void> {
    const state = this.ctx.state
    const rel = this.ctx.paths.rel(fullPath)
    const top = state.undoStack[state.undoStack.length - 1]
    if (!top || top[0] !== fullPath) state.undoStack.push([fullPath, null, false])
    const act = actionLabel.toLowerCase()
    let ctype: ChangeType
    if (
      act.includes('image') ||
      act.includes('generate') ||
      act.includes('uhd') ||
      act.includes('qr')
    )
      ctype = ChangeType.GENERATED
    else if (act.includes('docx') || act.includes('doc')) ctype = ChangeType.DOCX_EDITED
    else ctype = ChangeType.ADDED
    await this.ctx.changeTracker.recordChange(rel, fullPath, ctype, summaryNote, true, '', '')
    state.turnFileChanges.push({
      action: actionLabel,
      path: rel,
      diff: `Binary/Media artifact ${actionLabel}: ${rel}\n${summaryNote}`,
      old_content: null,
      new_content: summaryNote
    })
  }

  checkCommandPaths(command: string): string[] {
    const suspicious: string[] = []
    if (command.includes('..')) suspicious.push("parent traversal ('..')")
    for (const match of command.matchAll(/([A-Za-z]:[\\/][^\s"'<>|]+)/g)) {
      const pathStr = match[1].replace(/[,;.]+$/u, '')
      try {
        if (!this.ctx.paths.isWithinTarget(pyResolve(pathStr))) suspicious.push(pathStr)
      } catch {}
    }
    return suspicious
  }

  printTodos(): void {
    const todos = this.ctx.state.todos as Array<Record<string, unknown>>
    if (todos.length === 0) {
      out(`  ${C.DIM}No active todos.${C.RESET}`)
      return
    }
    const marks: Record<string, string> = { completed: '-', in_progress: '-', pending: '-' }
    out(`\n  ${C.GRAY}- ${C.BOLD}Tasks${C.RESET}`)
    for (const t of todos) {
      const status = (t['status'] ?? 'pending') as string
      const color = status === 'completed' ? C.GREEN : status === 'in_progress' ? C.YELLOW : C.DIM
      out(`  ${C.GRAY}- ${color}${marks[status] ?? '-'} ${t['content'] ?? ''}${C.RESET}`)
    }
    out(`  ${C.GRAY}-`)
  }
}

import { link, readFile, stat, symlink, writeFile } from 'fs/promises'
import { dirname, win32 } from 'path'

import JSZip from 'jszip'

import { AppConstants } from '../../shared/constants/app-constants'
import { ChangeType } from '../../shared/models/file-change'
import { PythonError, ToolError } from '../../shared/utils/exceptions'
import { pyBytesRepr } from '../../shared/utils/pyrepr'
import { pyStr, pyStrip, pyTypeName } from '../../shared/utils/pystr'
import {
  checkZipDate,
  readTarMembers,
  rglobFiles,
  tarTree,
  writeTarGz,
  zipArcName,
  zipExtractTarget
} from '../utils/py-archive'
import { mkdirParents, osError, statNotFoundWinError2 } from '../utils/py-oserror'
import { qrPayloadBytes, qrPayloadSummary, qrPngBytes, qrSymbol } from '../utils/py-qrcode'
import { pathArg, type ToolContext, type ToolSpec } from './tool-contract'

function actionText(value: unknown): string {
  return value instanceof Uint8Array ? pyBytesRepr(value) : pyStr(value)
}

function normalizedAction(value: unknown): string | null {
  if (typeof value === 'string') return pyStrip(value.toLowerCase())
  if (value instanceof Uint8Array) return null
  throw new PythonError('AttributeError', `'${pyTypeName(value)}' object has no attribute 'lower'`)
}

function truncateAtNul(path: string): string {
  const nul = path.indexOf('\u0000')
  return nul < 0 ? path : path.slice(0, nul)
}

async function isFile(path: string): Promise<boolean> {
  const info = await stat(path).catch(() => null)
  return info !== null && info.isFile()
}

async function raise<T>(at: string, fn: () => Promise<T>): Promise<T> {
  try {
    return await fn()
  } catch (error) {
    if (error instanceof PythonError || error instanceof ToolError) throw error
    throw osError(error, at)
  }
}

async function writeZip(
  dst: string,
  entries: { name: string; data: Buffer; date: Date }[]
): Promise<void> {
  const zip = new JSZip()
  const generate = (): Promise<Buffer> =>
    zip.generateAsync({
      type: 'nodebuffer',
      compression: 'DEFLATE',
      compressionOptions: { level: 6 }
    })
  for (const entry of entries) {
    try {
      checkZipDate(entry.date)
    } catch (error) {
      await writeFile(dst, await generate())
      throw error
    }
    zip.file(entry.name, entry.data, { date: entry.date, createFolders: false })
  }
  await writeFile(dst, await generate())
}

async function extractZip(zip: JSZip, dst: string, ctx: ToolContext): Promise<void> {
  for (const key of Object.keys(zip.files)) {
    const entry = zip.files[key]
    const name = entry.unsafeOriginalName ?? key
    const isDir = name.endsWith('/')
    const target = truncateAtNul(zipExtractTarget(dst, name, isDir))
    if (isDir || entry.dir) {
      await mkdirParents(target).catch(() => undefined)
      continue
    }
    await mkdirParents(dirname(target)).catch(() => undefined)
    const data = await entry.async('nodebuffer')
    await trackExtracted(ctx, dst, target)
    await writeFile(target, data)
  }
}

async function trackExtracted(
  ctx: ToolContext,
  dst: string,
  target: string
): Promise<void> {
  if (!insideDir(dst, target)) {
    throw new PythonError('ReadError', `Member '${target}' would be extracted outside '${dst}'`)
  }
  const changeType = (await isFile(target)) ? ChangeType.MODIFIED : ChangeType.ADDED
  await ctx.changeTracker.recordChange(
    ctx.paths.rel(target),
    target,
    changeType,
    'Extracted from archive',
    false,
    '',
    ''
  )
}

function insideDir(parent: string, target: string): boolean {
  const rel = win32.relative(win32.resolve(parent), win32.resolve(target))
  return rel !== '' && !rel.startsWith('..') && !win32.isAbsolute(rel)
}

async function extractTar(
  members: Awaited<ReturnType<typeof readTarMembers>>,
  dst: string,
  ctx: ToolContext
): Promise<void> {
  const written = new Set<string>()
  for (const member of members) {
    const isDir = member.typeflag === '5'
    const target = truncateAtNul(zipExtractTarget(dst, member.name, isDir))
    if (!isDir && !insideDir(dst, target)) {
      throw new PythonError(
        'ReadError',
        `Member '${member.name}' would be extracted outside '${dst}'`
      )
    }
    if (isDir) {
      await mkdirParents(target).catch(() => undefined)
      written.add(member.name)
      continue
    }
    if (member.typeflag === '2') {
      const linkTarget = win32.resolve(win32.dirname(target), member.linkName)
      if (win32.isAbsolute(member.linkName) || !insideDir(dst, linkTarget)) {
        throw new PythonError(
          'ReadError',
          `Link '${member.name}' points outside '${dst}'`
        )
      }
      await mkdirParents(dirname(target)).catch(() => undefined)
      await symlink(member.linkName, target)
      written.add(member.name)
      continue
    }
    if (member.typeflag === '1') {
      const source = written.has(member.linkName)
        ? truncateAtNul(zipExtractTarget(dst, member.linkName, false))
        : null
      if (!source) throw new PythonError('KeyError', `"linkname '${member.linkName}' not found"`)
      await mkdirParents(dirname(target)).catch(() => undefined)
      await link(source, target)
      written.add(member.name)
      continue
    }
    await mkdirParents(dirname(target)).catch(() => undefined)
    await trackExtracted(ctx, dst, target)
    await writeFile(target, member.data)
    written.add(member.name)
  }
}

const archiveManage: ToolSpec = {
  python: 'tool_archive_manage',
  params: [
    { name: 'action', required: true },
    { name: 'source', required: true },
    { name: 'destination', required: true }
  ],
  run: async (ctx, args) => {
    const src = await ctx.paths.resolve(pathArg(args.source))
    const dst = await ctx.paths.resolve(pathArg(args.destination))
    if (
      !(await ctx.allowed(
        'archive_manage',
        `${actionText(args.action)}: ${ctx.paths.rel(src)} -> ${ctx.paths.rel(dst)}`
      ))
    )
      throw new ToolError('The user denied archive operation.')

    const act = normalizedAction(args.action)
    if (act === 'zip') {
      await mkdirParents(dirname(dst))
      const entries: { name: string; data: Buffer; date: Date }[] = []
      if (await isFile(src)) {
        entries.push({
          name: zipArcName(win32.basename(src)),
          data: await readFile(src),
          date: (await stat(src)).mtime
        })
      } else {
        for (const full of await rglobFiles(src, AppConstants.IGNORED))
          entries.push({
            name: zipArcName(win32.relative(src, full)),
            data: await readFile(full),
            date: (await stat(full)).mtime
          })
      }
      await raise(dst, () => writeZip(dst, entries))
      return `Created ZIP archive ${ctx.paths.rel(dst)}`
    }

    if (act === 'unzip') {
      await mkdirParents(dst)
      const bytes = await raise(src, () => readFile(src))
      let zip: JSZip
      try {
        zip = await JSZip.loadAsync(bytes)
      } catch {
        throw new PythonError('BadZipFile', 'File is not a zip file')
      }
      await raise(dst, () => extractZip(zip, dst, ctx))
      return `Extracted ${ctx.paths.rel(src)} to ${ctx.paths.rel(dst)}`
    }

    if (act === 'tar') {
      await mkdirParents(dirname(dst))
      if (!(await stat(src).catch(() => null))) throw statNotFoundWinError2(src)
      const tree = await tarTree(src, zipArcName(win32.basename(src)))
      await raise(dst, () => writeTarGz(dst, tree))
      return `Created TAR.GZ archive ${ctx.paths.rel(dst)}`
    }

    if (act === 'untar') {
      await mkdirParents(dst)
      const members = await raise(src, () => readTarMembers(src))
      await raise(dst, () => extractTar(members, dst, ctx))
      return `Extracted ${ctx.paths.rel(src)} to ${ctx.paths.rel(dst)}`
    }

    throw new ToolError(`Unknown archive action: ${actionText(args.action)}`)
  }
}

const qrGenerate: ToolSpec = {
  python: 'tool_qr_generate',
  params: [
    { name: 'data', required: true },
    { name: 'output_path', required: true }
  ],
  run: async (ctx, args) => {
    const full = await ctx.paths.resolve(pathArg(args.output_path))
    const rel = ctx.paths.rel(full)
    if (!(await ctx.allowed('qr_generate', rel)))
      throw new ToolError('The user denied QR generation.')

    await mkdirParents(dirname(full))
    const symbol = qrSymbol(qrPayloadBytes(args.data))
    await ctx.beginBinaryArtifact(full)
    await raise(full, () => writeFile(full, qrPngBytes(symbol)))
    const summary = `Generated QR code at ${rel} for payload: ${qrPayloadSummary(args.data)}`
    await ctx.recordBinaryArtifact(full, 'created', summary)
    return summary
  }
}

