const PY_S =
  '[\\t\\n\\v\\f\\r\\x1c\\x1d\\x1e\\x20\\x85\\xa0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]'

export async function httpGet(
  url: string,
  headers: Record<string, string>,
  timeoutMs: number,
  maxBytes: number | null = null
): Promise<{ bytes: Uint8Array; contentType: string | null }> {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  try {
    let response: Response
    try {
      response = await fetch(url, { headers, signal: controller.signal, redirect: 'follow' })
    } catch (e) {
      throw new Error(`<urlopen error ${errorMessage(e)}>`, { cause: e })
    }
    if (!response.ok) throw new Error(`HTTP Error ${response.status}: ${response.statusText}`)

    const chunks: Uint8Array[] = []
    let total = 0
    const reader = response.body?.getReader()
    if (reader) {
      for (;;) {
        const { done, value } = await reader.read()
        if (done || !value) break
        chunks.push(value)
        total += value.byteLength
        if (maxBytes !== null && total >= maxBytes) {
          await reader.cancel()
          break
        }
      }
    }
    const limit = maxBytes === null ? total : Math.min(total, maxBytes)
    const bytes = new Uint8Array(limit)
    let offset = 0
    for (const chunk of chunks) {
      const take = Math.min(chunk.byteLength, limit - offset)
      if (take > 0) bytes.set(chunk.subarray(0, take), offset)
      offset += take
      if (offset >= limit) break
    }
    return { bytes, contentType: response.headers.get('content-type') }
  } finally {
    clearTimeout(timer)
  }
}

function decodeBody(bytes: Uint8Array, contentType: string | null): string {
  const charset = contentCharset(contentType) ?? 'utf-8'
  try {
    return new TextDecoder(charset).decode(bytes)
  } catch {
    throw new PythonError('LookupError', `unknown encoding: ${charset}`)
  }
}

function contentCharset(contentType: string | null): string | null {
  if (!contentType) return null
  for (const part of contentType.split(';').slice(1)) {
    const [name, ...rest] = part.trim().split('=')
    if (name.toLowerCase() === 'charset') {
      const value = rest.join('=').trim().replaceAll(/^"|"$/gu, '')
      return value || null
    }
  }
  return null
}

interface DomNode {
  type?: string
  data?: string
  children?: DomNode[]
}

function getTextStrip(root: DomNode | undefined): string {
  if (!root) return ''
  const parts: string[] = []
  const visit = (node: DomNode): void => {
    if (node.type === 'text') {
      parts.push(node.data ?? '')
      return
    }
    if (node.type === 'comment' || node.type === 'directive') return
    for (const child of node.children ?? []) visit(child)
  }
  visit(root)
  return parts
    .map(pyStrip)
    .filter((part) => part !== '')
    .join('')
}

const searchGrounding: ToolSpec = {
  python: 'tool_search_grounding',
  params: [{ name: 'query', required: true }],
  run: async (_ctx, args) => {
    const cleanQ = pyStrip(pyStr(pyOr(args.query, '')))
    if (!cleanQ) throw new ToolError('Search query cannot be empty.')
    const url = `https://html.duckduckgo.com/html/?q=${pyQuote(cleanQ)}`
    try {
      const { bytes } = await httpGet(
        url,
        { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Gemibot/2.0' },
        15000
      )
      const rawHtml = new TextDecoder('utf-8').decode(bytes)
      const $ = cheerio.load(rawHtml)
      const results: string[] = []
      $('.result')
        .slice(0, 5)
        .each((_, element) => {
          const row = $(element)
          const title = row.find('.result__title')
          const snippet = row.find('.result__snippet')
          const link = row.find('.result__url')
          if (title.length > 0 && snippet.length > 0) {
            results.push(
              `• **${getTextStrip(title.get(0) as DomNode | undefined)}**\n  ${getTextStrip(
                snippet.get(0) as DomNode | undefined
              )}\n  Source: ${link.length > 0 ? getTextStrip(link.get(0) as DomNode | undefined) : ''}`
            )
          }
        })
      if (results.length > 0) {
        return `Google Search Grounding Results for '${cleanQ}':\n\n${results.join('\n\n')}`
      }
    } catch (e) {
      return `Search Grounding query for '${cleanQ}' completed (${errorMessage(e)}).`
    }
    return `Google Search Grounding executed for: ${cleanQ}`
  }
}

function dictGet(obj: Record<string, unknown>, key: string, fallback: string): string {
  if (Object.prototype.hasOwnProperty.call(obj, key)) return pyStr(obj[key])
  return fallback
}

const mapGrounding: ToolSpec = {
  python: 'tool_map_grounding',
  params: [
    { name: 'location', required: true },
    { name: 'query', default: null }
  ],
  run: async (_ctx, args) => {
    const loc = pyStrip(pyStr(pyOr(args.location, '')))
    if (!loc) throw new ToolError('Location cannot be empty.')
    const query = args.query
    const q = pyTruthy(query) ? pyStrip(`${loc} ${pyStr(query)}`) : loc
    const url =
      `https://nominatim.openstreetmap.org/search?q=${pyQuote(q)}` +
      '&format=json&addressdetails=1&limit=5'
    try {
      const { bytes } = await httpGet(url, { 'User-Agent': 'Gemibot-Map-Grounding/2.0' }, 15000)
      const data = JSON.parse(new TextDecoder('utf-8').decode(bytes)) as Record<string, unknown>[]
      if (pyTruthy(data)) {
        const items: string[] = []
        for (const place of data.slice(0, 3)) {
          const name = dictGet(place, 'display_name', '')
          const lat = dictGet(place, 'lat', '')
          const lon = dictGet(place, 'lon', '')
          const placeType = dictGet(place, 'type', '')
          items.push(
            `• **${name}**\n  Type: ${placeType} | Coordinates: ${lat}, ${lon}\n` +
              `  Google Maps: https://www.google.com/maps/search/?api=1&query=${lat},${lon}`
          )
        }
        return `Google Maps Grounding for '${loc}':\n\n${items.join('\n\n')}`
      }
    } catch {}
    return `Google Maps Grounding for: ${loc}\nURL: https://www.google.com/maps/search/${pyQuote(loc)}`
  }
}

const webFetch: ToolSpec = {
  python: 'tool_web_fetch',
  params: [{ name: 'url', required: true }],
  run: async (ctx, args) => {
    const url = pyStr(args.url)
    if (!/^https?:\/\//.test(url)) throw new ToolError('Only http and https URLs are supported')
    if (!(await ctx.allowed('web_fetch', url))) throw new ToolError('The user denied this request.')

    let response: { bytes: Uint8Array; contentType: string | null }
    try {
      response = await httpGet(url, { 'User-Agent': 'Mozilla/5.0 (Gemibot CLI)' }, 20000, 2_000_000)
    } catch (e) {
      throw new ToolError(`Request failed: ${errorMessage(e)}`)
    }

    let text = decodeBody(response.bytes, response.contentType)
    text = text.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
    text = text.replace(/<[^>]+>/gs, ' ')
    text = htmlUnescape(text).replace(/[ \t]+/g, ' ')
    text = text.replace(new RegExp(`\\n${PY_S}*\\n+`, 'g'), '\n\n')
    return pyStrip(text)
  }
}

export const WEB_TOOLS: Record<string, ToolSpec> = {
  search_grounding: searchGrounding,
  map_grounding: mapGrounding,
  web_fetch: webFetch
}

import { AppConstants } from '../../shared/constants/app-constants'
import { C } from '../../shared/constants/colors'
import { KeyboardInterrupt } from '../../shared/utils/exceptions'
import { pyRstrip, pySlice, pyStrip } from '../../shared/utils/pystr'
import { makeUnifiedDiff } from '../../shared/utils/difflib'
import { wrap } from '../../shared/utils/textwrap'
import type { EscMonitor } from '../models/agent-state'

type ConsoleSink = (text: string, terminator: string) => void

const sinks = new Set<ConsoleSink>()

export function onConsoleOutput(sink: ConsoleSink): () => void {
  sinks.add(sink)
  return () => sinks.delete(sink)
}

export function out(text = ''): void {
  process.stdout.write(`${text}\n`)
  for (const sink of sinks) {
    try {
      sink(text, '\n')
    } catch {}
  }
}

export function outRaw(text: string): void {
  process.stdout.write(text)
  for (const sink of sinks) {
    try {
      sink(text, '')
    } catch {}
  }
}

export function sleep(seconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, seconds * 1000))
}

export type ShowFn = (
  label: string,
  text: string,
  color: string,
  meta?: string,
  escMonitor?: EscMonitor | null
) => Promise<void>

async function consoleShow(
  label: string,
  text: string,
  color: string,
  meta = '',
  escMonitor: EscMonitor | null = null
): Promise<void> {
  const width = AppConstants.WIDTH
  const headerMeta = meta ? ` ${C.GRAY}- ${meta}${C.RESET}` : ''
  out(`\n${color}│${C.RESET} ${color}${C.BOLD}${label}${C.RESET}${headerMeta}`)
  let inCode = false
  for (const line of pyRstrip(text).split('\n')) {
    if (escMonitor?.check()) throw new KeyboardInterrupt()
    if (pyStrip(line).startsWith('```')) {
      inCode = !inCode
      const lang = pyStrip(pySlice(pyStrip(line), 3))
      const tag = inCode && lang ? ` ${C.BG_BADGE} ${lang} ${C.RESET}` : ''
      out(`${color}│${C.RESET} ${C.GRAY}${'-'.repeat(Math.min(40, width - 4))}${C.RESET}${tag}`)
      continue
    }
    if (inCode || pyStrip(line) === '') {
      const codeColor = inCode ? C.CYAN : ''
      const reset = inCode ? C.RESET : ''
      out(`${color}│${C.RESET}   ${codeColor}${line}${reset}`)
      continue
    }
    const wrapped = wrap(line, width - 2, { subsequentIndent: '' })
    for (const part of wrapped.length > 0 ? wrapped : ['']) {
      if (escMonitor?.check()) throw new KeyboardInterrupt()
      out(`${color}│${C.RESET} ${part}`)
      if (escMonitor) await sleep(0.004)
    }
  }
}

let showImpl: ShowFn = consoleShow

export function setShowImpl(fn: ShowFn | null): ShowFn {
  const previous = showImpl
  showImpl = fn ?? consoleShow
  return previous
}

export function show(
  label: string,
  text: string,
  color: string,
  meta = '',
  escMonitor: EscMonitor | null = null
): Promise<void> {
  return showImpl(label, text, color, meta, escMonitor)
}

export function printDiff(
  rel: string,
  oldText: string | null,
  newText: string | null,
  isNew: boolean
): void {
  const badge = isNew ? `${C.GREEN}+ CREATED${C.RESET}` : `${C.YELLOW}~ MODIFIED${C.RESET}`
  out(`\n  ${C.GRAY}- ${badge} ${C.BOLD}${rel}${C.RESET}`)
  const diff = makeUnifiedDiff(rel, oldText, newText)
  for (const line of diff.slice(2, 82)) {
    let color: string = C.DIM
    if (line.startsWith('+')) color = C.GREEN
    else if (line.startsWith('-')) color = C.RED
    else if (line.startsWith('@@')) color = C.CYAN
    out(`  ${C.GRAY}- ${color}${line}${C.RESET}`)
  }
  if (diff.length > 82) {
    out(`  ${C.GRAY}- ${C.DIM}... ${diff.length - 82} more diff lines${C.RESET}`)
  }
  out(`  ${C.GRAY}-`)
}

import { lstat, readdir, stat } from 'fs/promises'
import type { Dirent } from 'fs'
import { PythonError } from '../../shared/utils/exceptions'

function escapeLiteral(ch: string): string {
  return /[\\^$.*+?()[\]{}|/]/u.test(ch) ? `\\${ch}` : ch
}

export function fnmatchTranslateSegment(pat: string, star: string, questionMark: string): string[] {
  const res: string[] = []
  let i = 0
  const n = pat.length
  while (i < n) {
    const c = pat[i] as string
    i += 1
    if (c === '*') {
      if (res.length === 0 || res[res.length - 1] !== star) res.push(star)
    } else if (c === '?') {
      res.push(questionMark)
    } else if (c === '[') {
      let j = i
      if (j < n && pat[j] === '!') j += 1
      if (j < n && pat[j] === ']') j += 1
      while (j < n && pat[j] !== ']') {
        if (pat[j] === '\\') j += 1
        j += 1
      }
      if (j >= n) {
        res.push('\\\\[')
        continue
      }
      const from = i
      let stuff = pat.slice(from, j)
      i = j + 1
      if (!stuff.includes('-')) {
        stuff = stuff.replaceAll('\\', '\\\\')
      } else {
        const chunks: string[] = []
        let start = from
        let k = pat[from] === '!' ? from + 2 : from + 1
        for (;;) {
          const at = pat.indexOf('-', k)
          if (at < 0 || at >= j) break
          chunks.push(pat.slice(start, at))
          start = at + 1
          k = at + 3
        }
        const chunk = pat.slice(start, j)
        if (chunk) chunks.push(chunk)
        else chunks[chunks.length - 1] += '-'
        for (let m = chunks.length - 1; m > 0; m--) {
          if (chunks[m - 1][chunks[m - 1].length - 1] > chunks[m][0]) {
            chunks[m - 1] = chunks[m - 1].slice(0, -1) + chunks[m].slice(1)
            chunks.splice(m, 1)
          }
        }
        stuff = chunks.map((part) => part.replaceAll('\\', '\\\\').replaceAll('-', '\\-')).join('-')
      }
      stuff = stuff.replace(/[&~|]/gu, '\\$&')
      if (!stuff) res.push('(?!)')
      else if (stuff === '!') res.push('[\\s\\S]')
      else {
        if (stuff[0] === '!') stuff = `^${stuff.slice(1)}`
        else if (stuff[0] === '^' || stuff[0] === '[') stuff = `\\${stuff}`
        res.push(`[${stuff}]`)
      }
    } else {
      res.push(escapeLiteral(c))
    }
  }
  return res
}

const ANY_SEP = '\\\\'
const NOT_SEP = '[^\\\\]'
const ONE_LAST_SEGMENT = `${NOT_SEP}+`
const ONE_SEGMENT = `${ONE_LAST_SEGMENT}${ANY_SEP}`
const ANY_SEGMENTS = `(?:[\\s\\S]+${ANY_SEP})?`
const ANY_LAST_SEGMENTS = '[\\s\\S]*'

export function globTranslate(pat: string): string {
  const parts = pat.split('\\')
  const last = parts.length - 1
  const results: string[] = []
  parts.forEach((part, idx) => {
    if (part === '*') {
      results.push(idx < last ? ONE_SEGMENT : ONE_LAST_SEGMENT)
    } else if (part === '**') {
      if (idx < last) {
        if (parts[idx + 1] !== '**') results.push(ANY_SEGMENTS)
      } else results.push(ANY_LAST_SEGMENTS)
    } else {
      if (part) results.push(...fnmatchTranslateSegment(part, `${NOT_SEP}*`, NOT_SEP))
      if (idx < last) results.push(ANY_SEP)
    }
  })
  return `^(?:${results.join('')})$`
}

const compiled = new Map<string, RegExp>()

function compileGlob(pat: string): RegExp {
  let re = compiled.get(pat)
  if (!re) {
    re = new RegExp(globTranslate(pat), 'i')
    compiled.set(pat, re)
  }
  return re
}

type Matcher = (text: string, pos: number) => boolean

function compileMatcher(pat: string): Matcher {
  const re = compileGlob(pat)
  return (text, pos) => {
    re.lastIndex = 0
    return re.test(pos === 0 ? text : text.slice(pos))
  }
}

const MAGIC_CHECK = /[*?[]/u

const SPECIAL_PARTS = ['', '.', '..']

type Selector = (path: string, exists: boolean) => AsyncGenerator<string>

class Globber {
  selector(parts: string[]): Selector {
    if (parts.length === 0) return selectExists
    const part = parts.pop() as string
    if (part === '**') return this.recursiveSelector(part, parts)
    if (SPECIAL_PARTS.includes(part)) return this.specialSelector(part, parts)
    if (!MAGIC_CHECK.test(part)) return this.literalSelector(part, parts)
    return this.wildcardSelector(part, parts)
  }

  private specialSelector(part: string, parts: string[]): Selector {
    const selectNext = this.selector(parts)
    return async function* (path, exists) {
      yield* selectNext(addSlash(path) + part, exists)
    }
  }

  private literalSelector(part: string, parts: string[]): Selector {
    while (parts.length > 0 && !MAGIC_CHECK.test(parts[parts.length - 1])) {
      part += `\\${parts.pop() as string}`
    }
    const selectNext = this.selector(parts)
    return async function* (path) {
      yield* selectNext(addSlash(path) + part, false)
    }
  }

  private wildcardSelector(part: string, parts: string[]): Selector {
    const match = part === '*' ? null : compileMatcher(part)
    const dirOnly = parts.length > 0
    const selectNext = dirOnly ? this.selector(parts) : null
    return async function* (path) {
      const entries = await scandir(path)
      if (entries === null) return
      for (const entry of entries) {
        if (match !== null && !match(entry.name, 0)) continue
        const full = childPath(path, entry.name)
        if (!dirOnly) {
          yield full
          continue
        }
        if (!isDirNoFollow(entry)) continue
        yield* (selectNext as Selector)(full, true)
      }
    }
  }

  private recursiveSelector(first: string, parts: string[]): Selector {
    while (parts.length > 0 && parts[parts.length - 1] === '**') parts.pop()
    let part = first
    while (parts.length > 0 && !SPECIAL_PARTS.includes(parts[parts.length - 1])) {
      part += `\\${parts.pop() as string}`
    }
    const match = part === '**' ? null : compileMatcher(part)
    const dirOnly = parts.length > 0
    const selectNext = this.selector(parts)

    return async function* (path, exists) {
      const base = addSlash(path)
      const matchPos = base.length
      if (match === null || match(base, matchPos)) yield* selectNext(base, exists)
      const stack: string[] = [base]
      while (stack.length > 0) {
        const current = stack.pop() as string
        const entries = await scandir(current)
        if (entries === null) continue
        for (const entry of entries) {
          const full = childPath(current, entry.name)
          const isDir = await isDirFollowed(full, entry)
          if (isDir || !dirOnly) {
            if (match === null || match(full, matchPos)) {
              if (dirOnly) yield* selectNext(full, true)
              else yield full
            }
          }
          if (isDir) stack.push(full)
        }
      }
    }
  }
}

async function* selectExists(path: string, exists: boolean): AsyncGenerator<string> {
  if (exists) {
    yield path
    return
  }
  try {
    await lstat(path)
    yield path
  } catch {}
}

async function scandir(path: string): Promise<Dirent[] | null> {
  try {
    return await readdir(path, { withFileTypes: true })
  } catch {
    return null
  }
}

function isDirNoFollow(entry: Dirent): boolean {
  return entry.isDirectory()
}

async function isDirFollowed(full: string, entry: Dirent): Promise<boolean> {
  if (entry.isDirectory()) return true
  if (!entry.isSymbolicLink()) return false
  try {
    return (await stat(full)).isDirectory()
  } catch {
    return false
  }
}

function addSlash(path: string): string {
  const tail = ntTail(path)
  if (!tail || tail.endsWith('\\') || tail.endsWith('/')) return path
  return `${path}\\`
}

function childPath(dir: string, name: string): string {
  return dir.endsWith('\\') || dir.endsWith('/') ? `${dir}${name}` : `${dir}\\${name}`
}

function ntTail(path: string): string {
  if (/^[A-Za-z]:/.test(path)) {
    const rest = path.slice(2)
    return rest.startsWith('\\') || rest.startsWith('/') ? rest.slice(1) : rest
  }
  if (path.startsWith('\\\\') || path.startsWith('//')) {
    const after = path.slice(2)
    const serverEnd = after.search(/[/\\]/u)
    if (serverEnd === -1) return ''
    const shareEnd = after.slice(serverEnd + 1).search(/[/\\]/u)
    if (shareEnd === -1) return ''
    return after.slice(serverEnd + 1 + shareEnd + 1)
  }
  if (path.startsWith('\\') || path.startsWith('/')) return path.slice(1)
  return path
}

function ntRootOf(pattern: string): string {
  const drive = /^[A-Za-z]:[/\\]/.exec(pattern)
  if (drive) return drive[0]
  if (pattern.startsWith('\\') || pattern.startsWith('/')) return pattern[0]
  return ''
}

function reverseParts(pattern: string): string[] {
  const names: string[] = []
  let path = pattern
  for (;;) {
    const [parent, name] = ntSplit(path)
    if (parent === path) break
    names.push(name)
    path = parent
  }
  return names
}

function ntSplit(path: string): [string, string] {
  const index = Math.max(path.lastIndexOf('\\'), path.lastIndexOf('/'))
  if (index === -1) return ['', path]
  return [path.slice(0, index).replace(/[/\\]+$/u, ''), path.slice(index + 1)]
}

export async function* pyGlob(root: string, pattern: string): AsyncGenerator<string> {
  if (ntRootOf(pattern)) {
    throw new PythonError('NotImplementedError', 'Non-relative patterns are unsupported')
  }
  yield* new Globber().selector(reverseParts(pattern))(root, false)
}

export interface ImageHeader {
  format: string
  width: number
  height: number
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]

function pngHeader(bytes: Buffer): ImageHeader | null {
  if (!PNG_SIGNATURE.every((value, index) => bytes[index] === value)) return null
  if (bytes.length < 29 || bytes.readUInt32BE(8) !== 13) return null
  if (bytes.toString('latin1', 12, 16) !== 'IHDR') return null
  return { format: 'PNG', width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20) }
}

const JPEG_SOF_MARKERS = new Set([
  0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf, 0xde
])

function jpegStandaloneMarker(marker: number): boolean {
  return marker === 0x00 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd9) || marker === 0xff
}

function jpegHeader(bytes: Buffer): ImageHeader | null {
  if (!(bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff)) return null
  let i = 2
  for (;;) {
    if (i >= bytes.length) return null
    if (bytes[i] !== 0xff) {
      i += 1
      continue
    }
    const marker = bytes[i + 1]
    i += 2
    if (jpegStandaloneMarker(marker)) continue
    if (i + 1 >= bytes.length) return null
    const length = bytes.readUInt16BE(i)
    if (length < 2) return null
    if (JPEG_SOF_MARKERS.has(marker)) {
      if (length < 7 || i + 7 > bytes.length) return null
      return { format: 'JPEG', width: bytes.readUInt16BE(i + 5), height: bytes.readUInt16BE(i + 3) }
    }
    if (marker === 0xda) return null
    i += length
  }
}

function gifHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 10) return null
  const version = bytes.toString('latin1', 0, 6)
  if (version !== 'GIF87a' && version !== 'GIF89a') return null
  return { format: 'GIF', width: bytes.readUInt16LE(6), height: bytes.readUInt16LE(8) }
}

const DIB_HEADER_SIZES = [12, 40, 52, 56, 64, 108, 124]

const BMP_BIT_DEPTHS = new Set([1, 4, 8, 16, 24, 32])

function dibInfo(bytes: Buffer, at: number): { width: number; height: number } | null {
  if (at < 0 || at + 4 > bytes.length) return null
  const size = bytes.readUInt32LE(at)
  if (!DIB_HEADER_SIZES.includes(size)) return null
  const data = at + 4
  if (data + size - 4 > bytes.length) return null
  if (size === 12) {
    const bits = bytes.readUInt16LE(data + 6)
    if (!BMP_BIT_DEPTHS.has(bits)) return null
    return { width: bytes.readUInt16LE(data), height: bytes.readUInt16LE(data + 2) }
  }
  const flipped = bytes[data + 7] === 0xff
  const height = bytes.readUInt32LE(data + 4)
  const bits = bytes.readUInt16LE(data + 10)
  if (!BMP_BIT_DEPTHS.has(bits)) return null
  return { width: bytes.readUInt32LE(data), height: flipped ? 2 ** 32 - height : height }
}

function bmpHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 14 || bytes.toString('latin1', 0, 2) !== 'BM') return null
  const info = dibInfo(bytes, 14)
  return info ? { format: 'BMP', ...info } : null
}

function rawDibHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 4) return null
  if (!DIB_HEADER_SIZES.includes(bytes.readUInt32LE(0))) return null
  const info = dibInfo(bytes, 0)
  return info ? { format: 'DIB', ...info } : null
}

function icoHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 6) return null
  if (!(bytes[0] === 0 && bytes[1] === 0 && bytes[2] === 1 && bytes[3] === 0)) return null
  const count = bytes.readUInt16LE(4)
  if (bytes.length < 6 + count * 16) return null
  const entries: { width: number; height: number; depth: number }[] = []
  for (let i = 0; i < count; i++) {
    const at = 6 + i * 16
    const width = bytes[at] || 256
    const height = bytes[at + 1] || 256
    const colors = bytes[at + 2]
    const bpp = bytes.readUInt16LE(at + 6)
    entries.push({
      width,
      height,
      depth: bpp || (colors !== 0 ? Math.ceil(Math.log2(colors)) : 0) || 256
    })
  }
  if (entries.length === 0) return null
  const winner = entries.reduce((top, entry) =>
    entry.width * entry.height > top.width * top.height ||
    (entry.width * entry.height === top.width * top.height && entry.depth < top.depth)
      ? entry
      : top
  )
  return { format: 'ICO', width: winner.width, height: winner.height }
}

function curHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 6) return null
  if (!(bytes[0] === 0 && bytes[1] === 0 && bytes[2] === 2 && bytes[3] === 0)) return null
  const count = bytes.readUInt16LE(4)
  if (bytes.length < 6 + count * 16) return null
  let chosen = -1
  for (let i = 0; i < count; i++) {
    const at = 6 + i * 16
    if (chosen < 0 || (bytes[at] > bytes[chosen] && bytes[at + 1] > bytes[chosen + 1])) chosen = at
  }
  if (chosen < 0) return null
  const bitmap = dibInfo(bytes, bytes.readUInt32LE(chosen + 12))
  if (!bitmap) return null
  return { format: 'CUR', width: bitmap.width, height: Math.floor(bitmap.height / 2) }
}

const TIFF_PREFIXES = ['II*\u0000', 'MM\u0000*']

function tiffHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 8) return null
  const prefix = bytes.toString('latin1', 0, 4)
  if (!TIFF_PREFIXES.includes(prefix)) return null
  const bigEndian = prefix.startsWith('MM')
  const u16 = (at: number): number => (bigEndian ? bytes.readUInt16BE(at) : bytes.readUInt16LE(at))
  const u32 = (at: number): number => (bigEndian ? bytes.readUInt32BE(at) : bytes.readUInt32LE(at))
  const ifd = u32(4)
  if (ifd + 2 > bytes.length) return null
  const entries = u16(ifd)
  let width: number | null = null
  let height: number | null = null
  let orientation = 1
  for (let i = 0; i < entries; i++) {
    const at = ifd + 2 + i * 12
    if (at + 12 > bytes.length) return null
    const tag = u16(at)
    const type = u16(at + 2)
    if ((tag !== 256 && tag !== 257 && tag !== 274) || u32(at + 4) !== 1) continue
    const value = type === 3 ? u16(at + 8) : type === 4 ? u32(at + 8) : null
    if (value === null) continue
    if (tag === 256) width = value
    else if (tag === 257) height = value
    else orientation = value
  }
  if (width === null || height === null) return null
  if (orientation >= 5 && orientation <= 8) return { format: 'TIFF', width: height, height: width }
  return { format: 'TIFF', width, height }
}

function webpHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 16) return null
  if (bytes.toString('latin1', 0, 4) !== 'RIFF' || bytes.toString('latin1', 8, 12) !== 'WEBP')
    return null
  const kind = bytes.toString('latin1', 12, 16)
  if (kind === 'VP8 ') {
    if (bytes.length < 30 || bytes.readUInt32LE(16) < 10) return null
    if (!(bytes[23] === 0x9d && bytes[24] === 0x01 && bytes[25] === 0x2a)) return null
    return {
      format: 'WEBP',
      width: bytes.readUInt16LE(26) & 0x3fff,
      height: bytes.readUInt16LE(28) & 0x3fff
    }
  }
  if (kind === 'VP8L') {
    if (bytes.length < 25 || bytes.readUInt32LE(16) < 5) return null
    if (bytes[20] !== 0x2f) return null
    const bits = bytes.readUInt32LE(21)
    return { format: 'WEBP', width: (bits & 0x3fff) + 1, height: ((bits >> 14) & 0x3fff) + 1 }
  }
  if (kind === 'VP8X') {
    if (bytes.length < 30 || bytes.readUInt32LE(16) < 10) return null
    return {
      format: 'WEBP',
      width: bytes.readUIntLE(24, 3) + 1,
      height: bytes.readUIntLE(27, 3) + 1
    }
  }
  return null
}

const WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0b, 0x0c, 0x0d])
const PPM_MODES = ['P1', 'P2', 'P3', 'P4', 'P5', 'P6']

function ppmTokens(bytes: Buffer, from: number, wanted: number): { values: number[]; ok: boolean } {
  const values: number[] = []
  let i = from
  while (values.length < wanted) {
    let token = ''
    while (token.length <= 10 && i < bytes.length) {
      const byte = bytes[i]
      i += 1
      if (WHITESPACE.has(byte)) {
        if (token.length > 0) break
        continue
      }
      if (byte === 0x23) {
        while (i < bytes.length && bytes[i] !== 0x0a && bytes[i] !== 0x0d) i += 1
        continue
      }
      token += String.fromCharCode(byte)
    }
    if (token.length === 0 || token.length > 10) return { values: [], ok: false }
    if (!/^[+-]?\d+$/.test(token)) return { values: [], ok: false }
    values.push(Number.parseInt(token, 10))
  }
  return { values, ok: true }
}

function ppmHeader(bytes: Buffer): ImageHeader | null {
  if (bytes.length < 2) return null
  let magic = ''
  let i = 0
  while (i < 6 && i < bytes.length && !WHITESPACE.has(bytes[i])) {
    magic += String.fromCharCode(bytes[i])
    i += 1
  }
  if (!PPM_MODES.includes(magic)) return null
  const size = ppmTokens(bytes, i, 2)
  if (!size.ok) return null
  if (magic !== 'P1' && magic !== 'P4') {
    const maxval = ppmTokens(bytes, i, 3)
    if (!maxval.ok || !(maxval.values[2] > 0 && maxval.values[2] < 65536)) return null
  }
  return { format: 'PPM', width: size.values[0], height: size.values[1] }
}

const READERS: ((bytes: Buffer) => ImageHeader | null)[] = [
  pngHeader,
  jpegHeader,
  gifHeader,
  bmpHeader,
  rawDibHeader,
  icoHeader,
  curHeader,
  tiffHeader,
  webpHeader,
  ppmHeader
]

export function readImageHeader(bytes: Buffer): ImageHeader | null {
  for (const reader of READERS) {
    try {
      const header = reader(bytes)
      if (header) return header
    } catch {}
  }
  return null
}

import { mkdir, stat } from 'fs/promises'
import { dirname } from 'path'

import { PythonError } from '../../shared/utils/exceptions'

export function fileNotFound(path: string): PythonError {
  return new PythonError('FileNotFoundError', `[Errno 2] No such file or directory: '${path}'`)
}

export function statNotFoundWinError2(path: string): PythonError {
  return new PythonError(
    'FileNotFoundError',
    `[WinError 2] The system cannot find the file specified: '${path}'`
  )
}

export function diskUsageNotFound(path: string): PythonError {
  return new PythonError(
    'FileNotFoundError',
    `[WinError 3] The system cannot find the path specified: '${path}'`
  )
}

export function permissionDenied(path: string): PythonError {
  return new PythonError('PermissionError', `[Errno 13] Permission denied: '${path}'`)
}

export function fileExistsWin183(path: string): PythonError {
  return new PythonError(
    'FileExistsError',
    `[WinError 183] Cannot create a file when that file already exists: '${path}'`
  )
}

export function osError(error: unknown, path: string): PythonError {
  const failure = error as NodeJS.ErrnoException | null
  const at = typeof failure?.path === 'string' && failure.path !== '' ? failure.path : path
  const code = failure?.code
  if (code === 'ENOENT') return fileNotFound(at)
  if (code === 'EEXIST') return fileExistsWin183(at)
  return permissionDenied(at)
}

export async function mkdirParents(dir: string): Promise<void> {
  try {
    await mkdir(dir, { recursive: true })
    return
  } catch {}
  let current = dir
  for (;;) {
    const info = await stat(current).catch(() => null)
    if (info && !info.isDirectory()) throw fileExistsWin183(current)
    const parent = dirname(current)
    if (parent === current) break
    current = parent
  }
  throw fileNotFound(dir)
}

import { useEffect, useRef, useState, type CSSProperties } from 'react'

import { pySlice, pyStrip } from '@shared/utils/pystr'
import type { RendererState } from '@renderer/state/window-store'
import type { WindowCommand } from '@shared/types/window'

// Drag floor, in --u units: the .btn-box stack is Send 32u + 4u gap + Stop 24u, so the
// textarea can never shrink past the buttons it sits beside.
const MIN_HEIGHT_UNITS = 60
const CHROME_PX = 380

interface Props {
  state: RendererState
  send: (command: WindowCommand) => void
}

/** Maximum characters to show in queue preview */
const QUEUE_PREVIEW_LENGTH = 60

export default function InputDock({ state, send }: Props): React.JSX.Element {
  const [text, setText] = useState(state.input.text)
  const [heightUnits, setHeightUnits] = useState<number | null>(null)
  const [dragging, setDragging] = useState(false)
  const [editingIndex, setEditingIndex] = useState<number | null>(null)
  const boxRef = useRef<HTMLTextAreaElement | null>(null)
  const dragRef = useRef<{ y: number; units: number } | null>(null)
  const scale = state.fontScale.scale

  /* eslint-disable react-hooks/set-state-in-effect */
  useEffect(() => {
    setText(state.input.text)
    if (state.input.focus) boxRef.current?.focus()
  }, [state.input])
  /* eslint-enable react-hooks/set-state-in-effect */

  const submit = (): void => {
    if (editingIndex !== null) {
      // Saving an in-progress queue edit
      const msg = pyStrip(text)
      if (msg) {
        send({ cmd: 'queue-edit', index: editingIndex, text: msg })
      }
      setEditingIndex(null)
      setText('')
      return
    }
    // Always send as 'send'; the main process decides whether to send immediately
    // or add to the queue based on isGenerating.
    const msg = pyStrip(text)
    if (msg) {
      send({ cmd: 'send', text: msg })
    }
  }

  const startDrag = (event: React.PointerEvent<HTMLDivElement>): void => {
    const box = boxRef.current
    if (box === null) return
    dragRef.current = { y: event.clientY, units: box.getBoundingClientRect().height / scale }
    event.currentTarget.setPointerCapture(event.pointerId)
    event.preventDefault()
    setDragging(true)
  }

  const moveDrag = (event: React.PointerEvent<HTMLDivElement>): void => {
    const start = dragRef.current
    if (start === null) return
    const min = MIN_HEIGHT_UNITS
    const max = Math.max(min, (window.innerHeight - CHROME_PX) / scale)
    const next = start.units + (start.y - event.clientY) / scale
    setHeightUnits(Math.min(max, Math.max(min, next)))
  }

  const endDrag = (event: React.PointerEvent<HTMLDivElement>): void => {
    if (dragRef.current === null) return
    dragRef.current = null
    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }
    setDragging(false)
  }

  const handleSendNow = (index: number): void => {
    send({ cmd: 'queue-send-now', index })
  }

  const handleEdit = (index: number): void => {
    setEditingIndex(index)
    setText(state.queue[index])
  }

  const handleDelete = (index: number): void => {
    send({ cmd: 'queue-delete', index })
  }

  const cancelEdit = (): void => {
    setEditingIndex(null)
    setText('')
  }

  const isEditing = (index: number): boolean => editingIndex === null ? false : editingIndex === index

  return (
    <div
      className={`input-dock${heightUnits === null ? '' : ' sized'}`}
      style={heightUnits === null ? undefined : ({ '--ih': String(heightUnits) } as CSSProperties)}
    >
      <div
        aria-orientation="horizontal"
        className={`input-resizer${dragging ? ' dragging' : ''}`}
        onDoubleClick={() => setHeightUnits(null)}
        onPointerCancel={endDrag}
        onPointerDown={startDrag}
        onPointerMove={moveDrag}
        onPointerUp={endDrag}
        role="separator"
        title="Drag to resize the input, double-click to reset"
      />
      {dragging ? <div className="input-drag-shield" /> : null}
      <div className="hint">
        {
          'Press Enter to send  •  Shift+Enter for newline  •  Type /command or !shell command directly'
        }
      </div>
      {state.queue.length > 0 && (
        <div className="queue-panel">
          <span className="queue-panel-header">Queue</span>
          <div className="queue-panel-list" style={{ maxHeight: `calc(${window.innerHeight - CHROME_PX - 80}px)` }}>
            {state.queue.map((msg, idx) => {
              const editing = isEditing(idx)
              return (
                <div
                  key={idx}
                  className="queue-item"
                >
                  <span className="queue-item-preview">{pySlice(msg, 0, QUEUE_PREVIEW_LENGTH)}...</span>
                  <div className="queue-item-actions">
                    {editing ? (
                      <>
                        <button
                          className="queue-btn queue-save"
                          onClick={(e) => {
                            e.stopPropagation()
                            submit()
                          }}
                          type="button"
                        >
                          ✓
                        </button>
                        <button
                          className="queue-btn queue-cancel"
                          onClick={(e) => {
                            e.stopPropagation()
                            cancelEdit()
                          }}
                          type="button"
                        >
                          ✕
                        </button>
                      </>
                    ) : (
                      <>
                        <button
                          className="queue-btn queue-send-now"
                          onClick={(e) => {
                            e.stopPropagation()
                            handleSendNow(idx)
                          }}
                          type="button"
                        >
                          ✓
                        </button>
                        <button
                          className="queue-btn queue-edit"
                          onClick={(e) => {
                            e.stopPropagation()
                            handleEdit(idx)
                          }}
                          type="button"
                        >
                          ✏️
                        </button>
                        <button
                          className="queue-btn queue-delete"
                          onClick={(e) => {
                            e.stopPropagation()
                            handleDelete(idx)
                          }}
                          type="button"
                        >
                          ✕
                        </button>
                      </>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
          {state.queue.length > 8 && (
            <span className="queue-scroll-hint">↑ Scrollable ({state.queue.length} messages)</span>
          )}
        </div>
      )}
      <div className="entry-row">
        <textarea
          aria-label="Message"
          className="input-text"
          onChange={(event) => setText(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter' && !event.shiftKey) {
              event.preventDefault()
              submit()
            }
          }}
          ref={boxRef}
          value={text}
        />
        <div className="btn-box">
          {editingIndex !== null ? (
            <>
              <button className="send-btn" onClick={submit} type="button">
                Save
              </button>
              <button className="stop-btn" onClick={cancelEdit} type="button">
                Cancel
              </button>
            </>
          ) : (
            <>
              <button className="send-btn" onClick={submit} type="button">
                Send
              </button>
              <button
                className="stop-btn"
                disabled={!state.isGenerating}
                onClick={() => send({ cmd: 'stop' })}
                type="button"
              >
                Stop
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'

import {
  CodeSnippet,
  DiffCard,
  GenericActionBody,
  TerminalCard
} from '@renderer/components/action-bodies'
import { Glyph, GlyphText } from '@renderer/components/icons'
import MarkdownBlocks from '@renderer/components/markdown-blocks'
import ThinkingRow from '@renderer/components/thinking-row'
import {
  DEFAULT_PADY,
  ERROR_PADY_AFTER_SEARCH,
  ERROR_PADY_BEFORE_SEARCH,
  actionHeader,
  actionIcon,
  assistantCopyText,
  assistantLooksLikeError,
  assistantSearchableText,
  payloadArray,
  payloadDict,
  payloadGet,
  payloadText,
  pillLooksLikeError,
  searchableText,
  statusColors,
  toolDisplayName,
  userSearchableText
} from '@renderer/state/card-model'
import type { ChatItem, RendererState } from '@renderer/state/window-store'
import { stripMarkdownMarkers } from '@shared/utils/text'
import { pyStrip, pySplitlines } from '@shared/utils/pystr'
import type { TimelineEventPayload } from '@shared/types/window'

export interface TimelineHandlers {
  copy: (text: string) => void
  copyPath: (rel: string) => void
  openFile: (rel: string) => void
  undo: () => void
  editUser: (rowId: number, text: string, cpIdx: number | null, dbId?: number) => void
  exportTimeline: () => void
  openApiKey: () => void
  loadOlder: () => void
  openConversation: (conversationId: string) => void
}

interface Props {
  state: RendererState
  handlers: TimelineHandlers
  children?: React.ReactNode
}

function pady(a: number, b: number): React.CSSProperties {
  return { marginBlock: `calc(${a} * var(--u)) calc(${b} * var(--u))` }
}

export default function Timeline({ state, handlers, children }: Props): React.JSX.Element {
  const [query, setQuery] = useState('')
  const [expanded, setExpanded] = useState<Record<number, boolean>>({})
  const [restyledErrors, setRestyledErrors] = useState<Set<number>>(new Set())
  const [autoScroll, setAutoScroll] = useState(true)
  const [showJump, setShowJump] = useState(false)
  const containerRef = useRef<HTMLDivElement | null>(null)

  useEffect(() => {
    if (!autoScroll) return
    const node = containerRef.current
    if (node === null) return
    const timer = setTimeout(() => {
      node.scrollTop = node.scrollHeight
    }, 50)
    return () => clearTimeout(timer)
  }, [state.revision, autoScroll])

  const onQueryChange = (value: string): void => {
    setQuery(value)
    setRestyledErrors((previous) => {
      const next = new Set(previous)
      for (const row of state.chat) if (row.type === 'error') next.add(row.id)
      return next
    })
  }

  const filter = query.trim().toLowerCase()
  const visible = (row: ChatItem): boolean => {
    if (filter === '') return true
    if (row.type === 'pill') return true
    if (row.type === 'error') return false
    const searchable =
      row.type === 'assistant'
        ? assistantSearchableText(row.meta, row.text)
        : row.type === 'user'
          ? userSearchableText(row.text)
          : row.type === 'action'
            ? searchableText(row.event)
            : ''
    return searchable.toLowerCase().includes(filter)
  }

  const toggle = (id: number): void =>
    setExpanded((previous) => ({ ...previous, [id]: !previous[id] }))

  const actionIds = state.chat.filter((row) => row.type === 'action').map((row) => row.id)
  const expandAll = (): void => setExpanded(Object.fromEntries(actionIds.map((id) => [id, true])))
  const collapseAll = (): void => setExpanded({})

  const onScroll = (): void => {
    const node = containerRef.current
    if (node === null) return
    const y1 = (node.scrollTop + node.clientHeight) / node.scrollHeight
    if (y1 < 0.98) {
      setAutoScroll(false)
      setShowJump(true)
    } else {
      setAutoScroll(true)
      setShowJump(false)
    }
    if (node.scrollTop < 40 && state.hasMoreHistory) handlers.loadOlder()
  }

  const jumpToLatest = (): void => {
    setAutoScroll(true)
    setShowJump(false)
    const node = containerRef.current
    if (node !== null) node.scrollTop = node.scrollHeight
  }

  return (
    <div className="chat-area">
      <div className="timeline-toolbar">
        <div className="tb-left">
          <span className="caption">TIMELINE</span>
          <button className="tb-btn expand" onClick={expandAll} type="button">
            Expand All
          </button>
          <button className="tb-btn collapse" onClick={collapseAll} type="button">
            Collapse All
          </button>
          <button className="tb-btn export" onClick={handlers.exportTimeline} type="button">
            Export
          </button>
          <button className="tb-btn api-key" onClick={handlers.openApiKey} type="button">
            API Key
          </button>
        </div>
        <div className="tb-right">
          <input
            aria-label="Search timeline"
            className="search-entry"
            onChange={(event) => onQueryChange(event.target.value)}
            placeholder="Search timeline..."
            value={query}
          />
        </div>
      </div>

      <div className="chat-container" onScroll={onScroll} ref={containerRef}>
        {state.chat.map((row) => (
          <TimelineRow
            expanded={expanded[row.id] === true}
            handlers={handlers}
            key={row.id}
            onToggle={() => toggle(row.id)}
            row={row}
            style={visible(row) ? padyFor(row, restyledErrors) : { display: 'none' }}
          />
        ))}
        {state.thinking !== null ? <ThinkingRow thinking={state.thinking} /> : null}
      </div>

      {showJump ? (
        <button
          className="jump-btn"
          onClick={jumpToLatest}
          style={{ left: '50%', top: '88%', transform: 'translate(-50%, -50%)' }}
          type="button"
        >
          <Glyph glyph="↓" />
          Jump to latest
        </button>
      ) : null}
      {children}
    </div>
  )
}

function padyFor(row: ChatItem, restyled: Set<number>): React.CSSProperties {
  if (row.type === 'error')
    return pady(...(restyled.has(row.id) ? ERROR_PADY_AFTER_SEARCH : ERROR_PADY_BEFORE_SEARCH))
  if (row.type === 'assistant' || row.type === 'user' || row.type === 'action')
    return pady(...DEFAULT_PADY[row.type])
  return pady(3, 3)
}

function TimelineRow({
  row,
  style,
  expanded,
  onToggle,
  handlers
}: {
  row: ChatItem
  style: React.CSSProperties
  expanded: boolean
  onToggle: () => void
  handlers: TimelineHandlers
}): React.JSX.Element {
  switch (row.type) {
    case 'assistant':
      return <AssistantRow row={row} style={style} handlers={handlers} />
    case 'user':
      return <UserRow row={row} style={style} handlers={handlers} />
    case 'pill':
      return <PillRow row={row} style={style} />
    case 'error':
      return <ErrorRow row={row} style={style} />
    case 'action':
      return (
        <ActionRow
          event={row.event}
          expanded={expanded}
          onToggle={onToggle}
          style={style}
          handlers={handlers}
        />
      )
  }
}

function AssistantRow({
  row,
  style,
  handlers
}: {
  row: Extract<ChatItem, { type: 'assistant' }>
  style: React.CSSProperties
  handlers: TimelineHandlers
}): React.JSX.Element {
  const isError = assistantLooksLikeError(row.text, row.meta)
  return (
    <div className="row-assistant" style={style}>
      <div className={`card card-assistant${isError ? ' is-error' : ''}`}>
        <div className="card-head">
          <span className="assistant-name">GemiBot AI</span>
