  'UI Scale: 12px (Small)',
  'UI Scale: 13px (Normal)',
  'UI Scale: 14px (Medium)',
  'UI Scale: 15px (Large)',
  'UI Scale: 16px (Extra Large)',
  'UI Scale: 18px (Huge)'
